// Generated by tools/property_data.py build. Edit canonical JSON in data/, not this file.
window.CULTIVAR_LIBRARY = {"schema_version":1,"unprofiled":{"61":"Ungrafted apple rootstock of unknown type, not a cultivar","62":"Unidentified apples; see UNIDENTIFIED_APPLES in orchard.json for the possibilities","71":"Unidentified apricot","81":"Unidentified sweet cherries","91":"Unidentified peaches"},"group_notes":[{"group":"Apple","habit":"Full-size apples often have twisting trunks and branches that start low, with many short fruiting spurs and, if unpruned, suckers along the trunk and in the crown. Crabapples mostly stay 6-25 ft, bear fruit up to 2 inches across, and some sucker heavily; Dolgo is listed near 40 ft. Columnar Urban apples are only 7-8 ft tall and 2-3 ft wide, with spurs along the trunk and no long side limbs.","bark":"Smooth when young, then thin and scaly; color varies. Crabapple bark is gray to brown, with narrow ridges that are scaly, and may peel. Fast-growing twigs are brown to gray and usually hairy, with plenty of spur shoots and plump buds covered in gray hairs.","leaf":"Alternate, oval to elliptical, 1.5-3 inches long, finely toothed, green above, with a paler underside and leaf stalk covered in white hairs; some leaves sit on spur shoots. Crabapple foliage is deep green, lighter below, and turns brown in fall.","sources":[["Virginia Tech Dendrology: Apple (Malus spp.) fact sheet","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=59"],["University of Minnesota UFOR Nursery: Crabapple (Malus spp.)","https://trees.umn.edu/crabapple-malus-spp"],["University of Nebraska-Lincoln Extension: Columnar Apples","https://lancaster.unl.edu/columnar-apples-growing-fruits-small-home-orchard/"]],"reviewed_on":"2026-10-17"},{"group":"Pear","habit":"Usually upright and cone-shaped, with branches leaving the trunk at tight angles, about 30-40 ft tall. Branches are stubby and crowded with fruiting spurs that often carry thorns. Perry pears can grow into big, long-lived trees; those in England's perry country can live over 300 years.","bark":"Gray-brown to reddish-brown, smooth at first, later cracking into shallow furrows with scaly ridges. Twigs are glossy and smooth to faintly downy, brown to yellow-green, with plenty of spur shoots; buds are sharp-pointed cones, smooth to lightly hairy.","leaf":"Oval with fine teeth, about 1-4 inches long, glossy dark green on top and paler and duller underneath. Pear leaves are glossier, with thinner blades and fewer hairs than apple leaves, though young leaves may carry long white hairs. Fall color ranges from dull yellow through red to maroon.","sources":[["Virginia Tech Dendrology: Common pear (Pyrus communis) fact sheet","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=369"],["Utah State University Extension TreeBrowser: Pear, Common","https://extension.usu.edu/treebrowser/catalog/pear-common"],["Three Counties Agricultural Society: National Collection of Perry Pears","https://threecounties.co.uk/national-collection-of-perry-pears/"]],"reviewed_on":"2026-10-17"},{"group":"Cherry","habit":"Sweet cherry grows into a small-to-medium tree up to about 50 ft, its crown wide and rounded, with fruit clustered on spurs. Tart cherry (Montmorency) is smaller, usually to 30 ft, also rounded. Nanking cherry clearly differs: a wide-spreading, bushy shrub with dense fine twigs, only 6-8 ft high and wide.","bark":"Sweet cherry bark is gray-brown and smooth, with bold long horizontal lenticels, and tends to peel; twigs are gray-brown with large reddish-brown buds and clustered terminal buds on spurs. Tart cherry bark runs red to gray-brown, closely fitting and a little rough, with horizontal lenticels. Nanking cherry bark is glossy reddish-brown and peels away.","leaf":"Sweet cherry leaves run 2-5 inches in length, oval but broadest above the middle, with rounded teeth and obvious dark glands on the leaf stalk; they usually show over 8 vein pairs, tart cherry fewer than 8. Nanking cherry leaves are shorter (2-3 inches), toothed and roughly veined.","sources":[["Virginia Tech Dendrology: Sweet cherry (Prunus avium) fact sheet","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=63"],["Virginia Tech Dendrology: Sour cherry (Prunus cerasus) fact sheet","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=860"],["The Morton Arboretum: Nanking cherry","https://mortonarb.org/plant-and-protect/trees-and-plants/nanking-cherry/"]],"reviewed_on":"2026-10-17"},{"group":"Peach","habit":"Small, quick-growing tree, roughly 15-25 ft high and as broad, with a spreading, rounded crown whose branches angle upward. It tends to form several trunks unless trained to one, and needs pruning to keep a strong framework.","bark":"Young bark is dark gray, smooth and marked with elongated lenticels; with age it splits and flakes unevenly. New twigs are red and green, aging to gray-brown, hairless with conspicuous lenticels, and bear short spur shoots.","leaf":"Long, narrow and lance-shaped, 3-6 inches by about 1 inch, finely toothed and hairless, glossy deep green on top and lighter underneath, often curving along the midrib. The short leaf stalk bears glands. Leaves usually turn yellow in fall.","sources":[["Virginia Tech Dendrology: Peach (Prunus persica) fact sheet","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=309"],["Utah State University Extension TreeBrowser: Peach","https://extension.usu.edu/treebrowser/catalog/peach"],["NC State Extension Plant Toolbox: Prunus persica (peach)","https://plants.ces.ncsu.edu/plants/prunus-persica/"]],"reviewed_on":"2026-10-17"},{"group":"Apricot","habit":"Small to medium tree, about 15-40 ft high and as broad, with a dense, wide canopy and branches that begin near the ground. It also throws up suckers. Flowers open very early and are prone to frost damage, and the tree needs regular pruning.","bark":"Bark color varies widely: reddish-brown, dark brown, gray or nearly black, with fissures developing with age. Twigs and thin branches are reddish-brown, with conspicuous lenticels lined up in rows.","leaf":"Broadly oval, clearly wider than a peach leaf, about 2-3.5 inches long and 1.5-3 inches wide; base rounded, tip pointed, edges finely toothed.","sources":[["Utah State University Extension TreeBrowser: Apricot","https://extension.usu.edu/treebrowser/catalog/apricot"],["NC State Extension Plant Toolbox: Prunus armeniaca (apricot)","https://plants.ces.ncsu.edu/plants/prunus-armeniaca/"],["Yale Nature Walk: Apricot (Prunus armeniaca)","https://naturewalk.yale.edu/trees/rosaceae/prunus-armeniaca/apricot-65"]],"reviewed_on":"2026-10-17"},{"group":"Plum","habit":"Grows as a big shrub or a small tree, typically up to 10-20 ft tall, and may carry some spines. Italian prune is a European plum (Prunus domestica), the latest-blooming type of plum.","bark":"Bark ranges from shiny silver-gray to dark brown and shows conspicuous horizontal lenticels. Twigs are shiny and purplish, ridged, turning brown with age, and carry small buds covered in overlapping scales.","leaf":"Oval or teardrop-shaped, about 2 inches long, with a blunt or short-pointed tip and small teeth; smooth on top, sometimes downy underneath. The hairy leaf stalk often carries two yellow-green glands.","sources":[["Utah State University Extension TreeBrowser: Plum, Common","https://extension.usu.edu/treebrowser/catalog/plum-common"],["NC State Extension Plant Toolbox: Prunus domestica (common plum)","https://plants.ces.ncsu.edu/plants/prunus-domestica/"],["Woodland Trust: Plum (Prunus domestica)","https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/british-trees/a-z-of-british-trees/plum/"]],"reviewed_on":"2026-10-17"}],"records":[{"id":"apple-arkansas-black","group":"Apple","type":"Apple","kind":"cultivar","name":"Arkansas Black","aliases":["Arkansas Black Spur (FT015)","Arkansas Black Spur"],"inventory_rows":[26],"purchase_rows":[2],"tagline":"Very late; dark red-black; tart, firm, long keeper","summary":"Old Arkansas apple, probably a Winesap seedling, with glossy yellow skin that turns deep red to nearly black. Firm and tart at harvest, it turns softer and sweeter over months in cold storage.","appearance":"Medium, round to slightly conical fruit. Glossy yellow skin is washed red, deepening to dark purple-red on the sunny side and darker still in storage, when it turns waxy. Small pale dots. Flesh yellowish, fine-grained, very firm.","flavor_use":"Firm and sharp straight off the tree; after months in cold storage it turns softer, sweeter and spicier (Raintree suggests about 90 days). Eaten fresh once aged and used for pies, sauce and cider. Keeps around 5 months.","uses":["fresh","cooking","cider","storage"],"ripening":"Very late","ripening_note":"Early Nov per Raintree; about Oct 20 near Madison, Wisconsin per Lapacek's Orchard","id_cues":"Medium, round-conic fruit with glossy yellow skin mostly washed deep red to purple-black, darkening and turning waxy in storage; small pale dots. Late harvest. Vigorous, upright-spreading tree with long, slender branches. Color is weaker on shaded fruit.","habit":"Moderately vigorous to vigorous, medium-sized, stocky tree; upright-spreading and rather open, with long slender branches. Old orchard books call it a shy bearer, while one nursery calls it a reliable producer.","bark":"Twigs short and stout with short internodes; twig bark dark red-brown, blotched with scarf-skin and downy. Lenticels small, round, scattered; buds large, broad, pointed, pressed to the twig. Wood described as dark.","leaf":"Leaves described as medium in size in an old pomology account; shape, color and gloss are not described.","hardiness":"Zone 5 per Raintree","sources":[["Pomiferous: Arkansas Black apple","https://pomiferous.com/applebyname/arkansas-black-id-328"],["Raintree Nursery: Arkansas Black Apple","https://raintreenursery.com/products/arkansas-black-apple-semi-dwarf"],["Lapacek's Orchard: Apple varieties and approximate ripening dates","https://www.lapaceksorchard.com/post/apple-varieties-and-approximate-ripening-dates"],["Heritage Apple Corps: Arkansas Black apple","https://heritageapplecorps.org/varieties/arkansas-black-apple/"]],"basis":"sourced","note":"Bought as a spur-type strain; notes cover Arkansas Black in general. Pomiferous lists it as triploid with sterile pollen, so it cannot pollinate other apples and needs pollen from nearby trees. It suits long growing seasons.","reviewed_on":"2026-10-17"},{"id":"apple-braeburn","group":"Apple","type":"Apple","kind":"cultivar","name":"Braeburn","aliases":["Braeburn Dwarf"],"inventory_rows":[27],"purchase_rows":[7,8],"tagline":"Late; red-orange streaks; crisp, tangy-sweet","summary":"New Zealand apple with red-orange streaks over green-yellow skin. Crisp and very juicy, with a sharp, refreshing flavor balanced by sweetness, and it stores well.","appearance":"Medium to large, taller than wide. Red-orange streaks over a green-yellow ground, a bi-colored apple.","flavor_use":"Crisp without being hard, very juicy, with a sharp, refreshing flavor balanced by sweetness and never sugary. Snaps cleanly when bitten; stores well.","uses":["fresh","storage"],"ripening":"Late","ripening_note":"Typically October","id_cues":"Bi-colored fruit with red-orange streaks over green-yellow that ripens late in the season. Cut one open: very juicy with a clean snap.","habit":"Growth is strong until it starts cropping, then slows to moderate. Spreading, spur-bearing, early and heavy cropper. The central leader throws many branches and needs top thinning to stay dominant. May bear biennially unless thinned. Said to stay smaller than Gala or Fuji on the same rootstock.","bark":null,"leaf":null,"hardiness":"","sources":[["Orange Pippin: Braeburn","https://www.orangepippin.com/varieties/apples/braeburn"],["Albemarle CiderWorks: Braeburn","https://www.albemarleciderworks.com/orchard/apple/braeburn"],["Silver Creek Nursery: Braeburn apple tree","https://silvercreeknursery.ca/products/braeburn-apple"]],"basis":"general","note":"Fruit size and ripening timing come from general descriptions; the listed page covers bi-coloring, flavor and storage.","reviewed_on":"2026-10-17"},{"id":"apple-campfield","group":"Apple","type":"Apple","kind":"cultivar","name":"Campfield","aliases":["Campfield Cide","Campfield Cider Apple"],"inventory_rows":[28],"purchase_rows":[9],"tagline":"Very late; red-striped; bittersweet Newark cider apple","summary":"Old New Jersey cider apple, medium to large and red-striped over greenish-yellow. Sweet, firm white flesh gives a low-acid, high-tannin juice for traditional Newark-style cider; not meant for fresh eating.","appearance":"Medium to large and round, somewhat flattened. Greenish-yellow skin with a red blush and brick-red stripes, denser on the sunny side, with small pale or russet dots. Flesh white, firm and fine-grained.","flavor_use":"Flesh tastes rich and very sweet with a dry finish. The juice is low in acid and high in tannin (bittersweet), pressed alone or blended, traditionally with Harrison crab. Not recommended for fresh eating. Keeps about 2 months.","uses":["cider"],"ripening":"Very late","ripening_note":"Early Nov per Raintree; Raintree and Cummins both say it ripens late","id_cues":"Flattened, medium-large fruit, greenish-yellow with a red blush and brick-red stripes, small pale dots. Large, usually closed calyx in a shallow basin; short stout stem in a deep, narrow cavity. Very late ripening on a large, vigorous tree. Stripes alone are a weak cue.","habit":"Large, vigorous to very vigorous tree with straight limbs, called spreading or upright-spreading. Hardy and healthy but prone to overbear and slip into biennial bearing, so it needs careful thinning and pruning.","bark":"Twigs are long, fairly thin and pale in color; wood described as hard. Trunk bark is not described in the sources.","leaf":null,"hardiness":"Zone 4 per Raintree","sources":[["Pomiferous: Campfield apple","https://pomiferous.com/applebyname/campfield-id-6973"],["Raintree Nursery: Campfield Cider Apple","https://raintreenursery.com/products/campfield-cider-apple-semi-dwarf"],["Cummins Nursery: Campfield apple","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=21726"],["Heritage Apple Corps: Campfield apple","https://heritageapplecorps.org/varieties/campfield-apple/"],["Trees of Antiquity: Campfield apple tree","https://www.treesofantiquity.com/products/campfield-apple-tree"]],"basis":"sourced","note":"Pomiferous warns that not every tree sold as Campfield is true to type, and says two strains are grown in North America. It is self-sterile and needs a different mid-season-blooming apple nearby.","reviewed_on":"2026-10-17"},{"id":"apple-cortland","group":"Apple","type":"Apple","kind":"cultivar","name":"Cortland","aliases":[],"inventory_rows":[29],"purchase_rows":[10],"tagline":"Mid; red-streaked; white flesh slow to brown","summary":"McIntosh-type apple, larger than McIntosh, with crisp paper-white flesh that is slow to brown once cut. Juicy and mildly tart, good fresh, in salads and in pies.","appearance":"Medium to large, larger than McIntosh. Typically deep red streaks and flush over a green-yellow ground, with thin skin and paper-white flesh.","flavor_use":"Juicy, tart-sweet but not sharp, in the McIntosh style, and best soon after picking because flavor and crispness fade. Slices stay white, so it suits salads; also pies and sauce.","uses":["fresh","cooking"],"ripening":"Mid","ripening_note":"Late September to early October, after McIntosh","id_cues":"Looks like a larger, brighter McIntosh. Cut one open: the flesh stays white far longer than most apples. Ripens a week or two after McIntosh.","habit":"Vigorous, tall tree that is upright and spreading. Bears young and annually, with heavy crops, so early fruit is removed to protect growth. Fruit hangs well on the tree after ripening.","bark":"Old wood is described as having dark red bark (one orchard account).","leaf":"Leaves are flat with the midrib curving the reverse way; the same orchard account describes the tips as light green and the surface as dull and rough.","hardiness":"","sources":[["Orange Pippin: Cortland","https://www.orangepippin.com/varieties/apples/cortland"],["UMass Center for Agriculture, Food, and the Environment: Cortland","https://www.umass.edu/agriculture-food-environment/fruit/cortland"],["Fedco Trees: Cortland apple","https://fedcoseeds.com/trees/cortland-apple-7863"],["Albemarle CiderWorks: Cortland","https://www.albemarleciderworks.com/orchard/apple/cortland"]],"basis":"general","note":"Skin color and ripening timing come from general descriptions; the listed pages cover the flesh, flavor and McIntosh heritage.","reviewed_on":"2026-10-17"},{"id":"apple-cox-orange-pippin","group":"Apple","type":"Apple","kind":"cultivar","name":"Cox's Orange Pippin","aliases":["Cox Orange Pippin"],"inventory_rows":[30],"purchase_rows":[11],"tagline":"Mid; orange-red flush; aromatic, sweet-tart; fussy","summary":"Old English dessert apple: yellow-green with an orange-red flush and a complex, aromatic flavor. The tree is fussy, wanting a dry climate, and is prone to scab and mildew.","appearance":"Medium, round to slightly conical. Yellow-green to golden skin with an orange-red blush and broken red stripes; stem cavity russeted, with rays onto the shoulder. Flesh cream, fine-grained and firm.","flavor_use":"Juicy and aromatic, sweet-tart at picking and sweeter after storage, with pear, melon and orange flavors. Mainly for fresh eating; also used in pies, preserves and cider. Keeps up to about 3 months while flavor improves, then crispness fades.","uses":["fresh","cooking","cider"],"ripening":"Mid","ripening_note":"Mid Sept to mid Oct per Cummins Nursery","id_cues":"Orange-red flush with broken stripes over yellow-green on a medium, slightly conical fruit. Russeted stem cavity with rays, often a fleshy bump beside the stem; seeds rattle in a fully ripe fruit. Blooms late.","habit":"Medium-sized, moderately vigorous tree with dense, slender branching; form called upright, upright-spreading, or often wider than tall. Tends toward biennial bearing and sun scald; old accounts favor dwarfing rootstock.","bark":"Twigs long to medium, slender, irregularly crooked; twig bark olive-green with reddish-brown blotches and light down. Many raised, oblong lenticels; buds small to medium, rounded, hairy. One nursery lists papery bark disease.","leaf":"Leaves small to medium and tend to be narrow; described as rather pale, wavy, folded upward and round-toothed.","hardiness":"Zones 4-8 per Stark Bro's","sources":[["Pomiferous: Cox's Orange Pippin apple","https://pomiferous.com/applebyname/coxs-orange-pippin-id-2133"],["Cummins Nursery: Cox's Orange Pippin apple","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=29706"],["Stark Bro's: Cox's Orange Pippin antique apple tree","https://www.starkbros.com/products/fruit-trees/apple-trees/coxs-orange-pippin-antique-apple"],["Heritage Apple Corps: Cox Orange apple","https://heritageapplecorps.org/varieties/cox-orange-apple/"]],"basis":"sourced","note":"Pomiferous and Cummins both call it hard to grow: disease-prone (scab, mildew, canker) and fussy about site and climate.","reviewed_on":"2026-10-17"},{"id":"apple-dolgo","group":"Apple","type":"Crabapple","kind":"cultivar","name":"Dolgo crabapple","aliases":["Crabapple, Dolgo","Dolgo"],"inventory_rows":[31],"purchase_rows":[13],"tagline":"Early crab; crimson, oblong; tart, white bloom","summary":"Hardy Siberian-type crabapple with small crimson, oblong fruit that is tart and juicy and makes ruby-red jelly. Covered in white flowers every spring and an early ripener.","appearance":"Small crabapple, about 1 inch. Crimson to purple-red skin, round-conical to oblong (Dolgo means long), sometimes with a waxy bloom; cream to yellow flesh.","flavor_use":"Tart, juicy and acidic, tasting like candied cranberry when eaten fresh. Used for jelly and sauce, and adds a bitter-sharp note to cider; stores poorly.","uses":["jelly","cider","cooking"],"ripening":"Early","ripening_note":"About September; Montana State lists a mid-season harvest","id_cues":"Oblong, olive-shaped crimson crab about an inch long on a vigorous, very hardy tree, with a heavy white bloom early in spring (bloom group 2).","habit":"Vigorous, large, very hardy crabapple of upright, spreading form; size reports vary but are often 25-30 ft tall by 30-40 ft wide. Blooms early to mid season with large white flowers. One nursery calls cropping steady, while a Utah arboretum says it flowers well mainly in alternate years.","bark":null,"leaf":"Green, alternate, elliptical leaves with toothed edges, roughly 2-4 in long.","hardiness":"Hardy to zone 3","sources":[["Raintree Nursery: Dolgo Crabapple","https://raintreenursery.com/products/dolgo-crabapple-dwarf"],["Montana State University WARC: Dolgo identification","https://agresearch.montana.edu/warc/guides/apples/heritage_orchard_management_guide/heritage-fruit-id-guide/apples_id_key/dolgoappleid.html"],["Fedco Trees: Dolgo crabapple","https://fedcoseeds.com/trees/dolgo-crabapple-7313"],["Utah State University Botanical Center: Dolgo Crabapple","https://extension.usu.edu/botanicalcenter/trees-of-varga-arboretum/dolgo-crabapple"]],"basis":"sourced","note":"Sources differ slightly on harvest time (Raintree early, Montana State mid).","reviewed_on":"2026-10-17"},{"id":"apple-kerr-crab","group":"Apple","type":"Crabapple","kind":"cultivar","name":"Kerr crabapple","aliases":["Crabapple, Kerr","Kerr Crab Seedling","Kerr Crab"],"inventory_rows":[32],"purchase_rows":[33],"tagline":"Mid; crimson-maroon crab; crisp, tart-sweet; keeps","summary":"Very hardy Prairie crabapple (Dolgo x Haralson) with deep crimson fruit about 1.75 in across. Crisp, juicy and tart-sweet; used fresh, for jelly, juice and canning, and it stores well.","appearance":"Fruit about 1.75 in (4-4.5 cm), oblong and slightly flattened, on a long stem. Cream-yellow skin nearly covered in crimson, later maroon, with a bluish bloom. Flesh yellow, often tinged red, very firm and crisp. White spring bloom is profuse.","flavor_use":"Tart but sweet with a rose-like scent, milder than Dolgo and better after some storage. Good fresh, cooked, canned, juiced or as jelly. Keeps 4 to 6 months cold and can hang on the tree into winter.","uses":["fresh","cooking","canning","jelly","juice","storage"],"ripening":"Mid","ripening_note":"Late Sept to early Oct per University of Saskatchewan fruit program","id_cues":"Named Kerr: crab-size fruit (about 1.75 in), oblong, deep crimson to maroon with a bluish bloom, long stem, yellow flesh tinged red; white spring bloom; fruit hangs into winter. Seedlings may look different, so these are not firm cues for your trees.","habit":"Moderately vigorous to vigorous tree with a broad, upright, rounded crown and sturdy branches set at wide angles; one nursery says upright and moderately spreading. Productive every year; fruit hangs late into winter.","bark":null,"leaf":null,"hardiness":"Very cold hardy; about -50 F per Cummins","sources":[["University of Saskatchewan Fruit Program: Kerr apple sheet","https://research-groups.usask.ca/fruit/documents/apples/Kerr.pdf"],["Cummins Nursery: Kerr apple","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=21352"],["eXtension (Penn State): Why can't I plant seeds from my apple?","https://apples.extension.org/why-cant-i-plant-seeds-from-my-apple/"],["T&T Seeds: Kerr crab apple tree","https://ttseeds.com/products/kerrcrabappletree"]],"basis":"sourced","note":"Your trees are seed-grown (Montana Fruit 'Kerr Crab Seedling'), not the named Kerr. Apple seedlings do not come true, so fruit size, color, flavor and bloom time may vary. Sources differ on how sweet Kerr is.","reviewed_on":"2026-10-17"},{"id":"apple-wickson-crab","group":"Apple","type":"Crabapple","kind":"cultivar","name":"Wickson crabapple","aliases":["Crabapple, Wickson","Wickson Crab"],"inventory_rows":[33],"purchase_rows":[44],"tagline":"Late; golf-ball red crab; very sweet, sharp; early bloom","summary":"Small California crabapple, about golf-ball size, yellow washed red. Intensely sweet-tart and spicy; used for jelly, snacking and cider blends, and its early, long bloom makes it a good pollen source.","appearance":"Very small to small, round to slightly conical. Yellow skin washed red on the sunny side with many pale dots; stem long and slender, reaching past the shoulders. Flesh pale, firm and juicy. Bloom is dense and white.","flavor_use":"Both sugary and sharp, with an intense, spicy flavor (tarter in cooler climates). Eaten fresh in small amounts, made into jelly (high in pectin), and pressed for juice or cider blends, where it adds sugar and acid. Keeps a few weeks to about 2 months.","uses":["fresh","jelly","cider","juice","pollinizer"],"ripening":"Late","ripening_note":"Late season, usually late Oct per Salt Spring Apple Co.; hangs well but is sensitive to rain","id_cues":"Golf-ball-size yellow-and-red crab with a slender stem longer than the shoulders and an open calyx; heavy white bloom comes early. Often mislabeled as Crimson Gold, a look-alike with a larger, flatter, brighter-colored fruit.","habit":"Small, vigorous, cold-hardy tree that bears every year, with heavy white spring bloom and fruit carried in clusters. Nursery heights of about 6-12 ft after 10 years apply to dwarf and semi-dwarf rootstocks.","bark":null,"leaf":null,"hardiness":"Zone 3 (-40 C) per Orange Pippin Trees","sources":[["Pomiferous: Wickson Crab apple","https://pomiferous.com/applebyname/wickson-crab-id-6690"],["Orange Pippin Trees: Wickson Crab crab apple trees","https://www.orangepippintrees.com/trees/crab-apple-trees/wickson-crab"],["Salt Spring Apple Company: Wickson","https://www.saltspringapplecompany.com/wickson"],["Cummins Nursery: Wickson Crab apple","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=32985"]],"basis":"sourced","note":"Parentage is unclear: Etter's patent names two crabs that are not known varieties. Sources differ on storage life (2-3 weeks to about 2 months). Not self-fertile.","reviewed_on":"2026-10-17"},{"id":"apple-crimson-crisp","group":"Apple","type":"Apple","kind":"cultivar","name":"Crimson Crisp","aliases":["CrimsonCrisp"],"inventory_rows":[34],"purchase_rows":[12],"tagline":"Mid; bright crimson; very crisp, honeyed; scab-immune","summary":"Modern scab-immune apple from the Purdue-Rutgers-Illinois program (Co-op 39). Medium, bright crimson over yellow, with very crisp, juicy flesh and a honeyed, aromatic flavor; mainly for fresh eating.","appearance":"Medium, round and slightly conical, sometimes slightly flat. Skin is bright crimson over yellow, purplish in the sun, thick and glossy, with many small dots. Flesh pale yellow, crisp and a little coarse.","flavor_use":"Very crisp and juicy, honey-like and aromatic with a caramel hint. Used mostly fresh and for juice; firm enough for baking. Keeps 3 months or more in a fridge or cold garage, though flavor fades somewhat.","uses":["fresh","cooking","juice","storage"],"ripening":"Mid","ripening_note":"Mid-Sept per Roots to Fruits; fruit holds on the tree for up to about 4 weeks","id_cues":"Uniform bright crimson, purplish in sun, over yellow on a medium, slightly conical fruit with many small dots and glossy, non-waxy skin. Hangs on the tree for weeks. Red color is shared with many apples, so it is a weak cue alone.","habit":"Upright, moderately vigorous tree with a rounded canopy; nurseries agree on this shape. Flower buds open deep purple before the bloom turns white. One nursery lists steady yields year after year.","bark":null,"leaf":null,"hardiness":"Zone 4-9 per Roots to Fruits","sources":[["Roots to Fruits Nursery: CrimsonCrisp Apple Tree","https://rootstofruitsnursery.com/products/crimsoncrisp"],["Cummins Nursery: CrimsonCrisp apple","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=30985"],["Orange Pippin Trees: CrimsonCrisp apple trees","https://www.orangepippintrees.com/trees/apple-trees/crimsoncrisp"],["Stark Bro's: CrimsonCrisp apple tree","https://www.starkbros.com/products/fruit-trees/apple-trees/crimsoncrisp-apple"]],"basis":"sourced","note":"Patented and trademarked (CrimsonCrisp, Co-op 39). Bloom group differs by source: 3 per Cummins and Orange Pippin Trees, 5 per Roots to Fruits, so confirm bloom timing before choosing a pollinizer.","reviewed_on":"2026-10-17"},{"id":"apple-crispin","group":"Apple","type":"Apple","kind":"cultivar","name":"Crispin (Mutsu)","aliases":["Crispin","Mutsu Crispin","Mutsu"],"inventory_rows":[35],"purchase_rows":[37],"tagline":"Late; big yellow-green; crisp, honeyed; triploid","summary":"Crispin is Mutsu under the name added in 1968 for European and North American sales; it is a Japanese Golden Delicious x Indo cross. Very large yellow-green, crisp, juicy fruit on a vigorous triploid tree.","appearance":"Very large, round-conical to oblong, often ribbed and lopsided. Smooth, waxy skin goes from green to golden yellow, often with a coppery blush on the sunny side. Flesh creamy white, dense, coarse and crisp.","flavor_use":"Crisp and very juicy with a sweet, honey-like taste and occasional anise notes. Used fresh, in pies and sauce (holds its shape when baked) and for juice. Keeps about 4 months cold, with flavor improving over the first month or two.","uses":["fresh","cooking","juice","storage"],"ripening":"Late","ripening_note":"October in Utah per USU; Cummins Nursery calls it the last major crop on its U-pick farm","id_cues":"Distinctly big, ribbed, often lopsided fruit with waxy green-to-gold skin, a coppery blush in sun and some russet around the stem cavity. Vigorous, large tree. Japanese bagged fruit turns yellow or pink; Red Mutsu is a separate red sport.","habit":"Vigorous, large triploid tree that needs extra space; crotches wide and strong. Bears young and heavily, more annually than Golden Delicious, but needs thinning; may need scoring to push low scaffold limbs.","bark":null,"leaf":null,"hardiness":"Zones 4-8 per Utah State Univ.","sources":[["Pomiferous: Mutsu apple (Crispin)","https://pomiferous.com/applebyname/mutsu-id-4443"],["Cummins Nursery: Mutsu apple","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=scion&id=36072"],["Utah State University: Fruit table - Apple (Varieties for Utah)","https://intermountainfruit.org/fruit-tables/apple"],["Heritage Apple Corps: Mutsu apple","https://heritageapplecorps.org/varieties/mutsu-apple/"]],"basis":"sourced","note":"Crispin and Mutsu are the same apple. Triploid: its pollen is sterile, so it cannot pollinate other apples and needs pollen from nearby trees.","reviewed_on":"2026-10-17"},{"id":"apple-golden-delicious","group":"Apple","type":"Apple","kind":"cultivar","name":"Golden Delicious","aliases":["Delicious, Golden"],"inventory_rows":[36],"purchase_rows":[21],"tagline":"Late; golden-green; sweet, mild honey; keeps well","summary":"Familiar yellow apple found as a West Virginia seedling in 1891 and taken up by Stark Bros. Sweet, mildly honeyed and crisp when ripened on the tree; a heavy bearer that stores for months.","appearance":"Medium to large, round-conical, sometimes oblong or slightly ribbed. Smooth skin greenish-yellow, turning golden as it ripens, with small russet dots and sometimes a faint red blush. Flesh creamy white, tender and crisp.","flavor_use":"Sweet, juicy and floral with a mild honey taste; pick fully ripe, since early-picked fruit does not show its flavor. Used fresh and in sauce and baking; slow to brown when cut. Keeps up to about 5 months in cold storage.","uses":["fresh","cooking","storage"],"ripening":"Late","ripening_note":"About Oct 11 near Madison, Wisconsin (Lapacek's Orchard); Sept-Oct in Utah per USU","id_cues":"Greenish-yellow turning gold, medium to large and round-conical, with raised russet dots, a long slender stem in a deep cavity and sometimes a faint red blush. Many yellow apples look alike, so these are weak cues; the tree is spreading, frost-tolerant and a heavy bearer.","habit":"Hardy, productive tree of medium to good vigor with sturdy crotches at wide angles; form called upright-roundish in one source, spreading in another. Bears young and heavily, from the trunk outward; thin to avoid biennial bearing.","bark":null,"leaf":null,"hardiness":"Zones 4-8 per Utah State Univ.","sources":[["Pomiferous: Golden Delicious apple","https://pomiferous.com/applebyname/golden-delicious-id-2984"],["Utah State University: Fruit table - Apple (Varieties for Utah)","https://intermountainfruit.org/fruit-tables/apple"],["Lapacek's Orchard: Apple varieties and approximate ripening dates","https://www.lapaceksorchard.com/post/apple-varieties-and-approximate-ripening-dates"],["Heritage Apple Corps: Golden Delicious apple","https://heritageapplecorps.org/varieties/golden-delicious-apple/"],["NC State Extension: Golden Delicious apple","https://plants.ces.ncsu.edu/plants/malus-domestica-golden-delicious/"]],"basis":"sourced","note":"Pomiferous lists it as self-fertile, though crops improve with a pollinizer. Thin heavily after fruit set or it can slip into biennial bearing; humid sites bring russet.","reviewed_on":"2026-10-17"},{"id":"apple-red-delicious","group":"Apple","type":"Apple","kind":"cultivar","name":"Red Delicious","aliases":["Delicious, Red"],"inventory_rows":[37],"purchase_rows":[40],"tagline":"Late; tall dark red; sweet, mild, crisp; five bumps","summary":"Widely grown dark-red apple found in Iowa about 1872: tall, conical and bumpy at the blossom end. Sweet, juicy and crisp but mild in flavor, with tough skin; mostly eaten fresh and stores about 4 months.","appearance":"Medium to large, round to tall conical, with five well-defined bumps at the blossom end. Smooth skin washed red to dark crimson and fairly tough. Flesh cream-colored, fine-textured, crisp and juicy.","flavor_use":"Sweet and juicy with a light crunch and a mild flavor with a faint melon note. Eaten fresh. Keeps up to about 4 months in cold storage.","uses":["fresh","storage"],"ripening":"Late","ripening_note":"About Oct 16, after a decent frost, near Madison, Wisconsin (Lapacek's Orchard)","id_cues":"Tall conical shape, five distinct bumps around the blossom end and smooth dark red skin. Many red sports (Starking, Red Chief, Red Spur and others) vary in color and in how conical they are, so color alone is a weak cue.","habit":"Vigorous, upright-growing tree; weak, narrow crotch angles are fairly typical (Oregon bulletin). The original Delicious it descends from is described as large and spreading, so strains may differ.","bark":null,"leaf":null,"hardiness":"Zone 4 per Pomiferous","sources":[["Pomiferous: Red Delicious apple","https://pomiferous.com/applebyname/red-delicious-id-8864"],["Orange Pippin: Red Delicious apple","https://www.orangepippin.com/varieties/apples/red-delicious"],["Lapacek's Orchard: Apple varieties and approximate ripening dates","https://www.lapaceksorchard.com/post/apple-varieties-and-approximate-ripening-dates"],["Heritage Apple Corps: Red Delicious apple","https://heritageapplecorps.org/varieties/red-delicious-apple/"],["Heritage Apple Corps: Delicious apple (original)","https://heritageapplecorps.org/varieties/delicious-apple/"]],"basis":"sourced","note":"Bought as plain Red Delicious at Lowe's; many red sports are sold under this name, so exact color and shape may differ from the typical description.","reviewed_on":"2026-10-17"},{"id":"apple-foxwhelp","group":"Apple","type":"Apple","kind":"cultivar","name":"Foxwhelp","aliases":["Foxwhelp Cider","Foxwhelp Cider Apple"],"inventory_rows":[39],"purchase_rows":[15],"tagline":"Late; crimson-striped; bittersharp cider apple","summary":"Old English bittersharp cider apple, red-striped with tart, very bitter, aromatic flesh. Trees sold in North America under this name are often a different apple, including Raintree's stock.","appearance":"English type: small to medium, round to flattened, irregularly ribbed. Yellowish skin washed bright crimson with dense red stripes, plus distinctive scab-like patches. Flesh yellowish with red staining, tender.","flavor_use":"Sharp, strongly bitter and very aromatic, with a musky note in the golden juice. Used only for hard cider, usually blended. Keeps about a month. Raintree's US look-alike gives amber, low-tannin, high-acid, fairly sweet juice.","uses":["cider"],"ripening":"Late","ripening_note":"Early to mid Oct for Raintree's US type; English type is picked over several weeks (Pomiferous)","id_cues":"English Foxwhelp: small to medium, ribbed, bright crimson with dense red stripes and scab-like patches, tightly closed calyx. Raintree's US 'Foxwhelp' is larger, about 3.5-4 in wide; fruit that big points to the look-alike, not the English apple.","habit":"English Foxwhelp, per old accounts: upright when young, becoming gnarled with age; slow growing and hardy, a shy, erratic bearer. US trees sold as Foxwhelp may be a different apple.","bark":null,"leaf":null,"hardiness":"Zone 5 per Raintree (US type)","sources":[["Pomiferous: Foxwhelp apple","https://pomiferous.com/applebyname/foxwhelp-id-8275"],["Raintree Nursery: Foxwhelp Cider Apple","https://raintreenursery.com/products/foxwhelp-cider-apple-semi-dwarf"],["Heritage Apple Corps: Foxwhelp apple","https://heritageapplecorps.org/varieties/foxwhelp-apple/"]],"basis":"sourced","note":"Raintree says its 'Foxwhelp' was DNA-tested and found misidentified (known as Sonoma or Geneva Foxwhelp, or Fauxwhelp), so your tree is probably that look-alike, not true English Foxwhelp.","reviewed_on":"2026-10-17"},{"id":"apple-franklin-cider","group":"Apple","type":"Apple","kind":"cultivar","name":"Franklin Cider","aliases":[],"inventory_rows":[40],"purchase_rows":[16],"tagline":"Late; russeted green-yellow; bittersharp cider apple","summary":"Modern cold-hardy cider apple found as a chance seedling in Franklin, Vermont, and released in 2017. Small to medium, russeted fruit with a high-sugar, high-tannin, bittersharp juice; sold by Stark Bro's.","appearance":"Small to medium, round to round-conical. Greenish-yellow skin heavily russeted, often with some red blush on the sunny side. Flesh white, crisp and juicy.","flavor_use":"Sweet with high acid and high tannin (bittersharp), making structured hard cider alone or in blends; sweet enough to eat fresh. Keeps under a month in cold storage, so press soon after picking.","uses":["cider","fresh"],"ripening":"Late","ripening_note":"Early to mid Oct per Stark Bro's (Zones 3B-7)","id_cues":"Small to medium, heavily russeted greenish-yellow apple, sometimes with a red blush; long slender stem and small closed calyx. Russet is common, so it is a weak cue. Vigorous, upright-spreading tree that blooms mid-season and bears annually.","habit":"Vigorous, upright-spreading tree of manageable size; blooms mid-season and is described as a reliable annual bearer. Very cold hardy.","bark":null,"leaf":null,"hardiness":"Zones 3B-7; cold hardy to -32 F per Stark Bro's","sources":[["Stark Bro's: Franklin Cider apple tree","https://www.starkbros.com/products/fruit-trees/apple-trees/franklin-cider-apple"],["Pomiferous: Mayo apple (Franklin Cider)","https://pomiferous.com/applebyname/franklin-cider-id-8551"],["Cummins Nursery: Franklin apple","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=23228"],["Fruit Tree Guy: Franklin apple tree (Franklin Cider)","https://fruittreeguy.com/product/franklin-apple-tree/"],["Roots to Fruits Nursery: Franklin Apple Tree","https://rootstofruitsnursery.com/products/franklin-apple-tree"]],"basis":"sourced","note":"Name clash: Pomiferous mentions a different Ohio-bred apple also called Franklin Cider Apple (2017), and says Stark Bro's sold the Vermont (Mayo) seedling. Sources differ on whether ripe fruit hangs (Stark) or drops (Pomiferous).","reviewed_on":"2026-10-17"},{"id":"apple-frequin-rouge","group":"Apple","type":"Apple","kind":"cultivar","name":"Frequin Rouge","aliases":["Frequin Rouge Cider Apple"],"inventory_rows":[41],"purchase_rows":[17],"tagline":"Mid; small red-striped; bittersweet French cider apple","summary":"Old French cider apple (Brittany or Normandy) with small, red-striped fruit and very bitter, tannic juice, used only for hard cider. Several types share the name, so the North American one is uncertain.","appearance":"Small to medium, round-flattened to round-conical. Light green or yellow skin with broken red stripes over most of it, though some nurseries describe it as bright to dark red all over. Flesh white, dry and soft.","flavor_use":"Not for eating: dry, soft and very bitter. The deep golden juice is tannic, smoky and leathery with clove and nutmeg notes, and it darkens fast once pressed. Used for hard cider; fruit keeps only a few weeks.","uses":["cider"],"ripening":"Mid","ripening_note":"Midseason (mid-fall) per Raintree Nursery","id_cues":"Small to medium red-striped fruit with a long slender stem in a russeted, funnel-shaped cavity and a small, partly open calyx. Color is described differently by different sources, so it is a weak cue. Slow to start bearing, then heavy crops every other year.","habit":"High-vigor tree with an easy-to-manage shape and long, sweeping branches; a French supplier calls it upright. Slow to start bearing, then strongly biennial; tends to overbear, so thin hard when young and prune diligently.","bark":null,"leaf":null,"hardiness":"Zone 4 per Raintree","sources":[["Pomiferous: Frequin Rouge apple","https://pomiferous.com/applebyname/frequin-rouge-id-7191"],["Cummins Nursery: Frequin Rouge apple scionwood","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=scion&id=36006"],["Raintree Nursery: Frequin Rouge Cider Apple","https://raintreenursery.com/products/frequin-rouge-cider-apple-semi-dwarf"],["Western Cider: Frequin Rouge","https://westerncider.com/frequin-rouge"],["Arboriverse: Frequin Rouge cider apple tree","https://arbrefruitiers.com/en/products/frs2024120020005e00004fc0008ce590"]],"basis":"sourced","note":"Sources disagree on origin (Brittany vs Normandy) and fruit color (striped vs all red), and several French strains share the name, so the exact type sold in North America is unclear.","reviewed_on":"2026-10-17"},{"id":"apple-fuji","group":"Apple","type":"Apple","kind":"cultivar","name":"Fuji","aliases":[],"inventory_rows":[42],"purchase_rows":[18],"tagline":"Very late; pink-red stripes; sweet, crisp, long keeper","summary":"Japanese-bred late apple with pink-red stripes over yellow-green, crisp white flesh and mild sweetness. It keeps for months but needs a long, warm season and may not ripen well in short-season sites.","appearance":"Yellow-green skin with pink to red stripes and speckling; red covers from about a fifth to most of the surface. Flesh is dull white, crisp and juicy, and breaks cleanly when bitten.","flavor_use":"Mostly sweet with little tartness, juicy and medium firm; refreshing when chilled. Eaten fresh. A long keeper: WSU rates 12 months in cold storage, and Orange Pippin Trees says 3 months or more in a home fridge.","uses":["fresh","storage"],"ripening":"Very late","ripening_note":"Oct to Nov; one of the last apples. Needs a very long season, so it may not fully ripen in cold, short-season sites.","id_cues":"Pink-red stripes and speckles over yellow-green are common among apples, so timing is the best clue: Fuji ripens in late Oct to Nov. Many Fuji sports ripen much earlier than the original. Not self-fertile.","habit":"Strong-growing, productive tree with a spreading, fairly bushy form. Prone to alternate-year cropping, so early fruit thinning and careful yearly pruning help.","bark":"One campus tree record describes gray and brown bark that scales and flakes off in thin plates, with gray-brown twigs bearing small side buds.","leaf":"Oval leaves arranged alternately, with gray fuzz or hairs on the underside; they turn yellow in fall.","hardiness":"Zone 5 per Orange Pippin Trees; needs a long, warm season","sources":[["Orange Pippin: Fuji apple variety","https://www.orangepippin.com/varieties/apples/fuji"],["Washington State University Tree Fruit: Fuji","https://treefruit.wsu.edu/variety/fuji/"],["Orange Pippin Trees: Fuji apple trees","https://www.orangepippintrees.com/trees/apple-trees/fuji"],["Cummins Nursery: Fuji Apple on G.210","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=21303"],["Yale Nature Walk: Fuji Apple (campus tree record)","https://naturewalk.yale.edu/trees/rosaceae/malus-domestica/fuji-apple-84"]],"basis":"sourced","note":"Shares the AL-Fuji tag with Auvil Early Fuji (an early-ripening sport); check the vendor label or harvest date to tell them apart. Keeping time varies by source.","reviewed_on":"2026-10-17"},{"id":"apple-aztec-fuji","group":"Apple","type":"Apple","kind":"cultivar","name":"Aztec Fuji","aliases":["Fuji Aztec"],"inventory_rows":[43],"purchase_rows":[4,5],"tagline":"Very late; deep pink-red; very sweet, long keeper","summary":"Deeply colored Fuji strain from New Zealand: large, round, thin-skinned fruit with reddish-pink skin, crisp pale-yellow flesh and a very sweet, low-acid flavor. Ripens very late and keeps a long time.","appearance":"Round, large (about 3 inches across) and thin-skinned. Deep reddish-pink skin, more even than most Fujis, over smooth pale yellow flesh.","flavor_use":"Crisp, juicy and very sweet with hardly any acid; firm enough to hold up in baking. Keeps a long time, well into winter.","uses":["fresh","cooking","storage"],"ripening":"Very late","ripening_note":"Late October","id_cues":"Evenly deep reddish-pink skin over pale yellow flesh, ripening very late; standard Fuji is paler and less uniformly red.","habit":"Strongly vigorous Fuji strain, best on a dwarfing rootstock. Comes into bearing quickly with good yields, but heavy crops can lead to alternate-year bearing and fruit thinning is difficult. Early-to-mid bloom. One nursery guide gives 12-15 ft tall and wide at maturity.","bark":null,"leaf":null,"hardiness":"Reliable in zones 5 to 8","sources":[["Stark Bro's: Aztec Fuji","https://www.starkbros.com/products/fruit-trees/apple-trees/aztec-fuji-apple"],["Minnetonka Orchards: Aztec Fuji","https://minnetonkaorchards.com/aztec-fuji-apple/"],["Dalival: Fuji Zhen Aztec apple variety sheet","https://www.dalival.com/pommes/fuji-zhen-aztec-en/"],["Tsesmelis Nursery: Fuji Aztec apple variety","https://tsesmelis.gr/en/trees/pome-fruits/apples/fuji-aztec-apple-variety/"]],"basis":"sourced","reviewed_on":"2026-10-17"},{"id":"apple-auvil-early-fuji","group":"Apple","type":"Apple","kind":"cultivar","name":"Auvil Early Fuji","aliases":["Fuji, Early","Early Fuji"],"inventory_rows":[44],"purchase_rows":[3],"tagline":"Mid; red, gold-touched; sweet, low-acid Fuji sport","summary":"Early-ripening sport of Fuji found in Washington State in 1993 and released in 1997. Large, mostly red fruit with sweet, low-acid, crisp flesh, ready weeks before regular Fuji, so it suits shorter seasons.","appearance":"Big, round fruit that is mostly red with some gold showing through; the flesh inside is cream-white and crisp. Grandpa's Orchard says it shares the traits of regular Fuji except for timing.","flavor_use":"Gentle, sweet flavor with little acid and a honey-and-citrus edge. Mostly fresh eating, also good baked. Best eaten soon after picking, since it does not store especially well.","uses":["fresh","cooking"],"ripening":"Mid","ripening_note":"About mid-Sept per nurseries; 3 weeks (Pomiferous) to 5-6 weeks (nurseries) ahead of regular Fuji","id_cues":"Fruit is described as much like regular Fuji (mostly red, round, white flesh), so ripening date is the main cue: ripe in Sept, weeks before Fuji. Spreading, weeping habit with strong limbs; heavy crops every other year unless thinned; not self-fertile.","habit":"Spreading tree with moderate branching, wide branch angles and good productivity; a nursery adds a weeping habit and strong limbs. Vigor is rated low in its patent but moderate by one nursery. Heavy crops alternate with light ones unless thinned early.","bark":"Smooth, thick-set trunk colored gray-green to pale brown. Branches spread at wide angles, are medium in thickness, and carry medium-sized, scattered lenticels that range from white to pale brown.","leaf":"Broad dark-green leaves, shiny on top and moderately hairy underneath, about 80-100 mm long and 50-65 mm wide, with toothed edges, a moderately pointed tip and a short, thin, hairy stalk.","hardiness":"Zone 4 per Pomiferous; nursery lists zones 5-9","sources":[["Pomiferous: Fuji 216 (marketed as Auvil Early Fuji)","https://pomiferous.com/applebyname/fuji-216-id-8727"],["Grandpa's Orchard (archived page): Fuji-Auvil Early Fuji Apple","https://web.archive.org/web/20250713144431/https://www.grandpasorchard.com/Tree/Malus-Auvil-Early-Fuji"],["Planting Justice: Auvil Early Fuji Apple","https://plantingjustice.org/products/auvil-early-fuji-apple-organic"],["Google Patents: US PP10141 Apple tree Fuji 216 (Auvil Early Fuji)","https://patents.google.com/patent/USPP10141P/en"],["Rainbow Grove: Fuji 216 (Early Fuji) apple scion cuttings","https://rainbowgrove.com/product/early-fuji-apple/"]],"basis":"sourced","note":"Also called Fuji 216 or Early Fuji. Shares the AL-Fuji tag with regular Fuji, so check the label. Sources differ on how much earlier it ripens (3 vs 5-6 weeks) and on keeping quality.","reviewed_on":"2026-10-17"},{"id":"apple-gala","group":"Apple","type":"Apple","kind":"cultivar","name":"Gala","aliases":[],"inventory_rows":[45],"purchase_rows":[19,20],"tagline":"Early; orange-red streaks; mild, sweet","summary":"Mild, sweet apple from New Zealand with orange-red streaks over yellow that darken to red when fully mature. An easy, reliable eating apple that suits many climates.","appearance":"Small to medium and round. Orange streaks over a yellow ground when young, turning a stronger red as the fruit matures.","flavor_use":"Sweet, mild and undemanding rather than complex. Fresh eating; keeps well in storage.","uses":["fresh","storage"],"ripening":"Early","ripening_note":"Late August through September, later in cool climates","id_cues":"Small to medium round fruit with orange streaks over yellow that deepen to red with ripeness; ripens early in the season.","habit":"Medium-small, low, round-topped, spreading tree; the 1974 patent calls it vigorous yet only medium-slow growing, hardy, productive and a regular bearer. A nursery lists it as moderately vigorous, precocious and spur-bearing, tending to crop every other year.","bark":"Trunk smooth and moderately stocky; branches of medium thickness, smooth and heavily branched, brown, with many medium-to-large lenticels (from the 1974 patent for the original selection).","leaf":"Oval leaves of fairly large size, abruptly pointed at the tip, smooth, of medium thickness, roughly 4 in long, olive green, with scalloped to finely toothed margins and long, medium-slender stalks (1974 plant patent).","hardiness":"","sources":[["Orange Pippin: Gala","https://www.orangepippin.com/varieties/apples/gala"],["Google Patents: US Plant Patent 3,637, Gala apple (Kidd's D-8)","https://patents.google.com/patent/USPP3637P/en"],["Silver Creek Nursery: Gala Original apple tree","https://silvercreeknursery.ca/products/gala-apple"]],"basis":"general","note":"Fruit size and ripening timing come from general descriptions; the listed page covers color, parentage, flavor and keeping.","reviewed_on":"2026-10-17"},{"id":"apple-goldrush","group":"Apple","type":"Apple","kind":"cultivar","name":"GoldRush","aliases":["Gold Rush"],"inventory_rows":[46],"purchase_rows":[24],"tagline":"Very late; yellow, russet; tart-sweet, keeps 6 months","summary":"Disease-resistant apple from the Purdue, Rutgers and Illinois program, descended from Golden Delicious. Firm, yellow, tart and sugary; it sweetens in storage and keeps about six months, but needs a long growing season.","appearance":"Medium, round to slightly conical fruit. Thin skin starts greenish and ripens to yellow, in places deep saffron, with a bronzy orange blush on the sunny side in warm climates; rough russet patches are common. Flesh is cream-colored, firm, crisp and a bit coarse.","flavor_use":"Fairly tart but high in sugar, with a spicy, full flavor that develops after roughly four weeks of storage. Eaten fresh, cooked, or pressed for juice and cider. Flesh resists browning; keeps up to about six months cold.","uses":["fresh","cooking","cider","storage"],"ripening":"Very late","ripening_note":"Late Oct to early Nov in upstate New York; fruit hangs on well after it is ripe","id_cues":"Yellow to saffron, medium, round-conic fruit with russet patches and russeted dots; color alone is a weak cue among yellow apples. Blooms late and ripens very late. Compact, tidy tree that needs hard thinning to avoid biennial bearing.","habit":"Medium-vigor tree, slightly upright but spreading, with sturdy branches and a semi-spur bearing habit. Strong central leader and 70-90 degree branch angles that rarely trap bark, so little pruning is needed, but fruit needs thinning; some biennial tendency.","bark":"New stems are maroon where sunlit and green beneath. Lenticels on one-year wood are raised, round to oblong, apricot-colored and about 1-1.3 mm long; on 5-year-old trunks they are rough, roundish and typically 3 mm.","leaf":"Ovate to oval, with toothed to doubly toothed edges and a sharp to long-pointed tip, about 1.9 times longer than wide. Leaf stalks carry anthocyanin pigment, sometimes strongly where sun hits them.","hardiness":"Zone 4 per Pomiferous; zone 5 per Orange Pippin Trees","sources":[["Orange Pippin: GoldRush apple variety","https://www.orangepippin.com/varieties/apples/goldrush"],["Pomiferous: Co-op 38 (GoldRush)","https://pomiferous.com/applebyname/co-op-38-id-1497"],["Orange Pippin Trees: GoldRush apple trees","https://www.orangepippintrees.com/trees/apple-trees/goldrush"],["Google Patents: US PP9392 Apple tree Co-op 38 (GoldRush)","https://patents.google.com/patent/USPP9392P/en"],["NC State Extension Plants Toolbox: Malus domestica GoldRush","https://plants.ces.ncsu.edu/plants/malus-domestica-goldrush/"]],"basis":"sourced","note":"Pomiferous notes a different Goldrush that is a Golden Delicious sport; this entry is Co-op 38. Skin is called smooth by Orange Pippin but partly russeted by Pomiferous.","reviewed_on":"2026-10-17"},{"id":"apple-granny-smith","group":"Apple","type":"Apple","kind":"cultivar","name":"Granny Smith","aliases":[],"inventory_rows":[47],"purchase_rows":[25],"tagline":"Very late; bright green; very tart, long keeper","summary":"Australian green apple with hard, crisp, sharply tart flesh that mellows in storage. Good fresh, in salads and in pies, and a long keeper, but it wants a long, warm season and is a stretch in zone 5.","appearance":"Skin is a mid to deep green that often carries a faint blush, and it is tough. Where nights are cool it may blush red instead of staying green. Fruit often hangs inside the leafy canopy rather than at the outside of the tree.","flavor_use":"Crisp and hard, sharply acidic, and refreshing when chilled; it is less sour after storage. Holds its shape in pies and resists browning in salads. Pick slightly underripe for cooking. Keeps for many months in cold storage.","uses":["fresh","cooking","storage","pollinizer"],"ripening":"Very late","ripening_note":"Very late per Orange Pippin Trees; needs a long, warm season. WSU lists it as mid-season for Washington.","id_cues":"Uniform green, tough-skinned fruit that stays hard and very sour late into fall; a red blush appears only where nights are cold. Fruit tends to sit deep inside the canopy and the tree fruits partly on branch tips. Other green apples exist, so use late ripening and taste.","habit":"Strong, vigorous, very productive tree with an upright-spreading habit. It is partly tip-bearing, so prune with care, and fruit tends to sit inside the canopy. Thinning helps keep crops annual.","bark":null,"leaf":null,"hardiness":"Prefers zone 6 and warmer per Orange Pippin Trees; zone 5 is a stretch","sources":[["Orange Pippin: Granny Smith apple variety","https://www.orangepippin.com/varieties/apples/granny-smith"],["Orange Pippin Trees: Granny Smith apple trees","https://www.orangepippintrees.com/trees/apple-trees/granny-smith"],["Washington State University Tree Fruit: Granny Smith","https://treefruit.wsu.edu/variety/granny-smith/"],["Dave Wilson Nursery: Granny Smith Apple","https://www.wheretobuy.davewilson.com/product-information-commercial/product/granny-smith-apple"],["Cummins Nursery: Granny Smith Apple on G.210","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=21327"]],"basis":"sourced","note":"Brief hint says standard Granny Smith. Sources differ on harvest timing (WSU mid-season vs Orange Pippin very late) and on keeping time (3+ months in a fridge vs WSU 12 months).","reviewed_on":"2026-10-17"},{"id":"apple-harrison","group":"Apple","type":"Apple","kind":"cultivar","name":"Harrison","aliases":["Harrison Cider Apple"],"inventory_rows":[48],"purchase_rows":[26,27],"tagline":"Late; small yellow; sweet, rich cider apple","summary":"Old New Jersey cider apple, thought lost until old trees were found in the 1970s and 1980s. Small to medium yellow fruit with very sweet, rich, slightly tart juice; grown for cider and also bakes well.","appearance":"Small to medium, round-conic to somewhat elongated. Yellow skin that sometimes takes on a rusty red tinge on the sun-facing side, with large dark dots scattered over it; stem fairly long. Flesh is yellow, dense, coarse and dry.","flavor_use":"Strongly sweet with a mild tart edge and a smooth, rich body; hints of peach and smoke, and a faint dry astringency at the end. Pressed for cider, alone or blended, and good baked. Does not store well.","uses":["cider","cooking"],"ripening":"Late","ripening_note":"Late Oct in western Washington; Raintree says Nov. Fruit tends to drop as it ripens.","id_cues":"Small yellow apple with big dark dots, round-conic to elongated, with a fairly long stem; yellow cider apples are not unique, so confirm by the late drop. Vigorous, upright-spreading tree, slow to first fruit, heaviest crops every other year.","habit":"Strong, vigorous tree, but young plants start slowly with thin, nearly vertical shoots and need branches spread. An 1817 account notes many suckers along the limbs. Early fruit thinning helps avoid alternate-year crops.","bark":null,"leaf":null,"hardiness":"Zone 4 per Pomiferous and Raintree","sources":[["Pomiferous: Harrison Crab (Harrison)","https://pomiferous.com/applebyname/harrison-crab-id-7280"],["Raintree Nursery: Harrison Cider Apple","https://raintreenursery.com/products/harrison-cider-apple-semi-dwarf"],["NW Fruit (Western Washington Fruit Research Foundation): Cider Apple Varieties","https://nwfruit.org/cider-apple-and-pear-varieties/"],["Western Cider: Harrison","https://westerncider.com/wickson-2"],["Wikipedia: Harrison Cider Apple","https://en.wikipedia.org/wiki/Harrison_Cider_Apple"]],"basis":"sourced","note":"Harrison and Harrison Cider are one cultivar (also Harrison Crab). Sources disagree: Raintree says rust resistant and bittersweet; Pomiferous says rust susceptible and sharp.","reviewed_on":"2026-10-17"},{"id":"apple-honeycrisp","group":"Apple","type":"Apple","kind":"cultivar","name":"Honeycrisp","aliases":[],"inventory_rows":[49],"purchase_rows":[28],"tagline":"Mid; red-orange flush; very crisp, sweet","summary":"University of Minnesota apple prized for a crisp, juicy bite. Medium to large with a red-orange flush over green-yellow skin and a sweet flavor with little acidity.","appearance":"Medium to large. Light green-yellow skin largely covered with a red-orange flush (pinker in good sun), sometimes flecked with russet dots; white flesh.","flavor_use":"Sweet with very little acidity and a light, crisp crunch that is soft rather than hard. Bruises easily. Keeps until about April in cold storage.","uses":["fresh","storage"],"ripening":"Mid","ripening_note":"Relatively early in September in the northern hemisphere","id_cues":"Large, red-orange flushed fruit with white flesh that is crisp but not hard; the fruit bruises easily. Ripens relatively early in September.","habit":"Breeder's patent: moderately vigorous, slightly upright, annual bearing. Minnesota's page: somewhat spreading, low to moderate vigor, good precocity on dwarfing rootstock; early heavy bearing may call for staking the leader or removing some fruit.","bark":"Bark is smooth and bronze-toned, with conspicuous lenticels (breeder's plant patent).","leaf":"Ovate, toothed leaves about 8-10.5 cm long and 5-8 cm wide on 3-3.5 cm stalks. Green and glossy above with a smooth surface, hairy beneath; margins sometimes tinge yellow in late summer.","hardiness":"Bred for cold hardiness; grows across a wide climate range","sources":[["Orange Pippin: Honeycrisp","https://www.orangepippin.com/varieties/apples/honeycrisp"],["Google Patents: US Plant Patent 7,197, Honeycrisp apple tree","https://patents.google.com/patent/USPP7197P/en"],["Minnesota Hardy (University of Minnesota): Honeycrisp","https://mnhardy.umn.edu/honeycrisp"]],"basis":"sourced","reviewed_on":"2026-10-17"},{"id":"apple-honeycrisp-super-red","group":"Apple","type":"Apple","kind":"cultivar","name":"Honeycrisp (Super Red)","aliases":["Honeycrisp, Super Red","Super Red Honeycrisp"],"inventory_rows":[50],"purchase_rows":[29],"tagline":"Mid; red over yellow; very crisp, sweet-tart","summary":"A redder strain of Honeycrisp, the cold-hardy University of Minnesota apple, sold as Super Red. Large, very crisp and juicy with a balanced sweet-tart flavor; picked in September and stored for months.","appearance":"Large, flattened-round to round apple, roughly 2.75 to 4 inches across. Dappled or striped red over a yellow ground, with more red in this strain; small russet dots are possible. Flesh is cream colored, coarse and light.","flavor_use":"Very crisp and juicy with a balanced, mildly aromatic sweet-tart flavor, though it can taste mild if picked early or in warm sites. Mostly eaten fresh; also used in salads and cooking. Stores about 7 months cold but bruises easily.","uses":["fresh","cooking","storage"],"ripening":"Mid","ripening_note":"About Sept 15 to Oct 5 in Minnesota; Grandpa's Orchard says mid-Sept. Fruit holds well on the tree.","id_cues":"Large flattened-round fruit, red-striped or dappled over yellow, with pale russet dots and coarse cream flesh. Summer leaves often look blotchy or mottled, which is normal for it. Low to moderate vigor, somewhat spreading, early bearing. Red strains look alike, so color alone will not separate them.","habit":"Low to moderate vigor and early bearing; described as somewhat spreading, though a patent says slightly upright. The leader may need staking, and some growers strip fruit in the first years so growth does not stall.","bark":"Smooth, bronze-colored bark with prominent lenticels, as described for the original Honeycrisp (Super Red is a red sport of it).","leaf":"Ovate, toothed leaves about 8-10.5 cm long and 5-8 cm wide. In summer they often look mottled, which is normal for this variety and easily mistaken for insect damage.","hardiness":"USDA Zone 4 (-25 to -30 F) per Univ. of Minnesota","sources":[["University of Minnesota Minnesota Hardy: Honeycrisp","https://mnhardy.umn.edu/honeycrisp"],["Grandpa's Orchard (archived page): Honeycrisp-Super Red Apple","https://web.archive.org/web/20250123112901/https://www.grandpasorchard.com/Tree/Malus-HoneycrispSuperRed"],["Orange Pippin: Honeycrisp apple variety","https://www.orangepippin.com/varieties/apples/honeycrisp"],["Google Patents: US PP7197 Apple tree Honeycrisp","https://patents.google.com/patent/USPP7197P/en"],["Cummins Nursery: Honeycrisp Apple on G.11","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=29348"]],"basis":"sourced","note":"'Super Red' is a nursery label for a redder Honeycrisp sport; the exact patented strain is not named, so treat it as Honeycrisp.","reviewed_on":"2026-10-17"},{"id":"apple-hudsons-golden-gem","group":"Apple","type":"Apple","kind":"cultivar","name":"Hudson's Golden Gem","aliases":["Hudsons Golden Gem"],"inventory_rows":[51],"purchase_rows":[30],"tagline":"Late; large russet, pear-shaped; sweet, nutty","summary":"Large, elongated, russeted yellow apple found as a chance seedling in Oregon in the early 1930s. Crisp, very sweet and nutty with a pear-like taste; eaten fresh, cooked or pressed, and it hangs on well into winter.","appearance":"Large, tall cone shape with slight angles and a lopsided look, so it is easily taken for a pear. Skin is dull yellow under a coarse, mostly complete russet layer, with many small russet dots most numerous near the blossom end. Flesh is yellow, crisp and juicy.","flavor_use":"Juicy and high in sugar, with a nutty taste that recalls a pear. Overripe fruit softens to a grainy, pear-like texture, and cut flesh browns quickly. Good fresh, baked or in sweet cider. Keeps about 1 to 3 months and gets sweeter in storage.","uses":["fresh","cooking","cider","juice"],"ripening":"Late","ripening_note":"Late Oct per Raintree; fruit hangs well into winter, though it can crack on young trees","id_cues":"Pear-shaped russet apple: large, tall-conic and lopsided, dull yellow under a full rough russet, with russet dots thickest near the eye and a long stem in a deep cavity. Vigorous, upright-spreading tree; fruit may split on young trees. Shape plus full russet is the best cue.","habit":"Productive tree with a spreading to upright-spreading habit. Sources differ on size (one nursery says small, others large and vigorous) and on bearing (annual in one, an alternate-year tendency in another).","bark":null,"leaf":null,"hardiness":"Zone 4 per Raintree and Pomiferous; one nursery lists zone 3","sources":[["Pomiferous: Hudson's Golden Gem","https://pomiferous.com/applebyname/hudsons-golden-gem-id-1969"],["Raintree Nursery: Hudson's Golden Gem Apple","https://raintreenursery.com/products/hudsons-golden-gem-apple-dwarf"],["Orange Pippin Trees: Hudson's Golden Gem apple trees","https://www.orangepippintrees.com/trees/apple-trees/hudsons-golden-gem"],["Cummins Nursery: Hudson's Golden Gem Apple on G.11","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=21342"],["Tooley's Trees: Hudson's Golden Gem","https://tooleystrees.com/product/234/"]],"basis":"sourced","note":"Sources differ on keeping time (1 to 3 months) and on skin base color (dull yellow vs pale green under the russet).","reviewed_on":"2026-10-17"},{"id":"apple-idared","group":"Apple","type":"Apple","kind":"cultivar","name":"Idared","aliases":[],"inventory_rows":[52],"purchase_rows":[31],"tagline":"Late; smooth red; mild sweet-tart; keeps 6 months","summary":"Idaho-bred apple from Jonathan x Wagener, released in 1942. Medium to large, smooth and red, with mild sweet-tart flesh; mainly used for sauce, pies and baking, and it stores about six months.","appearance":"Round, medium-to-large fruit with slight ribs. Green-yellow ground color with bright red covering as much as three quarters of it; the skin is glossy, smooth and tough. Flesh is firm and fine in texture, pale yellow and occasionally blushed pink.","flavor_use":"Juicy with a mild sweet-tart taste that turns bland if the fruit is picked early. Holds its shape baked, so it suits pies, sauce, strudel and baked apples; cooking with the skins on gives pink sauce. Keeps about 4 to 6 months in cold storage.","uses":["cooking","fresh","storage","pollinizer"],"ripening":"Late","ripening_note":"Sept to Oct in Utah; about 160-170 days after petal fall; fruit hangs well on the tree","id_cues":"Smooth, shiny red over green-yellow, round with slight ribs, a small closed eye sitting in a narrow, deep pit, and a short stem; the stem end may russet in humid years. Blooms early; moderately vigorous, spreading, precocious spur-bearing tree. Red color alone is shared with many apples.","habit":"Smallish tree whose open crown grows upright but spreads outward. It bears young and is a reliable, often heavy cropper; it blooms early.","bark":null,"leaf":null,"hardiness":"Zone 4-8 per Utah State Univ.; Pomiferous lists zone 3","sources":[["Pomiferous: Idared","https://pomiferous.com/applebyname/idared-id-2002"],["Orange Pippin Trees: Idared apple trees","https://www.orangepippintrees.com/trees/apple-trees/idared"],["Utah State University Intermountain Fruit: Varieties for Utah - Apple","https://intermountainfruit.org/fruit-tables/apple"],["Cummins Nursery: Idared Apple on G.210","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=23598"]],"basis":"sourced","note":"Also sold as Ida Red. Sources differ on keeping time: about 4 months if picked early (Pomiferous) vs 6 months (Orange Pippin Trees, Utah State).","reviewed_on":"2026-10-17"},{"id":"apple-jonagold","group":"Apple","type":"Apple","kind":"cultivar","name":"Jonagold","aliases":[],"inventory_rows":[53],"purchase_rows":[32],"tagline":"Late; large red-over-gold; honeyed sweet-tart; triploid","summary":"Large Jonathan x Golden Delicious cross from Geneva, NY: red over gold, crisp and honeyed sweet-tart. A dessert and baking apple; as a triploid it needs two other pollinizers.","appearance":"Large, round-conic fruit on a yellow background with a wide red flush and faint streaks, plus many tan freckles. The thin skin bruises easily. Flesh creamy yellow and crisp. Russet can creep out from the stem cavity in humid climates.","flavor_use":"Crisp, juicy and honeyed sweet-tart. Good fresh and in pies or baking, and used for cider. Holds about 2 months in cold storage, then turns soft and grainy. Needs several pickings.","uses":["fresh","cooking","cider"],"ripening":"Late","ripening_note":"Mid-Sept into Oct (NC State); mid-late season in NY (Cummins); 140-160 days after petal drop (Pomiferous)","id_cues":"Large round-conic apple: yellow background, wide red flush with faint streaks, tan freckles thickest near the blossom end, slight ribbing and a faint five-pointed crown. Spreading tree with drooping limbs. Redder sports exist, so color alone is weak.","habit":"Moderately vigorous (Cornell) to vigorous (Cummins) semi-spur tree with a spreading habit and wide-angled shoots. Very precocious and a heavy cropper that turns biennial unless thinned early. About 10-15 ft on semi-dwarf stock.","bark":null,"leaf":"Leaves are large and boat-shaped, per German Wikipedia.","hardiness":"Zone 4 (Pomiferous); Cummins calls it cold hardy","sources":[["Pomiferous: Jonagold apple entry","https://pomiferous.com/applebyname/jonagold-id-3590"],["Cummins Nursery: Jonagold apple","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=scion&id=36037"],["NC State Extension Plant Toolbox: Malus domestica Jonagold","https://plants.ces.ncsu.edu/plants/malus-domestica-jonagold/"],["Cornell NYSAES: Jonagold fruit variety bulletin 150","https://ecommons.cornell.edu/server/api/core/bitstreams/b6ccdd8e-d26f-4e18-a742-8a8aab6db2c8/content"],["Wikipedia (German): Jonagold apple variety","https://de.wikipedia.org/wiki/Jonagold"]],"basis":"sourced","note":"Over 70 sports are recorded, many redder, so a bought tree may look redder than described. Golden Delicious cannot pollinate it, and Jonagold pollen is sterile.","reviewed_on":"2026-10-17"},{"id":"apple-kingston-black","group":"Apple","type":"Apple","kind":"cultivar","name":"Kingston Black","aliases":[],"inventory_rows":[54],"purchase_rows":[34],"tagline":"Late; dark red, russeted; bittersharp cider apple","summary":"Traditional English bittersharp cider apple from Somerset: small to medium, dark red and russeted. Grown for single-variety cider rather than eating, on a slow, fussy tree.","appearance":"Small to medium, squat and often lopsided. Mostly dark red with deeper stripes over a green-yellow base, the shaded cheek yellow to orange, with small russet dots and sometimes a russet patch at the base. Flesh yellowish, often tinted red beneath the skin.","flavor_use":"Tart and tannic, with sweetness and fruit underneath. Makes full-bodied single-variety cider and a dark, rich juice; fresh eating is poor to fair. Let it rest about 10 days after picking, then press, since quality fades quickly in storage.","uses":["cider","juice"],"ripening":"Late","ripening_note":"Late Sept to Oct per Raintree, with early Oct typical; Fedco lists it as a fall apple","id_cues":"Squat, often lopsided fruit, mostly dark red with deeper stripes over green-yellow, a yellow-orange shaded cheek, russet dots, and a short thick stem in a deep cavity. Tree is gangly and slow to bear. Irregular shape makes shape alone a weak cue.","habit":"Medium-sized tree of moderate vigor with a spreading to upright-spreading habit, bearing on spurs. Fedco calls it gangly, so careful pruning matters; Raintree says it stays smaller with mild vigor, about 13-15 ft on semi-dwarf stock.","bark":null,"leaf":null,"hardiness":"Zone 4 (Raintree, Fedco); Pomiferous says zones 4-8","sources":[["Pomiferous: Kingston Black apple entry","https://pomiferous.com/applebyname/kingston-black-id-3761"],["Raintree Nursery: Kingston Black Cider Apple","https://raintreenursery.com/products/kingston-black-cider-apple-semi-dwarf"],["Fedco Trees: Kingston Black cider apple (scionwood)","https://fedcoseeds.com/trees/kingston-black-cider-apple-7887"],["National Fruit Collection: Kingston Black apple","https://www.nationalfruitcollection.org.uk/full2.php?id=3250&fruit=apple"],["Keepers Nursery: Kingston Black apple trees","https://www.keepers-nursery.co.uk/fruit-trees/apple/cider/kingston-black"]],"basis":"sourced","note":"Sources differ on cropping (light with off years vs reliable) and on fresh eating (poor vs fairly decent). Raintree says it needs good growing conditions to do well and stays a smaller, mild-vigor tree.","reviewed_on":"2026-10-17"},{"id":"apple-liberty","group":"Apple","type":"Apple","kind":"cultivar","name":"Liberty","aliases":[],"inventory_rows":[55],"purchase_rows":[35],"tagline":"Mid; bright red Mac-type; scab-resistant; sweet-tart","summary":"Scab-resistant McIntosh-style apple from Geneva, NY, bred from Macoun: bright red, crisp, juicy and well balanced. Used fresh, for sauce and pies, and for cider.","appearance":"Medium to large, round to conic fruit with a gold-yellow background mostly covered in bright red with deeper red streaks; a silvery bloom appears when ripe. The stem is very short and thick. Flesh white to pale yellow, crisp and juicy.","flavor_use":"Balanced sweet-tart with a McIntosh-like wine note, a little sharper than many Mac types. Used fresh, for sauce and pies, and for cider. Keeps about 2 months cold (one nursery says to January) and improves in storage; overripe fruit tastes off.","uses":["fresh","cooking","cider"],"ripening":"Mid","ripening_note":"Mid to late September per One Green World; Pomiferous: ready from the start of its fifth harvest period","id_cues":"Mac-type red apple, but the ground color under the bright red is gold-yellow with deeper streaks, a silvery bloom shows when ripe, and the stem is very short and thick. Scab-resistant, so scab spots are unlikely even in wet years. Vigorous, upright-spreading tree with heavy yearly crops.","habit":"Cornell: vigorous, round and spreading, bears annually; flower buds often form on tips and sides of current-year shoots, plus many spurs that stay fruitful for years. Heavy sets need thinning. Orange Pippin notes it lacks the extra size and vigor often seen in triploids.","bark":null,"leaf":null,"hardiness":"Zones 4-8; hardy to -30 F or below (One Green World)","sources":[["Orange Pippin: Liberty apple","https://www.orangepippin.com/varieties/apples/liberty"],["Pomiferous: NY 55140-19 (Liberty) apple entry","https://pomiferous.com/applebyname/liberty-id-3944"],["One Green World: Liberty Apple Tree","https://onegreenworld.com/product/liberty-apple-tree/"],["Cornell NYSAES: LIBERTY, a new disease resistant apple","https://ecommons.cornell.edu/server/api/core/bitstreams/df23bb1a-03c3-4be1-a791-d1517d86dec9/content"],["Cummins Nursery: Liberty apple scionwood","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=scion&id=36053"]],"basis":"sourced","note":"Pomiferous files Liberty under its Geneva number, NY 55140-19. Sources differ on size (medium-large vs large), flesh color (white vs yellowish) and keeping time (2 months to January).","reviewed_on":"2026-10-17"},{"id":"apple-mcintosh","group":"Apple","type":"Apple","kind":"cultivar","name":"McIntosh","aliases":["Macintosh"],"inventory_rows":[57],"purchase_rows":[36],"tagline":"Mid; red over green; crisp, wine-like, white flesh","summary":"Old Ontario apple, very cold hardy: round, dark red over green, with bright white, spicy, wine-like flesh. Eat fresh soon after picking for full flavor; also used for sauce, juice and cider.","appearance":"Medium to large, round to slightly flattened, green underneath but mostly overlaid with dark red (less red on some strains). A light waxy bloom and tiny pale dots are common. Flesh bright white, sometimes tinted red just under the skin.","flavor_use":"Crisp, mildly tart-sweet, aromatic and spicy with a wine-like edge, at its peak soon after picking. Makes good sauce (turns soupy in pies), juice and cider. Cold storage holds about 3 months at most, with flavor fading and flesh turning mealy.","uses":["fresh","cooking","juice","cider"],"ripening":"Mid","ripening_note":"Mid-September in upstate NY, the benchmark for other apples at Cummins; fruit can drop before harvest","id_cues":"Round to slightly flat apple, dark red over green with a light bloom and tiny pale dots; bright white flesh with a wine-like flavor; the stem drops off when overripe. Cortland, Macoun, Spartan and other descendants share the flavor, so taste alone is not decisive.","habit":"Medium-large to large, vigorous tree with a rounded, spreading form and many small slender laterals; Fedco calls it easy to manage. Heavy cropper, but sources differ on bearing: annual (Fedco), biennial unless thinned (Cummins), biennial or sometimes annual (Beach, 1905).","bark":"Young twig bark is bright reddish-brown, lightly streaked with scarf-skin and slightly hairy, with many small raised lenticels; buds plump, set deep in the bark and slightly hairy. Mature trunk bark not described.","leaf":"Oval leaves with a dull, rough surface and only shallow, faint teeth along the edges (one orchard description).","hardiness":"Zone 4 (Fedco, Pomiferous); fruit quality peaks in zones 4-5 (Cummins)","sources":[["Pomiferous: McIntosh apple entry","https://pomiferous.com/applebyname/mcintosh-id-4205"],["Cummins Nursery: McIntosh apple","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=36658"],["Fedco Trees: McIntosh apple","https://fedcoseeds.com/trees/mcintosh-apple-7253"],["Internet Archive: Beach, The Apples of New York vol 2 (1905)","https://archive.org/stream/applesofnewyork02beac/applesofnewyork02beac_djvu.txt"],["Albemarle CiderWorks: McIntosh apple","https://www.albemarleciderworks.com/orchard/apple/mcintosh"]],"basis":"sourced","note":"McIntosh strains vary in color. Sources differ on cropping (Fedco: annual; Pomiferous and Cummins: alternate-year if unthinned) and on cooking (good sauce vs not well suited).","reviewed_on":"2026-10-17"},{"id":"apple-newtown-pippin","group":"Apple","type":"Apple","kind":"cultivar","name":"Newtown Pippin","aliases":["Newton Yellow Pippin","Newtown Pippen"],"inventory_rows":[58],"purchase_rows":[38],"tagline":"Very late; dull green-yellow; tart, aromatic winter apple","summary":"Very old American heirloom from Long Island: dull green to yellow-green, tart, crisp and aromatic. A late-picked winter apple for fresh eating, pies, sauce and cider that improves in storage but wants a long, warm season.","appearance":"Medium to large, round to flattish or round-conic fruit. Matte pale-green skin that ripens toward greenish-yellow, sometimes with a faint brownish blush, large dark dots, and a little russet in the stem cavity. Flesh yellowish, firm and fine-grained.","flavor_use":"Tangy, tart and crisp with pineapple or tangerine notes; sweetens and mellows in storage. Used fresh, in sauce and pies (flesh browns fast) and for cider and juice. Orange Pippin finds it hard at harvest and stores it 1-2 months first; Pomiferous says it tastes good just picked.","uses":["fresh","cooking","cider","juice","storage"],"ripening":"Very late","ripening_note":"Late October in the eastern US (Orange Pippin); ripens poorly without a hot summer and autumn","id_cues":"Matte pale-green to greenish-yellow, medium-large, round to flattish fruit with large dark dots, a little russet in the stem cavity and an open calyx. Upright-spreading, tip-bearing tree that is slow to start. Green and yellow strains look almost identical.","habit":"Moderately vigorous, partly tip-bearing, slow to start fruiting even on dwarfing stock, and biennial if overcropped. Beach (1905): Green strain is rounded and spreading with drooping laterals; Yellow strain is more vigorous and more erect.","bark":"Beach (1905), Green strain: twig bark dark brownish-red with light scarf-skin streaks; twigs hairy near the tips; many medium or smaller raised lenticels that stand out; buds broad, plump and slightly hairy.","leaf":null,"hardiness":"Zone 4 (Cummins, Pomiferous); needs a warm summer and autumn to ripen","sources":[["Orange Pippin: Newtown Pippin apple","https://www.orangepippin.com/varieties/apples/newtown-pippin"],["Cummins Nursery: Newtown Pippin apple","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=29632"],["Pomiferous: Newtown Pippin apple entry","https://pomiferous.com/applebyname/newtown-pippin-id-4526"],["Internet Archive: Beach, The Apples of New York vol 1 (1905)","https://archive.org/stream/applesofnewyork01beac/applesofnewyork01beac_djvu.txt"],["Silver Creek Nursery: Newtown Pippin apple scionwood","https://silvercreeknursery.ca/products/newtown-pippin-apple-scionwood"]],"basis":"sourced","note":"Inventory 'Newton Yellow Pippin' is the yellow Newtown strain. Pomiferous lists it (as Albemarle Pippin) separately; Cummins and Orange Pippin treat Albemarle as the same apple. Strains look alike.","reviewed_on":"2026-10-17"},{"id":"apple-pink-lady","group":"Apple","type":"Apple","kind":"cultivar","name":"Pink Lady (Cripps Pink)","aliases":["Pink Lady","Cripps Pink"],"inventory_rows":[59],"purchase_rows":[39],"tagline":"Very late; pink blush on yellow; crisp, sweet-tart","summary":"Cripps Pink is the variety and Pink Lady a trademark: a late Australian Golden Delicious x Lady Williams apple with pink blush on yellow and crisp, sweet-tart flesh. It needs a long, warm season.","appearance":"Medium to large, round-conic fruit taller than wide, about 2.75 to 3.5 inches across. Yellow skin overlaid with a pink to orange-pink flush and broken streaks; the skin is thin and nearly free of russet. Flesh firm, dense and fine-grained.","flavor_use":"Crisp, juicy and sweet-tart with good acidity; flesh resists browning. Used fresh, in salads, cooking and baking. Stores up to about 4 months and peaks after roughly 4 weeks in storage.","uses":["fresh","cooking","storage"],"ripening":"Very late","ripening_note":"Late October in Willis's listing; needs roughly 150 frost-free days (Pomiferous)","id_cues":"Round-conic fruit taller than wide, yellow with a pink to orange-pink flush and broken streaks, thin skin, almost no russet, and a deep, wide calyx basin. Vigorous, upright-spreading tree that holds its leaves late. Pink color needs strong autumn sun.","habit":"Strongly upright; young limbs benefit from spreading (Cummins). Vigor is called vigorous and prolific there but moderate by Orange Pippin. Young trees give inferior fruit that improves with age.","bark":null,"leaf":"Holds its leaves late, well into winter. Growers may strip the top leaves so autumn sun can color the fruit.","hardiness":"Zones 6-9 (Willis); Pomiferous rates zone 6; needs a long warm season","sources":[["Orange Pippin: Pink Lady apple","https://www.orangepippin.com/varieties/apples/pinklady"],["Pomiferous: Cripps Pink apple entry","https://pomiferous.com/applebyname/cripps-pink-id-2185"],["Willis Orchard Company: Pink Lady Apple Tree","https://www.willisorchards.com/product/pink-lady-apple-tree"],["Cummins Nursery: Pink Lady Cripps Pink apple tree","https://www.cumminsnursery.com/buy-trees/product-detail.php?id=21824"]],"basis":"sourced","note":"Marginal for a zone 4-5 short-season site: sources say it needs a very long, hot season (about 150 frost-free days) and strong autumn sun for color, and rate it zones 6-9. Fruit may not ripen well.","reviewed_on":"2026-10-17"},{"id":"apple-sweet-sixteen","group":"Apple","type":"Apple","kind":"cultivar","name":"Sweet Sixteen","aliases":[],"inventory_rows":[60],"purchase_rows":[41],"tagline":"Mid; pink-red stripes; yellow flesh, candy-sweet","summary":"University of Minnesota apple, rose-red over yellow with crisp, golden-yellow flesh and an unusually candy-like flavor. Cold hardy and a reliable annual cropper.","appearance":"Medium-large, blushed and striped rose-red over yellow and speckled with pale lenticels. The crisp flesh is distinctly yellow, almost golden.","flavor_use":"Sweet but balanced by enough acid, with candy-like flavors often compared to cherry and bubblegum. Best eaten fresh off the tree; stores passably for about six weeks.","uses":["fresh"],"ripening":"Mid","ripening_note":"Typically mid to late September","id_cues":"Yellow flesh and a candy-like flavor set it apart from other red-striped apples. The tree is vigorous with a very upright habit that benefits from spreading.","habit":"Vigorous, moderate-sized, vase-shaped tree growing upright; slender branches carry heavy crops without breaking. Very upright, so spreading the branches helps (one nursery says moderately spreading). Easy to manage; annual bearer if thinned. Blooms mid to late season.","bark":null,"leaf":null,"hardiness":"Hardy to zone 3","sources":[["Cummins Nursery: Sweet Sixteen","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=21852"],["Fedco Trees: Sweet Sixteen apple","https://fedcoseeds.com/trees/sweet-sixteen-apple-7906"],["Tooley's Trees: Sweet 16 apple tree","https://tooleystrees.com/product/sweet-16-apple-tree/"]],"basis":"general","note":"Ripening timing is a general figure; the listed page covers appearance, flavor, storage, hardiness and tree habit.","reviewed_on":"2026-10-17"},{"id":"apple-blushing-delight","group":"Apple","type":"Apple","kind":"cultivar","name":"Blushing Delight (Urban columnar)","aliases":["Urban Gold","Blushing Delight Urban Columnar"],"inventory_rows":[63],"purchase_rows":[6],"tagline":"Mid; red blush on green; sweet; columnar tree","summary":"Urban-series columnar apple from Czech breeder Jaroslav Tupy (sold in Europe as Moonlight): sweet, crisp fruit with a red blush over green, ripening mid-September on a narrow 8-10 ft tree.","appearance":"Large, crisp fruit with a crimson to red blush over green skin. The sources do not describe flesh color or shape. The tree is a narrow upright pillar, 8-10 ft tall, bearing fruit on short spurs along the main stem.","flavor_use":"Sweet and crisp. The sources describe flavor only and give no cooking uses, so treat it as a fresh-eating apple; one nursery says it stores up to four months. Needs a second apple cultivar nearby; most Urban apples bloom mid-season and pollinate each other.","uses":["fresh"],"ripening":"Mid","ripening_note":"Mid-September per Raintree and Evergreen Botany; Raintree also calls it early midseason","id_cues":"Narrow columnar pillar with fruit on short spurs along the trunk. Fruit is green with a red blush, not golden; a fully golden fruit would point to Golden Treat, the golden Urban apple. All Urban apples share the columnar habit.","habit":"Columnar, erect and dense, with no conventional side branches and very short internodes; fruit mainly on spurs, very precocious. Patent tree was 3.4 m tall and 0.5 m wide at 10 years; nurseries list 8-10 ft. Patent rates vigor weak; Greenleaf lists the series as vigorous.","bark":"Trunk smooth to slightly rough and brown (RHS 174A), with small lenticels about 3 per square cm. One-year shoots smooth, straight, dark purplish-grey (RHS 183A) with dense small oval lenticels; crotch angle about 45 degrees.","leaf":"Oblong leaves about 100-130 mm long and 50-70 mm wide, moderately thick, smooth but wavy, with bicrenate (doubly scalloped) edges; hairless above, fine hairs on veins beneath. Yellow-green when young, deeper green when mature.","hardiness":"Zones 4-9 (Raintree); Evergreen Botany says hardy to zone 4","sources":[["Raintree Nursery: Blushing Delight Urban Columnar Apple","https://raintreenursery.com/products/blushing-delight%E2%84%A2-urban%E2%84%A2-columnar-apple-semi-dwarf"],["Evergreen Botany: Blushing Delight Urban Columnar Apple","https://evergreenbotany.com/products/blushing-delight-apple"],["Raintree Nursery: Golden Treat Urban Columnar Apple","https://raintreenursery.com/products/golden-treat%E2%84%A2-urban%E2%84%A2-columnar-apple-semi-dwarf"],["Google Patents: US PP21511 columnar apple named Moonlight","https://patents.google.com/patent/USPP21511P3/en"],["Greenleaf Nursery: Urban Apple series (Garden Debut)","https://www.greenleafnursery.com/index.cfm/fuseaction/whatsnew.detail/recID/29/index.htm"]],"basis":"sourced","note":"Identity unconfirmed: inventory says 'Urban Gold', but nurseries describe Blushing Delight as red-blushed green and Golden Treat as the golden Urban apple. Check fruit color to confirm the label.","reviewed_on":"2026-10-17"},{"id":"apple-tangy-green","group":"Apple","type":"Apple","kind":"cultivar","name":"Tangy Green (Urban columnar)","aliases":["Urban Green","Tandgy green Urban Columnar","Tandgy green"],"inventory_rows":[64],"purchase_rows":[42],"tagline":"Mid; lime green; crisp, tart; columnar tree","summary":"Urban-series columnar apple (AK-98) from Czech breeder Jaroslav Tupy: medium, lime-green, crisp, sweet-tart fruit in mid-September on a narrow 8-10 ft tree. Needs a second apple for pollination.","appearance":"Medium-sized, lime-green apples, sometimes with a hint of red, with crisp flesh. Flesh color and shape are not described by the sources. Narrow tree about 8-10 ft tall and 2 ft wide, fruiting on spurs along the main stem.","flavor_use":"Crisp with a sweet-tart, tangy bite; the extra acidity slows browning once cut. Suited to fresh eating, salads and pies. The sources do not state how long it keeps.","uses":["fresh","cooking"],"ripening":"Mid","ripening_note":"Midseason per Raintree; Restoring Eden says typically mid-September","id_cues":"Narrow columnar tree with fruit on spurs along the trunk; apples stay lime green with at most a hint of red and taste tart. Blushing Delight is also green with a red tinge but is described as sweeter, so color alone can mislead; taste is a better check.","habit":"Narrow columnar tree about 8-10 ft tall and 2-3 ft wide, fruiting on short spurs along the main leader, with short upright branches. Bears 1-3 years after planting; pruning can hold height down. Growth rate rated vigorous by Greenleaf, slow to moderate by Gurney's.","bark":null,"leaf":"Apple-green leaves in summer with negligible fall color (stated for the whole Urban Apple series).","hardiness":"Zones 4-9 (Raintree); Gurney's lists zones 4-8","sources":[["Raintree Nursery: Tangy Green Urban Columnar Apple","https://raintreenursery.com/products/tangy-green%E2%84%A2-urban%E2%84%A2-columnar-apple-semi-dwarf"],["Gurney's: Tangy Green Urban Apple","https://www.gurneys.com/products/tangy-green-tm-urban-apple"],["Restoring Eden: Columnar Apple Tree (Tangy Green)","https://restoringeden.co/product/apple-tree-urban-tangy-green/"],["Greenleaf Nursery: Urban Apple series (Garden Debut)","https://www.greenleafnursery.com/index.cfm/fuseaction/whatsnew.detail/recID/29/index.htm"]],"basis":"sourced","note":"Purchase sheet spells it 'Tandgy green'. Raintree lists the selection as AK-98. Sources differ slightly on color (Raintree: lime green; Gurney's: green with hints of red).","reviewed_on":"2026-10-17"},{"id":"apple-tasty-red","group":"Apple","type":"Apple","kind":"cultivar","name":"Tasty Red (Urban columnar)","aliases":["Urban Red","Tasty Red Urban Columnar"],"inventory_rows":[65],"purchase_rows":[43],"tagline":"Mid; bright red; sweet, firm, juicy; columnar tree","summary":"Urban-series columnar apple from Czech breeder Jaroslav Tupy: bright red, medium, firm, sweet and juicy fruit in mid-September on a narrow 8-10 ft tree. Needs a second apple for pollination.","appearance":"Bright red, medium-sized, firm apples on a narrow columnar tree that grows 8-10 ft tall and stays under about 2 ft wide, with fruit on spurs along the main stem. Flesh color and shape are not described by the sources.","flavor_use":"Firm, sweet and juicy flesh; marketed for fresh eating, baking and preserving. The sources do not state how long it keeps.","uses":["fresh","cooking"],"ripening":"Mid","ripening_note":"Mid-September per Stark Bro's and Gurney's; Raintree calls it early midseason","id_cues":"Narrow columnar tree with fruit on spurs along the trunk; the apples are bright red, medium-sized and firm, ripening mid-September. Many red apples look alike, so rely on the columnar habit and the label rather than fruit color alone.","habit":"Narrow columnar tree, 8-10 ft tall and under about 2 ft wide, with short upright branches and full-size fruit on spurs along the central leader. Fruits within the first couple of years. Growth rate rated vigorous by Greenleaf, slow to moderate by Gurney's.","bark":null,"leaf":"Apple-green leaves in summer with negligible fall color (stated for the whole Urban Apple series).","hardiness":"Zones 4-9 (Raintree); Gurney's lists zones 4-8","sources":[["Raintree Nursery: Tasty Red Urban Columnar Apple","https://raintreenursery.com/products/tasty-red%E2%84%A2-urban%E2%84%A2-columnar-apple-semi-dwarf"],["Stark Bro's: Tasty Red Urban Apple Tree","https://www.starkbros.com/products/fruit-trees/apple-trees/tasty-red-urban-apple"],["Gurney's: Tasty Red Urban Apple","https://www.gurneys.com/products/tasty-red-urban-apple"],["Greenleaf Nursery: Urban Apple series (Garden Debut)","https://www.greenleafnursery.com/index.cfm/fuseaction/whatsnew.detail/recID/29/index.htm"]],"basis":"sourced","note":"Raintree calls it early midseason, while Stark Bro's and Gurney's say mid-September. The sources do not describe flesh color, fruit shape or keeping time.","reviewed_on":"2026-10-17"},{"id":"apple-zestar","group":"Apple","type":"Apple","kind":"cultivar","name":"Zestar!","aliases":["Zestar"],"inventory_rows":[66],"purchase_rows":[45],"tagline":"Earliest; rosy red blush; sweet-tart, brown sugar","summary":"University of Minnesota apple, about 3 inches across and 60 to 85 percent rosy red, with a sprightly sweet-tart flavor and a hint of brown sugar. It ripens at the start of apple season.","appearance":"Round, about 3 inches across. Rosy red blush covers 60 to 85 percent of the skin depending on sun exposure, with creamy yellow on the shaded side.","flavor_use":"Sprightly sweet-tart with a hint of brown sugar, juicy, with a light and crisp texture. Eaten fresh; keeps about 2 months refrigerated.","uses":["fresh"],"ripening":"Early","ripening_note":"Late August to early September in Minnesota, about with Paula Red","id_cues":"Among the earliest apples to ripen. Round, medium-large fruit that is mostly rosy red over creamy yellow, with the most red on the sunny side.","habit":"Somewhat upright to spreading. Vigorous in the early years, then settles into a spur-type habit with moderate vigor (one nursery says low-moderate). Very early bloom and annual bearing. The original own-rooted seedling was about 14 ft tall and 9 ft wide.","bark":"One-year shoots are hairless and moderately shiny, grayed orange on the sunny side, with a medium number of medium-sized lenticels. Lateral buds are medium to large, round-tipped and held flat against the twig (plant patent).","leaf":"Expanded leaves are medium green above and lighter below with moderate down, weak to medium gloss, scalloped margins and a short pointed tip, about 9 cm long and 4 cm wide. Leaves at growing shoot tips are densely hairy and whitish (plant patent).","hardiness":"","sources":[["Minnesota Hardy (University of Minnesota): Zestar!","https://mnhardy.umn.edu/zestar"],["Google Patents: US Plant Patent 11,367, apple tree Minnewashta (Zestar!)","https://patents.google.com/patent/USPP11367P/en"],["Cummins Nursery: Zestar! apple","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=25074"]],"basis":"sourced","reviewed_on":"2026-10-17"},{"id":"apple-empire","group":"Apple","type":"Apple","kind":"cultivar","name":"Empire","aliases":[],"inventory_rows":[],"purchase_rows":[14],"tagline":"Mid; deep maroon-red; crisp white flesh","summary":"Cornell apple from McIntosh and Delicious with intense maroon-red skin, bright white crisp flesh and a sweet, McIntosh-like flavor. Resists bruising and bears heavy, regular crops.","appearance":"Intense maroon-red over a light green background, with bright white flesh.","flavor_use":"Sweet with a crisp texture and the vinous McIntosh flavor, sometimes with a hint of melon or pineapple. Best fresh from the tree; it stores only a short time.","uses":["fresh"],"ripening":"Mid","ripening_note":"Typically late September to early October, just after McIntosh","id_cues":"Very dark maroon-red fruit over light green, firmer than McIntosh, with bright white flesh. The tree is strong and well shaped and crops heavily every year.","habit":"Moderately vigorous to vigorous, precocious tree with a spreading habit and sturdy, well-formed structure. Bears on spurs and crops heavily every year, so thinning is advised for fruit size.","bark":null,"leaf":null,"hardiness":"","sources":[["Orange Pippin: Empire","https://www.orangepippin.com/varieties/apples/empire"],["Cummins Nursery: Empire apple","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=31142"],["Silver Creek Nursery: Empire apple tree","https://silvercreeknursery.ca/products/empire-apple"]],"basis":"general","note":"Ripening timing is a general figure; the listed page covers color, flesh, flavor and bearing.","reviewed_on":"2026-10-17"},{"id":"apple-golden-russet","group":"Apple","type":"Apple","kind":"cultivar","name":"Golden Russet","aliases":[],"inventory_rows":[],"purchase_rows":[22],"tagline":"Very late; russeted bronze skin; dense, rich","summary":"Old American russet apple, small and slightly flattened, with rough golden-yellow to bronze skin and dense, strongly flavored flesh. A long keeper that is prized for cider as well as eating.","appearance":"Small and slightly flattened. Rough russeted skin in golden-yellow to bronze, sometimes with an orange blush on the sunny side.","flavor_use":"Dense, intensely flavored russet-type flesh. Versatile for fresh eating, cooking and juice, and valued for hard cider; keeps well.","uses":["fresh","cooking","cider","storage"],"ripening":"Very late","ripening_note":"Mid to late October in the Northeast; among the last apples picked","id_cues":"Rough russet over most of the skin is the giveaway, on small, slightly squat fruit. It ripens very late, so it is still on the tree after most others are picked.","habit":"1905 New York account: medium-to-large tree of moderate to strong vigor; rounded and upright when young, later spreading and dense, with long limbs whose slender side shoots sag after heavy crops. Fruit on branch ends; usually biennial, sometimes nearly annual. Other apples share this name.","bark":"1905 account: young branches smooth and olive-yellow; new shoots olive-green to muted reddish-brown with gray mottling and fine hairs toward the tips. Many small, pale lenticels give a speckled look. One orchard says dark reddish-olive bark.","leaf":"Leaves are described as dull, dark green with sharply toothed margins (one orchard account).","hardiness":"","sources":[["Orange Pippin: Golden Russet","https://www.orangepippin.com/varieties/apples/golden-russet"],["Internet Archive: The Apples of New York vol. 1 (Beach, 1905), Golden Russet pp. 143-144","https://archive.org/stream/applesofnewyork01beac/applesofnewyork01beac_djvu.txt"],["Albemarle CiderWorks: Golden Russet","https://www.albemarleciderworks.com/orchard/apple/golden-russet"]],"basis":"general","note":"Skin color and ripening timing come from general descriptions; the listed page covers size, shape, flavor and keeping.","reviewed_on":"2026-10-17"},{"id":"pear-anjou","group":"Pear","type":"Pear","kind":"cultivar","name":"D'Anjou","aliases":["Anjou Stan. Supreme","Anjou"],"inventory_rows":[92,101],"purchase_rows":[89],"tagline":"Late; green skin, blunt shape; mild, buttery; long keeper","summary":"Old European winter pear with medium to large, blunt, green to yellow-green fruit and juicy, smooth flesh with mild sweetness. Picked late and stored; used fresh, baked or poached.","appearance":"Medium to large, about 3.5 in. long in old records, with a blunt egg-like pear shape that tapers only slightly to the stem. Thin, smooth, dull skin is green to yellow-green, with fine russet dots and russet at the stem and eye ends. Flesh is whitish.","flavor_use":"Fine, smooth, juicy flesh with mild sweetness and a light aroma; firm enough to hold its shape when baked or poached. Pick hard and ripen off the tree. Refrigerated, it keeps for months (up to 7 per Stark Bro's).","uses":["fresh","cooking","storage"],"ripening":"Late","ripening_note":"Harvest late Sept per Stark Bro's; ripe Oct to Jan in old pomology records","id_cues":"Blunt, egg-like pear that tapers only slightly to the stem. Thin, smooth, dull skin stays mostly green, paling or taking a faint yellow tinge when ripe, with fine russet dots and russet at both ends. Late harvest. Green color alone is a weak cue.","habit":"Vigorous, hardy, fast-growing tree, large and spreading by one account (another says moderate growth). Young shoots go out horizontal, then turn upright; branches spread under fruit weight. Bears early, fruit on shoot tips; cropping reports differ, some call it erratic.","bark":"Smooth trunk. Branches slightly zigzag; thin gray skin covers reddish-brown wood and small lenticels are few. Older wood is grayish olive. Young shoots are yellowish olive, yellowish brown, light green or reddish brown, depending on the source.","leaf":"Large, thin but leathery leaves, oblong to narrow oval with a rounded base, narrowing to a pointed tip; light green, wavy, folded upward. Margin almost smooth to shallowly scalloped (one source says toothed). About 3.5 in long. Fall color pale yellow, sometimes red.","hardiness":"Zones 5-8 per Stark Bro's","sources":[["Stark Bro's: Anjou Pear Tree","https://www.starkbros.com/products/fruit-trees/pear-trees/anjou-pear"],["Heritage Apple Corps: Beurre d'Anjou (compiled old pomology records)","https://heritageapplecorps.org/varieties/beurre-danjou-pear/"],["Oregon State Univ. Extension: Picking and storing apples and pears","https://extension.oregonstate.edu/catalog/pub/fs-147-picking-storing-apples-pears"]],"basis":"sourced","note":"Two inventory lines (Anjou Stan. Supreme and D'Anjou) are the same cultivar: 3 trees on hand vs 2 bought. This profile covers the standard green d'Anjou.","reviewed_on":"2026-10-17"},{"id":"pear-hosui","group":"Pear","type":"Asian pear","kind":"cultivar","name":"Hosui (Asian pear)","aliases":["Asian Hosui","Hosui - Asian","Hosui"],"inventory_rows":[93],"purchase_rows":[96],"tagline":"Mid; round golden-russet; sweet-tart, very juicy","summary":"Japanese Asian pear, introduced in the 1970s, with medium to large round fruit in golden russet. Crisp, very juicy and sweet with a little acidity; eaten mostly fresh in late summer.","appearance":"Round fruit, medium to large, in golden russet with lots of small lenticel dots. The flesh is creamy off-white, fine-grained, delicate yet crisp.","flavor_use":"Crisp and juicy, sweet with a bit more acid than most Asian pears, so it reads sweet-tart. Best fresh; the firm flesh also holds up in pies and desserts and can be canned. Cummins says it stores only about four weeks.","uses":["fresh","cooking","canning"],"ripening":"Mid","ripening_note":"Late August in zones 5-9 (Stark Bro's); Cummins calls it early to midseason","id_cues":"Round, golden-russet fruit with many pale lenticel dots, ripe in late August. Vigorous, willowy, spreading tree. Russet skin alone does not single it out among Asian pears, so check the late-August ripening and the dotted golden skin together.","habit":"Vigorous, spreading tree with willowy growth; among the most vigorous Asian pears in a Polish trial. Crops heavily, so fruit must be thinned to protect fruit size, yearly cropping and the limbs.","bark":null,"leaf":null,"hardiness":"Zones 5-9 (Stark Bro's)","sources":[["Stark Bro's: Hosui Asian Pear","https://www.starkbros.com/products/fruit-trees/pear-trees/hosui-asian-pear"],["Cummins Nursery: Hosui Pear","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=29563"],["Gardenia: Pyrus pyrifolia Hosui (Asian Pear)","https://www.gardenia.net/plant/pyrus-pyrifolia-hosui"],["Acta Scientiarum Polonorum Hortorum Cultus: Asian pear cultivars in Lower Silesia","https://czasopisma.up.lublin.pl/asphc/article/view/377"]],"basis":"sourced","note":"Sources differ: Stark calls it self-pollinating and better than many European pears for fire blight; Cummins says partly self-fertile and susceptible. Cummins storage is 4 weeks in text, 1-3 months in its table.","reviewed_on":"2026-10-17"},{"id":"pear-hardy-giant","group":"Pear","type":"Asian pear","kind":"cultivar","name":"Starking Hardy Giant (Asian pear)","aliases":["Asian, Hardy Giant","Starking Hardy Giant - Asian","Hardy Giant Asian pear"],"inventory_rows":[94],"purchase_rows":[105],"tagline":"Late; huge round brown russet; crisp, long keeper","summary":"Stark Bro's Asian pear of Korean origin with very large, round, fawn-brown russeted fruit picked in October. Crisp, juicy and sweet; eaten fresh and kept in the fridge for months.","appearance":"Very large round fruit, 12 to 15 ounces each, with russeted fawn-brown skin and crisp, juicy flesh.","flavor_use":"Clean, sweet, crisp and juicy, and it needs no ripening time after picking. Stark Bro's claims storage of up to nine months in refrigeration, so one October harvest can supply fresh pears into the following summer.","uses":["fresh","storage"],"ripening":"Late","ripening_note":"October harvest per Stark Bro's; Planting Justice gives early to mid October for the similar Korean Giant","id_cues":"Huge round brown-russet Asian pear picked in October, with early bloom. Olympic/Korean Giant is described very similarly (Korea, 1969, about a pound, brown russet, October, 9-month keeper), so fruit alone may not tell them apart.","habit":"Stark Bro's describes early bloom and consistent heavy cropping, and lists a mature size of about 12-15 ft tall by 9-11 ft wide.","bark":null,"leaf":null,"hardiness":"Hardy to zone 4 (Stark Bro's)","sources":[["Stark Bro's: Starking Hardy Giant Asian Pear","https://www.starkbros.com/products/fruit-trees/pear-trees/starking-hardy-giant-asian-pear"],["Planting Justice: Korean Giant Asian Pear","https://plantingjustice.org/products/korean-giant-organic"]],"basis":"sourced","note":"Stark's description closely matches Olympic/Korean Giant, but no page found says they are the same variety. If they are, the Hardy Giant and Olympic Giant trees could be one cultivar sold under two names.","reviewed_on":"2026-10-17"},{"id":"pear-shinseiki","group":"Pear","type":"Asian pear","kind":"cultivar","name":"Shinseiki (Asian pear)","aliases":["Asian, Shinseiki","Shinseiki - Asian","Shinseiki"],"inventory_rows":[95],"purchase_rows":[103],"tagline":"Mid; yellow skin; crisp, sweet, slightly tart","summary":"Early-season Japanese Asian pear (also sold as New Century) with bright yellow skin and crisp, juicy, sweet-slightly tart flesh. Self-fertile, bears young, and is eaten mostly fresh.","appearance":"Medium-size round fruit with thin, smooth, bright yellow skin marked by faint pale dots. The flesh is cream to white, crisp and very juicy.","flavor_use":"Sweet with a slight tartness, crisp and very juicy; good fresh or sliced into salads, and listed for canning. Fruit hangs well on the tree and stores about two months. Thin the crop to prevent broken limbs and skipped years.","uses":["fresh","canning"],"ripening":"Mid","ripening_note":"Late summer per Raintree; Cummins calls it early-season, ripening about with Hosui","id_cues":"Bright yellow, smooth-skinned round Asian pear with faint pale speckling, ripe in late summer about when Hosui is. Self-fertile tree that starts bearing in two to three years and sets heavy crops that need thinning.","habit":"Medium size and vigor, spreading and medium dense (UC Extension); smallest of six Asian pears in a Polish trial. Flower buds form at the tips of short spurs on 2-3 year wood. Bears from 2-3 years; heavy crops need thinning to avoid limb breakage.","bark":"Trunk bark is a little rough, dark brown beneath a scaly grayish-white corky layer. Branch bark is smooth and brown, shedding in patches, with large raised tan or grayish-white lenticels. Twigs greenish brown to brown, new tips whitish-hairy.","leaf":"Ovate, stiff, leathery leaves about 4 in long and 3 in wide, pointed tip, rounded base; most fold upward along the midrib. Dark green above, light green and nearly hairless beneath; sharply toothed. Young leaves are light green and hairy.","hardiness":"Cold hardy to zone 5 (Raintree)","sources":[["Cummins Nursery: Shinseiki Pear","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=21565"],["Raintree Nursery: Shinseiki Asian Pear","https://raintreenursery.com/products/shinseiki-a-pear-semi-dwarf"],["J. Frank Schmidt & Son: Shinseiki Asian Pear","https://jfschmidt.com/all-trees/shinseiki-asian-pear/"],["University of California Cooperative Extension: Asian Pear Varieties in California","https://fruitsandnuts.ucdavis.edu/sites/g/files/dgvnsk12441/files/391-770.pdf"],["Acta Scientiarum Polonorum Hortorum Cultus: Asian pear cultivars in Lower Silesia","https://czasopisma.up.lublin.pl/asphc/article/view/377"]],"basis":"sourced","note":"Sources differ on fire blight: Cummins calls it susceptible, Raintree says moderate resistance. Also sold as New Century (the English meaning of the name).","reviewed_on":"2026-10-17"},{"id":"pear-barnet-perry","group":"Pear","type":"Perry pear","kind":"cultivar","name":"Barnet (perry pear)","aliases":["Barnet Euro","Barnett European Perry Pear","Barnett"],"inventory_rows":[96],"purchase_rows":[90],"tagline":"Late; small, russeted all over; light perry","summary":"Old Gloucestershire perry pear, also called Hedgehog Pear, with small russeted fruit shaken from the tree in October. Makes a light, low-tannin, low-acid perry; the tree bears young.","appearance":"Small turbinate (top-shaped) pears with greenish-yellow skin flushed orange-red and russeted all over, which is unusual for perry pears. Windfalls are said to resemble little hedgehogs.","flavor_use":"Grown for juice, pressed alone or blended to make a light, low-tannin, low-acid perry. The fruit is astringent yet edible, passable fresh or cooked. Shake the pears down when ripe and press within 1 to 3 weeks.","uses":["perry"],"ripening":"Late","ripening_note":"October per Raintree and Orange Pippin; early to mid October in England (Walcot Nursery)","id_cues":"Whole fruit is russeted, which is rare in perry pears, with a faint orange-red flush; windfalls resemble hedgehogs. Blooms late (Raintree). Tree shape is a weak cue: a UK nursery says spreading head, Raintree says upright and compact.","habit":"Moderately vigorous, medium to large tree; precocious and heavy but prone to biennial crops. Shape sources differ: compact and upright with narrow branch angles and distinct spurs (Raintree, Brooks and Olmo) versus a spreading head (Walcot).","bark":null,"leaf":null,"hardiness":"Zones 4-9 (Raintree)","sources":[["Raintree Nursery: Barnett European Perry Pear","https://raintreenursery.com/products/barnett-perry-pear-ohxf-87"],["Walcot Organic Nursery: Barnet","https://walcotnursery.co.uk/product/barnet/"],["Orange Pippin: Barnet pear","https://www.orangepippin.com/varieties/pears/barnet"],["Flowering Plant Nursery: Perry Pear Barnet (Brooks and Olmo notes)","https://www.floweringplantnursery.com/product/pear-barnet/"]],"basis":"sourced","note":"Raintree spells it Barnett. Other names: Hedgehog Pear, Barn Pear, Brown Thorn Pear. Raintree says biennial bearing and upright habit; the UK nursery says heavy early cropping and a spreading head.","reviewed_on":"2026-10-17"},{"id":"pear-bartlett","group":"Pear","type":"Pear","kind":"cultivar","name":"Bartlett","aliases":[],"inventory_rows":[97],"purchase_rows":[91,92],"tagline":"Mid; green turning yellow; sweet, juicy, aromatic","summary":"Leading US commercial pear (about half of production), with bell-shaped fruit that goes from speckled green to clear yellow. Sweet, aromatic, juicy flesh; good fresh, baked and canned. Fire blight is its weak point.","appearance":"Classic pear outline: broad bottom half tapering to a slim neck. Thin skin dotted with fine speckles, green at first and clear yellow when ripe, sometimes with faint red behind it. Flesh is fine-grained and very juicy.","flavor_use":"Sweet and aromatic with a light spiciness. Keeps its form when baked or canned and is also good fresh. Pick while still green and let it finish ripening off the tree; the skin turns yellow as it ripens.","uses":["fresh","cooking","canning"],"ripening":"Mid","ripening_note":"About Aug 20 in upstate New York (Cummins); early Sept in New Hampshire (UNH)","id_cues":"Bell-shaped pear with thin, speckled skin that changes from green to clear yellow as it ripens, sometimes with faint red behind it. Vigorous tree with white spring bloom. Ready late Aug to early Sept. Yellow color alone is shared with other pears.","habit":"Vigorous to very vigorous, upright tree that grows fast; medium to large, with a tall, pear-shaped crown as it ages, though one old source calls growth moderate. Long-lived, easy to manage, bears young. Blooms white in spring.","bark":"Branches stocky and smooth, reddish brown under a thin ash-gray outer skin; lenticels few. Twigs short-jointed, reddish brown, glossy and hairless with conspicuous lenticels. Shoots yellowish to yellow-brown; leaf scars prominent.","leaf":"Oval, leathery leaves with a tapered tip and fine teeth topped with tiny dark red glands; roughly 2.5 by 1.5 in, often folded. One old source says the leaves persist late and turn deep crimson in fall.","hardiness":"Zones 5-8 (Stark Bro's); lows seldom below -25 F (UNH)","sources":[["Cummins Nursery: Bartlett Pear on OHxF 87","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=21531"],["Stark Bro's: Bartlett Pear Tree","https://www.starkbros.com/products/fruit-trees/pear-trees/bartlett-pear"],["Univ. of New Hampshire Extension: Growing pears in the home orchard","https://extension.unh.edu/resource/growing-fruits-growing-pears-home-orchard-fact-sheet"],["Heritage Apple Corps: Bartlett pear (compiled old pomology records)","https://heritageapplecorps.org/varieties/bartlett-pear/"]],"basis":"sourced","note":"Two trees from different vendors; confirm both by fruit. Known as Williams in Europe. Hardiness is marginal where winters drop below about -25 F.","reviewed_on":"2026-10-17"},{"id":"pear-red-bartlett","group":"Pear","type":"Pear","kind":"cultivar","name":"Red Bartlett","aliases":["Bartlett, Red"],"inventory_rows":[98],"purchase_rows":[102],"tagline":"Mid; red-skinned Bartlett sport; sweet, juicy","summary":"A red-skinned bud sport of Bartlett found near Zillah, Washington, in 1938. Same bell shape and sweet, juicy, aromatic flesh as Bartlett; the red color is only skin deep.","appearance":"Bartlett shape: full rounded lower half that steps in at the shoulders to a narrower neck. Skin is deep red, sometimes with pale lengthwise stripes over green, turning a brighter red as the fruit ripens. The red stays in the skin only.","flavor_use":"Sweet, aromatic, juicy and smooth, much like yellow Bartlett. Good fresh, baked and canned; peeling removes the red, so color does not matter for preserving. Pick mature but still firm and ripen off the tree.","uses":["fresh","cooking","canning"],"ripening":"Mid","ripening_note":"Late Aug to early Sept in the Pacific Northwest (USA Pears)","id_cues":"Bartlett outline in red: deep red, sometimes lightly striped, getting brighter as it ripens, which most pears do not do. Other red pears exist (Starkrimson, Red Anjou), so use the Bartlett shape and late Aug to early Sept timing.","habit":"Bud sport of Bartlett. One nursery calls the tree vigorous and nearly identical to Bartlett apart from red fruit skin; another calls it very vigorous and easy to grow, starting to bear 2-3 years after it is planted. Listed at 10-12 ft on a dwarfing rootstock.","bark":null,"leaf":null,"hardiness":"Not stated; Bartlett is reasonably hardy where lows seldom pass -25 F (UNH)","sources":[["Washington State Univ. Tree Fruit: Red Bartlett","https://treefruit.wsu.edu/variety/red-bartlett/"],["USA Pears: Red Bartlett pear","https://www.usapears.org/red-bartlett/"],["Univ. of New Hampshire Extension: Growing pears in the home orchard","https://extension.unh.edu/resource/growing-fruits-growing-pears-home-orchard-fact-sheet"],["One Green World: Red Bartlett Pear","https://onegreenworld.com/product/red-bartlett-pear/"],["Tree Top Nursery: Pear Red Bartlett","https://www.treetop-nursery.com/plants/pear-red-bartlett/"]],"basis":"sourced","note":"Bud sport of Bartlett, also sold as Max Red. Lowes tree with unknown rootstock; confirm by fruit color and shape.","reviewed_on":"2026-10-17"},{"id":"pear-butt-perry","group":"Pear","type":"Perry pear","kind":"cultivar","name":"Butt (perry pear)","aliases":["Butt Euro Perry","Butt European Perry Pear"],"inventory_rows":[99],"purchase_rows":[93],"tagline":"Late; small lemon-yellow; astringent perry pear","summary":"Traditional English perry pear, also called Norton Butt, with small round lemon-yellow fruit. Not for fresh eating; pressed late for a fruity, astringent perry.","appearance":"Small globular fruit in lemon yellow, flecked with russet spots; the flesh is off-white. Raintree describes it as small, yellow and slightly russeted.","flavor_use":"Perry only. The juice is astringent and fruity and slow to ferment. The fruit is unusually durable and can sit on the ground without rotting; it can be milled 4 to 10 weeks after harvest.","uses":["perry"],"ripening":"Late","ripening_note":"October per Raintree; late season (November) per England's National Perry Pear Centre","id_cues":"Small round lemon-yellow pears flecked with russet that stay sound for weeks on the ground. Vigorous tree with narrow-angled crotches; slow to begin bearing, then heavy, with biennial swings. Late blooming, with late-season fruit.","habit":"Vigorous tree that grows large. Raintree and Cummins describe narrow crotch angles, while Walcot (UK) says the limbs spread and may droop. Slow to begin bearing, then heavy crops with a biennial tendency.","bark":null,"leaf":null,"hardiness":"Zones 4-9 (Raintree)","sources":[["Raintree Nursery: Butt European Perry Pear","https://raintreenursery.com/products/butt-perry-pear-semi-dwarf"],["Cummins Nursery: Butt Pear","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=21609"],["National Perry Pear Centre: Butt","https://www.nationalperrypearcentre.org.uk/pear/butt/"],["Walcot Organic Nursery: Butt","https://walcotnursery.co.uk/product/butt/"]],"basis":"sourced","note":"Tannin level differs: Cummins says high, Raintree says moderate. Ripening is October per Raintree but November in England.","reviewed_on":"2026-10-17"},{"id":"pear-comice","group":"Pear","type":"Pear","kind":"cultivar","name":"Comice","aliases":["Doyenne du Comice"],"inventory_rows":[100],"purchase_rows":[94],"tagline":"Late; squat, green-yellow, red blush; buttery, aromatic","summary":"French dessert pear with large, short, rounded greenish-yellow fruit that is often red-blushed. Sweet, aromatic, tender, buttery flesh; eaten mainly fresh after a spell in cold storage.","appearance":"Large, squat, rounded body, green turning greenish-yellow when ripe. Patches of red blush are common, and a few newer strains are mostly red.","flavor_use":"Sweet and aromatic, with tender, buttery flesh; mainly a fresh-eating pear. Must spend time in cold storage before it ripens fully and keeps about 3 months or more. Picking later builds flavor; picking earlier extends storage life.","uses":["fresh","storage"],"ripening":"Late","ripening_note":"Late Sept to early Oct per Bemis Tree Farm; Trees of Antiquity calls it a very late harvest","id_cues":"Large, squat, round-bodied fruit, green to greenish-yellow when ripe, often red-blushed (a few strains mostly red). Blooms mid to late season; tree is compact and upright (12-18 ft) with glossy leaves turning red and yellow. Color alone is shared with other pears.","habit":"Upright, dense tree whose vigor is rated moderate to high; one old source says growth is moderate and upright-spreading. Young nursery trees start slowly. Compact form listed at 12-18 ft tall and wide. Blooms mid to late season; bears fairly freely but not always reliably.","bark":"Smooth branches in dull gray with greenish brown mixed in, carrying large lenticels. Young wood reddish yellow-brown; branchlets long, hairless, brown tinged red, with many small raised lenticels. Buds large, conical and pointed, with prominent leaf scars.","leaf":"Glossy green, medium-sized, oval to somewhat elongated and leathery, folded upward and curving down, with finely and evenly toothed shallow edges; roughly 3.5 by 1.5 in. Fall color red and yellow per one nursery.","hardiness":"Zones 6-10 per Trees of Antiquity","sources":[["Washington State Univ. Tree Fruit: Comice","https://treefruit.wsu.edu/variety/comice/"],["Bemis Tree Farm: Comice Pear Tree","https://www.bemistreefarm.com/comice-pear-tree/"],["Trees of Antiquity: Comice Pear Tree","https://www.treesofantiquity.com/products/comice-pear"],["Heritage Apple Corps: Doyenne du Comice pear (compiled old pomology records)","https://heritageapplecorps.org/varieties/doyenne-du-comice-pear/"]],"basis":"sourced","note":"Proper name is Doyenne du Comice. Trees of Antiquity rates it zones 6-10, so winter hardiness at a zone 4-5 site is a risk.","reviewed_on":"2026-10-17"},{"id":"pear-starking-delicious","group":"Pear","type":"Pear","kind":"cultivar","name":"Starking Delicious","aliases":["Delicious"],"inventory_rows":[102],"purchase_rows":[104],"tagline":"Mid; large yellow-green; sweet, juicy, easy to peel","summary":"Pear found as a seedling in Ohio in 1930 and sold by Stark Bro's since 1953. Large, sweet, juicy fruit on a heavy-bearing tree with good fire blight resistance; treated as identical to Maxine.","appearance":"Large (one nursery says medium), smooth yellow-green fruit, often covered in light russet. The skin peels easily; flesh is firm and juicy.","flavor_use":"Sweet, juicy, Bartlett-style flavor with firm flesh. Used fresh, canned and preserved. Fridge life is about 1-2 months per Orange Pippin Trees. Needs aggressive fruitlet thinning in late May because it over-sets.","uses":["fresh","cooking","canning","pollinizer"],"ripening":"Mid","ripening_note":"Aug per Stark Bro's; end of Aug, a bit after Bartlett, per Orange Pippin Trees","id_cues":"Smooth, large yellow-green pear, often with light russet and an easy-peel skin. Ripens near or just after Bartlett. Sets heavy crops (needs thinning) and strongly resists fire blight. Fruit size reports differ, so size is a weak cue.","habit":"Vigorous, upright tree (dense and upright-spreading in one listing); Maxine and Starking Delicious are treated as one pear. About 20 ft tall and wide, or 10-16 ft after 10 years semi-standard. Heavy bearer that over-sets fruit and needs hard thinning.","bark":null,"leaf":"Dark green leaves, listed as glossy and pointed, turning coppery-bronze in fall (one Stark-branded plant listing).","hardiness":"Zone 5 per Orange Pippin Trees; 5-8 per 39th Parallel","sources":[["Stark Bro's: Starking Delicious Pear Tree","https://www.starkbros.com/products/fruit-trees/pear-trees/starking-delicious-pear"],["Orange Pippin Fruit Trees: Maxine pear (same as Starking Delicious)","https://www.orangepippintrees.com/trees/pear-trees/maxine"],["39th Parallel Nursery: Maxine pear","https://39thparallel.com/maxine/"],["Cummins Nursery: Maxine Pear on OHxF 87 (same as Starking Delicious)","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=29566"],["Franz Witte plant finder: Starking Delicious Pear","https://plants.franzwitte.com/12150021/Plant/29112/Starking_Delicious_Pear"]],"basis":"sourced","note":"Inventory lists it as plain 'Delicious'; this is the pear, not the apple of that name. Orange Pippin Trees says it is now considered identical to the older Maxine pear.","reviewed_on":"2026-10-17"},{"id":"pear-hendre-huffcap-perry","group":"Pear","type":"Perry pear","kind":"cultivar","name":"Hendre Huffcap (perry pear)","aliases":["Hendre Huffeap","Hendre Huffcapp European Perry Pear","Hendre Huffcapp"],"inventory_rows":[103],"purchase_rows":[95],"tagline":"Late; small elliptical; light low-tannin perry","summary":"Traditional English perry pear of the Huffcap type, with small elliptical green-yellow fruit. A very productive, early-bearing tree that makes a light, low-tannin perry; not for fresh eating.","appearance":"Small oval-elongated (elliptical) fruit; the green-yellow skin carries a faint orange blush, with a little russet at both the stem and eye ends. Off-white flesh, with grit clustered at the core and eye end.","flavor_use":"Perry only; the juice is light, low in tannin and rated good quality. Mill within about two weeks of harvest. The tree crops very heavily, so thin the fruit to prevent limb breakage.","uses":["perry"],"ripening":"Late","ripening_note":"October per Raintree; Cummins calls it midseason","id_cues":"Small elliptical green-yellow pears with a faint orange blush and russet at stem and eye. Raintree calls the tree extremely upright and pairs it with an early-blooming pollinizer; Cummins notes wide crotch angles and early, heavy bearing. Related to, but distinct from, Yellow Huffcap.","habit":"Large, precocious, very productive tree. Branches are upright (Raintree: extremely upright) though Cummins reports typically wide crotch angles. Heavy crops can break limbs, so fruit needs thinning.","bark":null,"leaf":null,"hardiness":"Zones 4-9 (Raintree)","sources":[["Raintree Nursery: Hendre Huffcapp European Perry Pear","https://raintreenursery.com/products/hendre-huffcapp-e-pear-semi-dwarf"],["Cummins Nursery: Hendre Huffcap Pear","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=29560"],["Raintree Nursery: Thorn European Perry Pear","https://raintreenursery.com/products/thorn-e-perry-pear-semi-dwarf"],["Frank P Matthews: Hendre Huffcap","https://www.frankpmatthews.com/catalogue/fruit-trees/pear/hendre-huffcap-perry/"]],"basis":"sourced","note":"Inventory has 2 Hendre trees but 1 was bought; a Thorn perry pear was bought but not found, so one may be Thorn (small yellow fruit, orange flush, upright tree, ripe Sept per Raintree). Compare ripening dates. The National Perry Pear Centre lists Yellow Huffcap as a synonym of this pear, so the Hendre and Yellow Huffcap trees may be the same cultivar.","reviewed_on":"2026-10-17"},{"id":"pear-kieffer","group":"Pear","type":"Pear","kind":"cultivar","name":"Kieffer","aliases":["Keiffer"],"inventory_rows":[104],"purchase_rows":[97],"tagline":"Late; yellow, crimson blush; crisp, coarse; canning pear","summary":"Old American hybrid of Bartlett and an Asian pear, grown mainly for canning and cooking. Golden-yellow fruit with crisp, coarse white flesh on a heavy-bearing, fire blight resistant tree.","appearance":"Yellow to golden-yellow fruit, often with a crimson blush, and white flesh that is crisp, coarse and a bit gritty, a trait that comes from the Asian pear side of its ancestry.","flavor_use":"Firm, coarse and gritty when raw, so it is usually cooked: canned, baked, or made into preserves and pear butter. Pick hard and ripen off the tree; it stores three months or more.","uses":["cooking","canning","storage"],"ripening":"Late","ripening_note":"Late Sept to Oct per Arbor Day Foundation; Cummins calls it very late","id_cues":"Golden-yellow fruit often blushed crimson, with crisp, coarse, gritty flesh. Heavy crops, self-fertile and very resistant to fire blight. Picked hard in late Sept to Oct. The coarse texture and late timing are better cues than color.","habit":"Very vigorous, medium-sized, upright, dense-topped tree; fast-growing and long-lived. Bears early and very heavily, though an old account says it may set fruit sparingly in large single-variety blocks. Listed at 12-16 ft on semi-dwarf rootstock.","bark":"Slender branches, almost smooth and reddish-brown, with only a few small lenticels.","leaf":"Large, thick, leathery leaves, dark green and glossy, oval with a tapered tip and often finely toothed edges; roughly 3.75 by 1.75 in.","hardiness":"Zones 4-9 per Food Forest Nursery","sources":[["Cummins Nursery: Kieffer Pear on OHxF 87","https://www.cumminsnursery.com/buy-trees/product-detail.php?id=34202"],["Arbor Day Foundation: Kieffer Pear tree guide","https://shop.arborday.org/treeguide/359"],["Food Forest Nursery: Kieffer Pear","https://www.foodforestnursery.com/product/kieffer-pear/"],["Heritage Apple Corps: Kieffer pear (compiled old pomology records)","https://heritageapplecorps.org/varieties/kieffer-pear/"]],"basis":"sourced","note":"Purchase sheet spells it Keiffer; the usual spelling is Kieffer (named for breeder Peter Kieffer).","reviewed_on":"2026-10-17"},{"id":"pear-moonglow","group":"Pear","type":"Pear","kind":"cultivar","name":"Moonglow","aliases":[],"inventory_rows":[105],"purchase_rows":[98],"tagline":"Mid; yellow, pink blush; soft, juicy, mild","summary":"Pear released by the USDA in 1960, with large green-yellow fruit blushed pink and soft, juicy flesh. The tree is highly fire blight resistant and a good pollen source for other pears.","appearance":"Medium to large fruit, green-yellow to golden-yellow or yellow-tan, blushed pink to red and similar in look to Bartlett. White flesh, soft and juicy with almost no grit.","flavor_use":"Mild to rich, aromatic flavor (sources differ) and soft, juicy flesh. Used fresh, baked, canned and as juice. Fruit may need 6-8 weeks of storage for full flavor; fresh-picked fruit is acidic enough for baking.","uses":["fresh","cooking","canning","juice","pollinizer"],"ripening":"Mid","ripening_note":"Early Aug, about 2 wk before Bartlett, per Gurney's; Stark Bro's says Sept","id_cues":"Very upright, vigorous, heavily spurred tree. Fruit looks Bartlett-like but is blushed pink or red and soft with almost no grit. Fire blight resistance is a useful but weak cue. Not self-fertile, so it sets fruit only with another pear nearby.","habit":"Strongly upright, vigorous tree carrying many fruiting spurs; bears young and heavily. Mature height is given as 15-20 ft for a standard tree by one source and 25 ft by another, which rates growth as medium.","bark":null,"leaf":"Leaves elliptic in shape, glossy and green, with red and yellow fall color, per one plant-encyclopedia listing.","hardiness":"Zones 5-8 per Gurney's (same page also lists 7-9)","sources":[["Cummins Nursery: Moonglow Pear on OHxF 87","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=21556"],["Stark Bro's: Moonglow Pear Tree","https://www.starkbros.com/products/fruit-trees/pear-trees/moonglow-pear"],["Gurney's: Moonglow Pear Tree","https://www.gurneys.com/products/moonglow-pear"],["Gardenia: Pyrus communis Moonglow (European pear)","https://www.gardenia.net/plant/pyrus-communis-moonglow"]],"basis":"sourced","note":"Sources disagree on ripening (early Aug, 2 weeks before Bartlett, vs Sept) and on flavor (rich and aromatic vs mild and subacid).","reviewed_on":"2026-10-17"},{"id":"pear-olympic-giant","group":"Pear","type":"Asian pear","kind":"cultivar","name":"Olympic Giant (Asian pear)","aliases":["Olympic Giant","Olympic Giant - Asian"],"inventory_rows":[106],"purchase_rows":[99],"tagline":"Late; huge brown russet; sweet, crisp, long keeper","summary":"Giant russeted Asian pear, also sold as Korean Giant, Olympic and Dan Beh, picked in mid to late October. Crisp, juicy and sweet; eaten fresh and stored for months.","appearance":"Very large round fruit, up to a pound or more (about grapefruit size), with dark brown to bronze russeted skin. The flesh is white, juicy and crisp.","flavor_use":"Sweet and high in sugar, crisp and juicy, with an unusual earthy note. Eaten fresh; a good keeper, with nurseries quoting about 5 to 6 months in storage.","uses":["fresh","storage"],"ripening":"Late","ripening_note":"About mid-October (Loen) to mid or late October (Ison's)","id_cues":"Giant, round, dark-brown russet Asian pear ripening mid to late October. Starking Hardy Giant (Stark Bro's) has a very similar description: round, brown russet, picked in October, long keeper, so fruit alone may not separate the two.","habit":"Vigorous, upright tree that blooms early and begins bearing about its third year. One nursery lists 10-12 ft at maturity; another says 20 ft or more on standard rootstock.","bark":null,"leaf":null,"hardiness":"Zones 5-9 (Ison's)","sources":[["Loen Nursery: Asian Pear 'Olympic' (aka Korean Giant)","https://www.loennursery.com/products/frt-op-olp"],["Ison's Nursery: Korean Giant Asian Pear Tree","https://www.isons.com/shop/fruit-trees/asian-pear-trees/korean-giant-asian-pear-tree/"],["Stark Bro's: Starking Hardy Giant Asian Pear","https://www.starkbros.com/products/fruit-trees/pear-trees/starking-hardy-giant-asian-pear"],["Planting Justice: Korean Giant Asian Pear","https://plantingjustice.org/products/korean-giant-organic"],["Blue Hill Wildlife Nursery: Korean Giant Pear","https://bluehillwildlifenursery.com/product/korean-giant-olympic-pear-large/"]],"basis":"sourced","note":"Olympic and Korean Giant are the same pear per these nurseries. Starking Hardy Giant may be the same variety under another name; no page found confirms it.","reviewed_on":"2026-10-17"},{"id":"pear-parker","group":"Pear","type":"Pear","kind":"cultivar","name":"Parker","aliases":[],"inventory_rows":[107],"purchase_rows":[100],"tagline":"Mid; yellow-bronze, red blush; hardy, tender-juicy","summary":"Cold-climate pear released by the University of Minnesota in 1934, with medium to large yellow-bronze fruit and tender, juicy flesh. Upright tree that is prone to fire blight; best eaten fresh.","appearance":"Medium to large, somewhat round fruit, yellow-bronze with a red blush on the side that gets the most sun. White flesh with a fine grain, tender and juicy.","flavor_use":"UMN compares it to Bartlett for size, taste and texture. Best fresh; also used for baking and juice, though one nursery calls it too soft for canning. UMN advises picking before it is ripe; Johnson's says tree-ripe also works.","uses":["fresh","cooking","juice"],"ripening":"Mid","ripening_note":"Sept per UMN Hardy and Johnson's Nursery; one UMN Extension table says mid Aug","id_cues":"Upright, vigorous, vase-shaped tree about 18 ft tall with white blossoms in mid-May (Wisconsin). Medium-large yellow-bronze fruit with a red blush in Sept. Fruit is Bartlett-like, so tree shape and extra hardiness are better cues.","habit":"Upright, vigorous, compact tree with a dense vase-shaped or upright-spreading crown. About 15-20 ft tall and 15-18 ft wide; pruning on semi-dwarf rootstock can hold it near 15 ft.","bark":"Furrowed brown bark, described as plain rather than ornamental.","leaf":"Dark green all season, glossy and pointed, turning deep purple in fall. Leaves can yellow (chlorosis) on alkaline soils.","hardiness":"UMN rates it good to poor; may not be hardy north of Twin Cities","sources":[["Univ. of Minnesota: Minnesota Hardy pears","https://mnhardy.umn.edu/pears"],["Univ. of Minnesota Extension: Growing pears","https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/growing-pears"],["Johnson's Nursery: Parker Pear","https://kb.jniplants.com/parker-pear-pyrus-communis"],["Univ. of Minnesota UFOR Nursery and Lab: Parker pear","https://trees.umn.edu/nursery-tour/species/pape"]],"basis":"sourced","note":"Sources disagree on harvest (mid Aug vs Sept) and on tree-ripe picking. It may set a little fruit alone, but plant a second pear nearby. Fire blight is the main risk.","reviewed_on":"2026-10-17"},{"id":"pear-pineapple","group":"Pear","type":"Pear","kind":"cultivar","name":"Pineapple","aliases":[],"inventory_rows":[108],"purchase_rows":[101],"tagline":"Mid; golden russet, crisp; sweet-tart, pineapple note","summary":"Low-chill pear that has done well in the Deep South, with large fruit in golden, russeted skin that stays crisp and firm and has a sweet-tart, pineapple-like note. Used for cooking, canning and fresh eating once fully ripe.","appearance":"Large fruit with golden skin and russet, firm and crisp (nurseries call it a hard pear), holding its shape when cooked.","flavor_use":"Sweet-tart with a hint of pineapple; crisp and firm, so it suits cooking, canning, baking and preserves. Nurseries say it can be eaten fresh once fully ripe. They list an August harvest.","uses":["fresh","cooking","canning"],"ripening":"Mid","ripening_note":"Aug to Sept per Willis Orchards and Chestnut Hill; no northern timing found","id_cues":"Large golden-russet fruit that stays firm and crisp, on a vigorous tree (20-30 ft) that is self-fertile and bears young. A low-chill type that can bloom very early. These cues are weak without a tag, as few sources describe the fruit in detail.","habit":"Vigorous, fast-growing, long-lived tree with a dense upright-oval to upright-spreading crown; starts bearing in 2-3 years. Most sources list 15-20 ft tall and 12-15 ft wide; one nursery says 20-30 ft by 10-20 ft.","bark":null,"leaf":"Forest-green leaves, listed as glossy and pointed; fall color is yellow to red (plant-database listing).","hardiness":"Zones 5-9 per Willis Orchards and Chestnut Hill","sources":[["Willis Orchard Company: Pineapple Pear Tree","https://www.willisorchards.com/product/pineapple-pear-tree"],["Chestnut Hill Tree Farm: Pineapple Pear Tree","https://chestnuthilltreefarm.com/shop/pineapple-pear/"],["LSU AgCenter: Choose a pear variety suited to our climate","https://www.lsuagcenter.com/profiles/mhferguson/articles/page1607612529906"],["Franz Witte plant finder: Pineapple Pear","https://plants.franzwitte.com/12150021/Plant/36156/Pineapple_Pear"],["Ison's Nursery: Pineapple Pear Tree","https://www.isons.com/shop/fruit-trees/pear/pineapple-pear-tree/"]],"basis":"sourced","note":"Died in 2026. Sources are nursery pages and a Louisiana extension article; no cold-climate trial found. Low-chill trees can bloom early and lose flowers to frost (LSU).","reviewed_on":"2026-10-17"},{"id":"pear-summercrisp","group":"Pear","type":"Pear","kind":"cultivar","name":"Summercrisp","aliases":[],"inventory_rows":[109],"purchase_rows":[106],"tagline":"Early; green, red blush; crisp, mild-sweet","summary":"Cold-hardy University of Minnesota pear, picked firm and green in mid-August. Crisp, juicy and mildly sweet with an Asian-pear texture; meant for fresh eating, not canning.","appearance":"Classic pear-shaped fruit about 3 to 4 inches long and 2.5 to 3.5 inches wide, green overall with a red blush and noticeable red lenticel dots; borne on many short spurs.","flavor_use":"Sweet and mild with a crisp, juicy bite when eaten unripened. Chill it right after picking; it keeps about six weeks in the fridge. Do not let it ripen: soft, yellowing fruit turns gritty, brown near the seeds and strongly scented.","uses":["fresh","pollinizer"],"ripening":"Early","ripening_note":"Mid-August (Aug 10-15 at Excelsior, Minnesota), about five weeks before Parker, Patten and Luscious","id_cues":"Ripens mid-August, weeks ahead of Parker, Patten and Luscious, and is picked while still green with a red blush and red dots. Pear-shaped, not round. Conical tree 18 to 25 feet tall; leaves glossy dark green above, gray beneath; blooms with Parker and Patten.","habit":"Mature tree is conical and 18 to 25 ft tall. It flowers every year and carries its fruit on numerous spurs.","bark":"Wood at one year old is deep reddish brown and dotted with tan lenticels; it fades to gray as it ages.","leaf":"Leaves are 2.5 to 3.5 in long and 1.5 to 2 in wide with serrate margins; the upper side is shiny deep green and the underside dull gray.","hardiness":"Zone 4; hardiest of the University of Minnesota pears","sources":[["Univ. of Minnesota: Summercrisp Pear (Luby et al. release notice)","https://conservancy.umn.edu/server/api/core/bitstreams/cc92f668-17b9-4ee4-ad66-08b010df4707/content"],["Univ. of Minnesota Extension: Growing pears","https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/growing-pears"],["Univ. of Minnesota: Minnesota Hardy - Pears","https://mnhardy.umn.edu/pears"]],"basis":"sourced","note":"Needs another pear for cross-pollination but makes plenty of pollen. Release year is 1985 on the Extension page and 1986 on Minnesota Hardy; parentage is unknown.","reviewed_on":"2026-10-17"},{"id":"pear-yellow-huffcap-perry","group":"Pear","type":"Perry pear","kind":"cultivar","name":"Yellow Huffcap (perry pear)","aliases":["Yellow Huffcapp","Yellow Huffcapp European Perry Pear"],"inventory_rows":[110],"purchase_rows":[108],"tagline":"Mid; small elliptical yellow-green; sharp perry","summary":"Old English perry pear of the Huffcap type with small, elliptical, yellow-green fruit on a large, spreading tree. Makes a medium-sharp, full-flavored perry; not eaten fresh.","appearance":"Small elliptical pear with green-yellow skin that is russeted around the stem. The flesh is yellowish and a bit gritty.","flavor_use":"Used only for perry, giving a medium-sharp, full-flavored juice that is higher in acid and low in tannin. Pick slightly underripe because fruit clings to the tree and rots; mill within a week of harvest.","uses":["perry"],"ripening":"Mid","ripening_note":"Mid to late September in Western Oregon (Raintree); Cummins calls it midseason","id_cues":"Small elliptical green-yellow pears with russet at the stem that hang on the tree and over-ripen rather than dropping. Large tree with spreading limbs, slow to start bearing, then heavy with biennial swings. Huffcap is a name shared by several perry pears.","habit":"Large, vigorous tree whose limbs spread outward. Slow to begin bearing, then very productive, with a tendency to biennial crops; thinning fruit in June helps keep annual cropping.","bark":null,"leaf":null,"hardiness":"Zones 5-9 (Raintree)","sources":[["Raintree Nursery: Yellow Huffcapp European Perry Pear","https://raintreenursery.com/products/yellow-huffcapp-perry-pear-semi-dwarf"],["Cummins Nursery: Yellow Huffcap Pear","https://www.cumminsnursery.com/buy-trees/product-detail.php?type=tree&id=29625"],["Orange Pippin: Yellow Huffcap pear","https://www.orangepippin.com/varieties/pears/yellow-huffcap"],["National Perry Pear Centre: Yellow Huffcap","https://www.nationalperrypearcentre.org.uk/pear/yellow-huffcap/"]],"basis":"sourced","note":"Raintree's text says mid-to-late September in Western Oregon but its table says October; band set to Mid. Several different perry pears carry the Huffcap name. The National Perry Pear Centre lists Yellow Huffcap as a synonym of Hendre Huffcap, while Cummins treats them as separate trees.","reviewed_on":"2026-10-17"},{"id":"pear-thorn-perry","group":"Pear","type":"Perry pear","kind":"cultivar","name":"Thorn (perry pear)","aliases":["Thorn European Perry Pear","Thorn perry"],"inventory_rows":[],"purchase_rows":[107],"tagline":"Mid; small yellow, some russet; medium-acid perry","summary":"Old Gloucestershire perry pear with small yellow, lightly russeted fruit on a small upright tree. Pressed for a perry that is medium in acid and low in tannin, rated average to good.","appearance":"Small yellow pears, faintly flushed orange and patchily russeted. The pages read do not describe fruit shape or flesh color.","flavor_use":"Grown for perry: Raintree rates the juice average to good (medium acid, low tannin), and the National Perry Pear Centre calls it good quality and also culinary and dessert. Needs a pollinizer pear.","uses":["perry","cooking"],"ripening":"Mid","ripening_note":"September per Raintree; mid to late Sept (early mid-season) at the UK National Perry Pear Centre","id_cues":"Best check against Hendre Huffcap is timing: Raintree lists Thorn for September with mid-season bloom, and Hendre Huffcap for October with an early-blooming pollinizer. Both trees are called upright, so shape is a weak cue. Thorn fruit: small, yellow, faint orange flush, some russet.","habit":"Small tree with an upright habit, about 15 ft tall on the semi-dwarf OHxF87 rootstock Raintree lists; bears abundant crops.","bark":null,"leaf":null,"hardiness":"Zones 5 to 9 (Raintree)","sources":[["Raintree Nursery: Thorn European Perry Pear","https://raintreenursery.com/products/thorn-e-perry-pear-semi-dwarf"],["National Perry Pear Centre: Thorn","https://www.nationalperrypearcentre.org.uk/pear/thorn/"],["Raintree Nursery: Hendre Huffcapp European Perry Pear","https://raintreenursery.com/products/hendre-huffcapp-e-pear-semi-dwarf"]],"basis":"sourced","note":"Pages cover fruit, perry and timing but give no leaf or bark traits. One of the 2 trees tagged Hendre Huffcap may be this Thorn, so compare harvest month and fruit.","reviewed_on":"2026-10-17"},{"id":"cherry-bing","group":"Cherry","type":"Cherry","kind":"cultivar","name":"Bing","aliases":[],"inventory_rows":[72],"purchase_rows":[53,54],"tagline":"Mid; mahogany to near-black heart; very sweet, firm","summary":"Main commercial sweet cherry of the western US, developed in Oregon in 1875. Large, firm, juicy, very sweet dark fruit, eaten mostly fresh. Needs a different sweet cherry nearby to set a crop.","appearance":"Heart-shaped fruit, large (sources range from moderate to very large); skin dark red to mahogany, almost black when fully ripe; flesh dark red, firm and crunchy. Large, vigorous tree.","flavor_use":"Sweet with a little acidity, juicy and crunchy. Mainly eaten fresh; also canned or made into preserves. Rated as susceptible to fruit cracking.","uses":["fresh","canning"],"ripening":"Mid","ripening_note":"Mid-season; WSU rates it early to mid-season and USU gives mid June in Utah.","id_cues":"Dark mahogany, heart-shaped cherries on a large, vigorous tree that sets little fruit without another sweet cherry nearby. Fruit alone is a weak cue: Stella, Lapins and Black Tartarian look similar. Ripens mid June in Utah, ahead of Stella and Lapins (USU).","habit":"Large, vigorous tree, erect at first and becoming upright-spreading and fairly open; productive. Hedrick (1915) found NY station trees less vigorous and productive than expected, perhaps due to site.","bark":"Stout, smooth trunk and limbs; limbs brownish and speckled with lots of little lenticels. Shoots stout and widely spaced between buds, greenish-brown and finely downy, bearing small raised lenticels that are easy to see.","leaf":"Many large leaves, ovate to obovate, blades folded upward; smooth and dark green on top, paler and downy beneath; shallowly toothed, glandular margin; long, thickish, downy, red-tinged leafstalk bearing 1-3 big reddish glands.","hardiness":"USDA zones 5-8 (USU); Dave Wilson lists 5-9","sources":[["Washington State Univ. Tree Fruit: Bing sweet cherry variety profile","https://treefruit.wsu.edu/variety/bing/"],["Utah State Univ. Extension: Intermountain Fruit table, cherry varieties for Utah","https://intermountainfruit.org/fruit-tables/cherry"],["Dave Wilson Nursery: Bing cherry","https://www.davewilson.com/nurseries/products/fruit-trees/cherry/bing/"],["Project Gutenberg: The Cherries of New York by U. P. Hedrick (1915)","https://www.gutenberg.org/cache/epub/46327/pg46327-images.html"]],"basis":"sourced","note":"Sources disagree on fruit size (moderate to very large). USU says it will not pollinate Lambert or Royal Ann; Dave Wilson lists Black Tartarian, Van, Rainier and Lapins as pollinizers.","reviewed_on":"2026-10-17"},{"id":"cherry-black-tartarian","group":"Cherry","type":"Cherry","kind":"cultivar","name":"Black Tartarian","aliases":[],"inventory_rows":[73],"purchase_rows":[55,56],"tagline":"Early; purple-black, medium; sweet, rich; pollinizer","summary":"Old Russian sweet cherry that is among the first to ripen in June. Medium, purplish-black fruit, sweet and rich, mostly eaten fresh. Needs a second sweet cherry and is widely used as a pollinizer for others.","appearance":"Medium to large fruit; skin deep cherry-red to purplish-black, nearly black when ripe; flesh firm, crisp and juicy. Vigorous pyramid-shaped tree, typically 12 to 30 ft tall and wide.","flavor_use":"Sweet, rich and juicy; best eaten fresh off the tree. Also canned, preserved, juiced or baked. USU rates the fruit as susceptible to cracking.","uses":["fresh","canning","juice","cooking","pollinizer"],"ripening":"Early","ripening_note":"Among the first sweet cherries in June (Stark Bro's); June in Utah (USU).","id_cues":"Purplish-black, medium-sized cherries on a vigorous pyramid-shaped tree that blooms early and ripens before most sweet cherries. Dark fruit alone is a weak cue (Bing and Stella are similar); early bloom and early ripening are the best clues.","habit":"Upright, vigorous, productive tree, 12-30 ft tall and wide; long-lived and can grow very big with age. Arbor Day lists medium growth speed and a pyramidal shape, while Hedrick (1915) calls the form vase-like.","bark":"Smooth trunk of moderate thickness. Limbs smooth and reddish-brown with a faint ash-gray wash and large lenticels. Shoots fairly long, brown but nearly covered by gray, smooth and hairless, with faint, slightly raised lenticels.","leaf":"Plentiful thin leaves about 5.5 in by 2.5 in, obovate to elliptical and folded upward; puckered and dark green on top, paler and slightly downy below; edge toothed to scalloped; thick red-tinged leafstalk about 2 in with 1-3 glands.","hardiness":"USDA zones 5-8 (USU)","sources":[["Utah State Univ. Extension: Intermountain Fruit table, cherry varieties for Utah","https://intermountainfruit.org/fruit-tables/cherry"],["Stark Bro's: Black Tartarian sweet cherry","https://www.starkbros.com/products/fruit-trees/cherry-trees/black-tartarian-sweet-cherry"],["Arbor Day Foundation: Black Tartarian cherry tree guide","https://shop.arborday.org/treeguide/210"],["Project Gutenberg: The Cherries of New York by U. P. Hedrick (1915)","https://www.gutenberg.org/cache/epub/46327/pg46327-images.html"]],"basis":"sourced","note":"Also called Ronald's Large Black Heart (Arbor Day). Sources call the fruit medium, medium to large, or large.","reviewed_on":"2026-10-17"},{"id":"cherry-craigs-crimson","group":"Cherry","type":"Cherry","kind":"cultivar","name":"Craig's Crimson","aliases":["Craigs Crimson"],"inventory_rows":[74],"purchase_rows":[57],"tagline":"Mid; dark red heart; sweet, firm; natural semi-dwarf","summary":"Sweet cherry from the Zaiger breeding program in California that stays naturally semi-dwarf. Medium to large, very firm, dark red to nearly black fruit with intense sweetness and a spicy note; eaten fresh or preserved.","appearance":"Rounded to heart-shaped fruit, medium to large; skin dark red to nearly black; flesh firm and juicy. Natural semi-dwarf tree, about two-thirds the size of a standard cherry and smaller on Colt or Mahaleb rootstock.","flavor_use":"Intense sweetness with a spicy edge, juicy and very firm. Used for fresh eating, desserts and preserves. Bird protection is advised as the fruit ripens.","uses":["fresh","cooking","canning"],"ripening":"Mid","ripening_note":"Dave Wilson: midseason, listed May 12 to June 2; Bay Laurel: mid to late May. Both are warm-climate dates.","id_cues":"Dark red to nearly black, rounded to heart-shaped, very firm cherries on a naturally small tree (about two-thirds of standard size). Other dark sweet cherries look alike, so the small tree and spicy flavor are the main clues. Partly self-fruitful, so it may set some fruit alone.","habit":"Natural semi-dwarf, about 10-14 ft tall per the plant patent, with a semi-spreading canopy of medium to high density; semi-vigorous, productive, regular bearer. Nurseries say about two-thirds of standard size; the patent says one-third to one-half.","bark":"Medium-sized trunk, medium-rough, gray-brown to brown, with a medium number of large lenticels. Branches medium-stocky and medium-rough, gray-brown to red-brown, with medium-to-large lenticels (plant patent, Modesto, CA trees).","leaf":"Medium leaves about 5.5 in long and 2 in across, ovate to obovate, medium thickness, toothed edge; upper side green shading to dark green, underside grayish shading to deep green; petiole about 1.25 in with 1-3 (usually 2) kidney-shaped glands near the top.","hardiness":"USDA zones 4-9 per all three nursery pages","sources":[["Dave Wilson Nursery: Craig's Crimson cherry","https://www.davewilson.com/nurseries/products/fruit-trees/cherry/craig_s_crimson/"],["Grow Organic: Craig's Crimson cherry tree","https://www.groworganic.com/products/cherry-craig-s-crimson-zaiger-semi-dwarf"],["Bay Laurel Nursery: Craig's Crimson cherry, semi-dwarf","https://www.baylaurelnursery.com/cherries/craig-s-crimson-cherry-semi-dwarf-detail.html"],["Google Patents: US PP7320, cherry tree named Craig's Crimson","https://patents.google.com/patent/USPP7320P/en"]],"basis":"sourced","note":"Nurseries differ on pollination: Dave Wilson and Grow Organic say partly self-fruitful and suggest Stella or Black Tartarian nearby; Bay Laurel says self-fruitful.","reviewed_on":"2026-10-17"},{"id":"cherry-hardy-giant","group":"Cherry","type":"Cherry","kind":"cultivar","name":"Hardy Giant","aliases":["Hardy Giant Antique","Hardy Giant Antque Sweet"],"inventory_rows":[75],"purchase_rows":[58],"tagline":"Mid; mahogany skin, dark red flesh; heavy clusters","summary":"Antique sweet cherry found in Cedarburg, Wisconsin in 1926 and sold by Stark Bro's since 1949. Firm, sweet fruit in big clusters, with mahogany skin and dark red flesh. Needs another sweet cherry for pollination.","appearance":"Large, firm cherries carried in heavy bunches; skin mahogany, flesh dark red. The pit is partly freestone, so it separates fairly easily from the flesh.","flavor_use":"Sweet and firm. Eaten fresh and good for canning, since the pit separates readily and the color and sweetness hold up in jars. The harvest is described as generous and falls in June.","uses":["fresh","canning"],"ripening":"Mid","ripening_note":"June per Stark Bro's. The page does not compare it with Bing, so the band is an estimate.","id_cues":"Heavy bunches of firm cherries with mahogany skin, dark red flesh and a pit that partly lets go of the flesh; needs a second sweet cherry for pollination. These traits overlap with other dark sweet cherries, so identification by fruit alone is weak.","habit":"Vigorous tree with a wide, open, semi-spreading crown and strong scaffold limbs; Stark gives about 15-18 ft tall and wide. Young shoots reportedly need bending to widen branch angles. Blooms pink and white in spring.","bark":null,"leaf":null,"hardiness":"USDA zones 5-9 (Stark Bro's)","sources":[["Stark Bro's: Starking Hardy Giant antique sweet cherry","https://www.starkbros.com/products/fruit-trees/cherry-trees/starking-hardy-giant-antique-sweet-cherry"],["DLV Agrar Trade: Stark Hardy Giant sweet cherry","https://dlv-agrar.com/en/sweet-cherry-stark-hardy-giant/"],["Excelentes Precios: Starking cherry (Stark Hardy Giant)","https://en.excelentesprecios.com/starking-cherry"]],"basis":"general","note":"Only Stark Bro's, its exclusive seller, describes it; no independent source found. The purchase sheet name 'Hardy Giant Antque Sweet' matches Stark's Starking Hardy Giant Antique Sweet Cherry.","reviewed_on":"2026-10-17"},{"id":"cherry-lapins","group":"Cherry","type":"Cherry","kind":"cultivar","name":"Lapins","aliases":["Lapins Sweet"],"inventory_rows":[76],"purchase_rows":[59],"tagline":"Late; self-fertile; large mahogany, Bing-shaped","summary":"Self-fertile sweet cherry from Summerland, British Columbia (Van x Stella). Large, firm, sweet, mahogany-colored fruit shaped like Bing but ripening later; mostly eaten fresh.","appearance":"Large, round heart-shaped fruit close to Bing in outline; skin dark red turning mahogany when ripe; flesh red to purple-red and firm.","flavor_use":"Sweet (about 17-19% sugar), firm and well flavored; best for fresh eating. Reported to resist cracking and to handle late spring frost better than most early-blooming sweet cherries.","uses":["fresh"],"ripening":"Late","ripening_note":"WSU: 10-14 days after Bing. Dave Wilson says only 4 days after Bing; Stark Bro's says July.","id_cues":"Big Bing-shaped, dark red to mahogany cherries on a tree that sets fruit alone. Blooms 2-4 days before Bing and ripens after it. Fruit looks like Bing, so self-fertility and late ripening are the clues.","habit":"Vigorous, upright tree; limbs rise at narrow angles with few side shoots, so unpruned trees go bare inside. Described as an early, heavy bearer. Height depends on rootstock (Stark: 18-25 ft standard, 15-18 ft semi-dwarf).","bark":null,"leaf":null,"hardiness":"USDA zones 5-9 (Stark Bro's, Dave Wilson)","sources":[["Washington State Univ. Tree Fruit: Lapins sweet cherry variety profile","https://treefruit.wsu.edu/variety/lapins/"],["Stark Bro's: Lapins sweet cherry","https://www.starkbros.com/products/fruit-trees/cherry-trees/lapins-sweet-cherry"],["Dave Wilson Nursery: Lapins cherry","https://www.davewilson.com/nurseries/products/fruit-trees/cherry/lapins/"],["UC Davis Foundation Plant Services: Prunus cultivar Lapins","https://fps.ucdavis.edu/treedetails.cfm?v=883"],["DLV Agrar Trade: Lapins sweet cherry","https://dlv-agrar.com/en/sweet-cherry-lapins/"]],"basis":"sourced","note":"Sometimes sold as Self-fertile Bing (Dave Wilson). Sources differ on ripening: 4 days after Bing (Dave Wilson) versus 10-14 days (WSU).","reviewed_on":"2026-10-17"},{"id":"cherry-montmorency","group":"Cherry","type":"Cherry","kind":"cultivar","name":"Montmorency","aliases":[],"inventory_rows":[77],"purchase_rows":[60],"tagline":"Late; bright red tart pie cherry; self-fertile","summary":"The standard tart (sour) pie cherry of North America. Medium-large, bright red fruit with firm yellow flesh and a rich tart flavor, used for pies and preserves. Self-fertile and cold hardy to zone 4.","appearance":"Medium-large fruit with bright red skin, firm yellow flesh and clear juice. Rounded tree, about 8 to 18 ft tall and 10 to 20 ft wide, with white spring blossoms.","flavor_use":"Tart, tangy flavor with firm flesh; made into pies, cobblers and preserves and can be dried. Stark Bro's also calls it good fresh. Blooms later than sweet cherries, so it escapes more spring frosts.","uses":["cooking","canning","drying","fresh"],"ripening":"Late","ripening_note":"About 2 weeks after sweet cherries (USU); Stark Bro's says June, Arbor Day says early in the season.","id_cues":"Bright red, tart cherries with firm yellow flesh on a rounded tree 8-18 ft tall; sets fruit alone and blooms later than sweet cherries. Bright red skin, yellow flesh and a sour taste set it apart from the dark sweet cherries here; other pie cherries can look alike.","habit":"Medium-sized, vigorous, round-topped tree, about 8-18 ft tall and 10-20 ft wide, growing at a medium pace. The crown spreads widely with many branches, lower limbs tend to droop, and fruit is carried in clusters throughout the crown.","bark":"Smooth trunk and limbs. Limbs reddish-brown with a light ash-gray tinge and scattered medium lenticels. Shoots slender, red-brown, partly overlaid with gray, smooth, and marked by tiny, hard-to-see lenticels, few in number.","leaf":"Leathery, oval to obovate leaves about 3 in by 1.5 in, flat or folded; smooth and dark green above, paler green below with scattered hairs; double-scalloped glandular edge; red-tinged leafstalk about 1 in, glands few or none.","hardiness":"Cold hardy to zone 4 (Stark Bro's)","sources":[["Arbor Day Foundation: Montmorency cherry tree guide","https://shop.arborday.org/treeguide/226"],["Stark Bro's: Stark Montmorency sour cherry","https://www.starkbros.com/products/fruit-trees/cherry-trees/stark-montmorency-sour-cherry"],["Utah State Univ. Extension: How to Preserve Cherries (Utah varieties)","https://extension.usu.edu/preserve-the-harvest/research/cherries"],["Project Gutenberg: The Cherries of New York by U. P. Hedrick (1915)","https://www.gutenberg.org/cache/epub/46327/pg46327-images.html"],["UC Davis Foundation Plant Services: Prunus cultivar Montmorency","https://fps.ucdavis.edu/treedetails.cfm?v=993"]],"basis":"sourced","note":"Timing sources differ: USU says sour cherries ripen about 2 weeks after sweet ones, Arbor Day says early season, Stark says June. USU also calls the flesh red; others say yellow.","reviewed_on":"2026-10-17"},{"id":"cherry-nanking","group":"Cherry","type":"Nanking cherry","kind":"species","name":"Nanking cherry","aliases":["Nanking, Ian","Nanking, Jules","Nanking (bush)"],"inventory_rows":[78,79],"purchase_rows":[61],"tagline":"Mid; small tart-sweet cherries; very hardy bush","summary":"Very cold-hardy bush cherry (Prunus tomentosa) with downy leaves, early pink-white bloom and tiny cherries that range from sweet to tart. Needs two or more plants; also used as an edible hedge.","appearance":"Multi-stemmed, twiggy shrub, upright to broad-spreading, usually 8-12 ft (4-8 ft for the white selections), with downy leaves. Fruit is cherry-shaped, about 1/2 inch across, with a large pit: red in ordinary seedlings, white in Ian and Jules.","flavor_use":"Sweet to tart, varying by plant. Red seedlings are tart enough for pies, wine and jelly; Ian is described as the sweetest Nanking and the white selections as best for fresh eating. The pit is large.","uses":["fresh","jelly","cooking","windbreak","ornamental","wildlife"],"ripening":"Mid","ripening_note":"Fruit ripens in June in Utah (USU).","id_cues":"Upright, multi-stemmed bush with white downy fuzz on the leaves; pink buds open white before the leaves, about when apricots bloom, then tiny cherries follow. Fruit color is the clue: red on ordinary seedlings, white on Ian and Jules.","habit":"Upright to semi-spreading, multi-stemmed, densely twiggy, thornless shrub, usually 6-12 ft tall and wide (some to 15 ft); opens up with age. Seedling plants vary in size. Blooms on bare wood in early spring, about when apricots do.","bark":"Mature bark is shiny brown and peels (exfoliates) with age. Young stems are coated in fine down, like the leaves. Buds are small (about 1/8 in), brown and alternate.","leaf":"Simple, alternate, elliptical to oval leaves, 2-3 in long and 1-1.5 in wide, wrinkled and rough-veined with uneven teeth; dark or medium green above, covered in white hairs below; fall color yellow.","hardiness":"Species zone 2 (NDSU); Ian and Jules zones 3-7","sources":[["Utah State Univ. Extension: How to Grow Nanking Cherries in Your Garden","https://extension.usu.edu/yardandgarden/research/nanking-cherry-in-the-garden"],["NDSU Extension: Nanking Cherry (F2141)","https://www.ndsu.edu/agriculture/extension/publications/nanking-cherry"],["Edible Landscaping: Ian Nanking Cherry White","https://ediblelandscaping.com/products/nanking-cherry-white-ian"],["NDSU Extension: Tree Handbook, Nanking Cherry (Prunus tomentosa)","https://www.ag.ndsu.edu/trees/handbook/th-3-11.pdf"],["NC State Extension: Prunus tomentosa (Downy Cherry, Nanking Cherry)","https://plants.ces.ncsu.edu/plants/prunus-tomentosa/"]],"basis":"sourced","note":"Ian and Jules are named white-fruited Nanking selections (Edible Landscaping), but the purchase sheet only says Nanking (bush); confirm fruit color. Pair with a different selection or a red seedling.","reviewed_on":"2026-10-17"},{"id":"cherry-royalton","group":"Cherry","type":"Cherry","kind":"cultivar","name":"Royalton","aliases":["Royalton Sweet"],"inventory_rows":[80],"purchase_rows":[63],"tagline":"Mid; very large dark purple, crack-resistant; slow to bear","summary":"Cornell-bred sweet cherry released in 1991. Very large, firm, crack-resistant dark purple fruit with a rich cherry flavor, mainly for fresh eating. The tree is upright, slow to start bearing, and needs another sweet cherry.","appearance":"Round, slightly flattened fruit about 1 1/4 in across (over 10 g), skin dark purple-red to grayish purple, flesh slightly lighter, crisp, with a large pit. Vigorous, upright, leggy pyramid tree with few side branches, 20 ft and rising on Mazzard roots.","flavor_use":"Rich, strong cherry flavor, firm and crisp, with sugars usually above 19% in Geneva, New York. Mainly fresh eating. Resists cracking and bacterial canker, but is sensitive to a disorder called blast.","uses":["fresh","pollinizer"],"ripening":"Mid","ripening_note":"June, about 60 days after mid-season bloom (Stark Bro's); bloom overlaps Bing's (patent), so about midseason.","id_cues":"Very large (about 1 1/4 in), slightly flattened round, grayish-purple cherries on a tall, upright tree with few side branches and large, dark green, coarsely toothed leaves. Slow to start bearing (about year 7 on Mazzard in New York).","habit":"Vigorous, upright, leggy tall pyramid with sparse side branching; about 20 ft and still rising on Mazzard roots, about 14 ft on Gisela 5 or Inmil. Fewer fruit-bearing spurs on wood over 3 years old; slow to bear (first bloom about 7 years after grafting on Mazzard, NY).","bark":"Shoots long and lightly branched, carrying numerous big lenticels. Autumn shoot bark is grayish-orange on the sun-exposed side and grayish-brown on the opposite side. New shoots often show grooves running back from the tip bud.","leaf":"Large, mostly symmetrical leaves with smooth, hairless blades; dark green above, yellow-green below; coarsely toothed margin with 3-4 teeth per cm; kidney-shaped glands; petiole 4-4.5 cm; stipules fall before harvest.","hardiness":"USDA zones 5-8 (Stark Bro's)","sources":[["Stark Bro's: Royalton sweet cherry (discontinued listing)","https://www.starkbros.com/products/fruit-trees/cherry-trees/royalton-sweet-cherry"],["Google Patents: US PP11107, sweet cherry cultivar named Royalton","https://patents.google.com/patent/USPP11107P/en"],["Cornell eCommons: Royalton Black Sweet Cherry, NYSAES bulletin 140","https://ecommons.cornell.edu/entities/publication/2b03c7b9-c686-496b-8c66-b18958c5bacc"]],"basis":"sourced","note":"Stark Bro's no longer lists it. Bearing age differs: the patent says first bloom about year 7 on Mazzard in New York; Stark says 4 to 7 years.","reviewed_on":"2026-10-17"},{"id":"cherry-stella","group":"Cherry","type":"Cherry","kind":"cultivar","name":"Stella","aliases":["Sweet Stella"],"inventory_rows":[82],"purchase_rows":[65],"tagline":"Mid; self-fertile; large dark heart-shaped, firm","summary":"Self-fertile sweet cherry released at Summerland, British Columbia in 1968. Large, heart-shaped, dark red to nearly black fruit, firm and sweet. A single tree sets fruit and also pollinates other sweet cherries.","appearance":"Large heart-shaped fruit; skin dark red to nearly black (Stark Bro's calls it bold red); flesh firm, sweet and dark red. Fruit closely resembles its parent Lambert.","flavor_use":"Firm, sweet and well flavored; good fresh, canned, frozen or dried. Rated crack-resistant. The tree starts bearing young.","uses":["fresh","canning","drying","pollinizer"],"ripening":"Mid","ripening_note":"After Bing: late June into July in Utah (USU); Dave Wilson calls it a late harvest; Stark Bro's says June.","id_cues":"Large, heart-shaped, dark red to nearly black cherries on a tree that sets fruit alone and bears young. Looks much like Lambert and other dark sweet cherries, so fruit is a weak cue; it ripens somewhat after Bing.","habit":"Vigorous, productive tree with an upright-spreading habit that begins fruiting while young. Size depends on rootstock: Stark lists 18-25 ft standard and 15-18 ft semi-dwarf; Fedco says it will reach 25-30 ft.","bark":null,"leaf":null,"hardiness":"USDA zones 5-8 (USU, Stark Bro's); Dave Wilson says 5-9","sources":[["Utah State Univ. Extension: Intermountain Fruit table, cherry varieties for Utah","https://intermountainfruit.org/fruit-tables/cherry"],["Stark Bro's: Stella sweet cherry","https://www.starkbros.com/products/fruit-trees/cherry-trees/stella-sweet-cherry"],["Dave Wilson Nursery: Stella cherry","https://www.davewilson.com/nurseries/products/fruit-trees/cherry/stella/"],["UC Davis Foundation Plant Services: Prunus cultivar Stella","https://fps.ucdavis.edu/treedetails.cfm?v=1445"],["Fedco Seeds: Stella sweet cherry","https://fedcoseeds.com/trees/stella-sweet-cherry-7393"]],"basis":"sourced","note":"Sources differ on skin color (bold red vs nearly black) and timing (June vs late June to July). Dave Wilson says it pollinates Bing except in mild-winter climates.","reviewed_on":"2026-10-17"},{"id":"cherry-regina","group":"Cherry","type":"Cherry","kind":"cultivar","name":"Regina","aliases":["Regina sweet cherry","RA"],"inventory_rows":[],"purchase_rows":[62],"tagline":"Late; very large, dark, very firm; crack resistant","summary":"German sweet cherry from the Jork research station that ripens late. Very large, dark, crunchy fruit with a sweet, mild flavor and strong resistance to rain cracking. Needs a different sweet cherry nearby for pollination.","appearance":"Very large heart-shaped cherries with squared shoulders; skin dark red to nearly black, flesh slightly paler than the skin, very firm and crunchy. Stark Bro's says the stone clings to the flesh (clingstone).","flavor_use":"Sweet and mild with balanced acid (WSU gives 19-22% sugar); Stark Bro's finds it sweet-tart when red and sweeter when deep purple. Fresh eating; reported to store up to five weeks. Stark says any other sweet cherry except Van will pollinate it.","uses":["fresh"],"ripening":"Late","ripening_note":"14-17 days after Bing (WSU), 10-12 days (Dave Wilson); Stark Bro's gives only late June.","id_cues":"Late: ripens about 2 weeks after Bing and blooms 7-9 days after it (WSU), so an early-blooming or early-fruiting tree is not Regina. Fruit is very large, very firm, crunchy, clingstone. Owner's notes call Black Tartarian early and soft, and Sam mid-season.","habit":"Vigorous, about 15-18 ft tall and wide (Stark Bro's); wide branch angles and strong central-leader habit make it easy to train (Dave Wilson). Productivity problems are reported; several late pollenizers and extra bees help.","bark":null,"leaf":null,"hardiness":"Zones 5-8 (Stark Bro's); Dave Wilson: very winter hardy","sources":[["Washington State Univ. Tree Fruit: Regina cherry variety profile","https://treefruit.wsu.edu/variety/regina/"],["Dave Wilson Nursery: Regina cherry (variety finder)","https://www.wheretobuy.davewilson.com/product-information-commercial/product/regina-cherry"],["Stark Bro's: Regina sweet cherry tree","https://www.starkbros.com/products/fruit-trees/cherry-trees/regina-sweet-cherry"]],"basis":"sourced","note":"Sources differ on timing (WSU 14-17 days after Bing, Dave Wilson 10-12), acidity (low-acid vs sweet-tart) and origin year (WSU 1981, Stark 1998). Stark lists Sam Sweet Cherry as a pollination partner.","reviewed_on":"2026-10-17"},{"id":"cherry-sam-sweet","group":"Cherry","type":"Cherry","kind":"cultivar","name":"Sam Sweet","aliases":["Sam","Sam cherry","SS"],"inventory_rows":[],"purchase_rows":[64],"tagline":"Early; large mahogany, firm; late bloom, hardy","summary":"Hardy sweet cherry from Summerland, British Columbia (1953), named for the station and breeder Arthur Mann; Stark Bro's sells it as Sam Sweet. Large, dark, firm fruit; blooms late; needs a second sweet cherry.","appearance":"Large, conic to heart-shaped cherries (Stark Bro's says medium to large) with dark mahogany to nearly black skin and firm flesh. The fruit hangs in fairly tight clusters.","flavor_use":"Sweet but fairly low in sugar and acid; tastes poor if picked before it is fully dark. Eaten fresh or canned (syrup as dark as Bing's but milder); Stark adds freezing. Resists rain cracking; tight clusters favor brown rot. Needs another sweet cherry as pollinizer.","uses":["fresh","canning","pollinizer"],"ripening":"Early","ripening_note":"About 1 week before Bing (UC Davis); June per Stark Bro's.","id_cues":"Blooms in the latest pollination period, same as Regina, while Black Tartarian blooms in the earliest (OSU): bloom separates it from Black Tartarian, not Regina, so compare ripening against Bing too (Sam is about a week ahead). Large, firm, mahogany fruit in tight clusters; poor flavor if picked early.","habit":"Hardy, vigorous, upright-spreading tree with a good branch framework, hardier than Bing; it ranked just behind Van in a 1955 Washington freeze. Blooms later than most sweet cherries, which can help it miss late frosts.","bark":null,"leaf":null,"hardiness":"Zones 5-9 (Stark Bro's, UC Davis)","sources":[["UC Davis Foundation Plant Services: Sam cherry","https://fps.ucdavis.edu/treedetails.cfm?v=1336"],["Stark Bro's: Sam Sweet cherry tree","https://www.starkbros.com/products/fruit-trees/cherry-trees/sam-sweet-cherry"],["Oregon State Univ. Extension: EM 9484 sweet cherry compatibility and bloom timing chart","https://extension.oregonstate.edu/catalog/em-9484-sweet-cherry-compatibility-bloom-timing-chart-commercial-growers"]],"basis":"sourced","note":"Almost certainly Sam: Stark titles its cherries '[Name] Sweet Cherry' and its text says Sam. Sheet says partly self-fertile; sources say a pollinizer is needed. OSU lists Sam and Royalton in the same group (S2S4): cross-incompatible.","reviewed_on":"2026-10-17"},{"id":"peach-blazing-star","group":"Peach","type":"Peach","kind":"cultivar","name":"Blazingstar","aliases":["Blazing Star"],"inventory_rows":[83],"purchase_rows":[77],"tagline":"Early; bright red skin; firm, non-browning freestone","summary":"Hardy yellow-fleshed freestone peach with nearly all-red skin, ripening just after Redhaven. Resists bacterial spot and peach canker; good fresh or canned.","appearance":"Skin is about 90 percent bright red over a yellow ground color. Flesh is yellow, firm and slow to brown, with a small pit that pulls away cleanly. The cited pages give no fruit size or shape.","flavor_use":"Called a good-tasting peach, but no detailed flavor notes were found. Used fresh, canned or preserved. Firm flesh keeps a few days to a week in the fridge, and fruit ripens evenly, often in two pickings.","uses":["fresh","canning"],"ripening":"Early","ripening_note":"About 4 days after Redhaven (IPM); mid August per Kraus Nurseries.","id_cues":"Nearly solid bright red skin (about 90 percent) over yellow, with yellow flesh that resists browning, ripening within a week of Redhaven. Other red-blushed freestone peaches can look similar, so these cues are weak.","habit":"Medium-large, high-vigor tree, upright and spreading with an open canopy and a central leader; main scaffolds sit at a 50-60 degree angle. Unpruned at age 7 it measured about 16 ft tall by 18 ft wide. Bears every year.","bark":"Trunk is medium-small, smooth and gray, with small lenticels.","leaf":"Lanceolate with a pointed tip and base, about 6 in long by 1.6 in wide, medium thickness, with rounded (crenate) teeth. Green above, paler below; 2-4 round glands on the upper leaf stalk and lower blade.","hardiness":"Zones 5-8 per Kraus; bud and blossom hardy per IPM","sources":[["Kraus Nurseries: Blazingstar peach","https://www.krausnurseries.com/product/blazingstar/"],["International Plant Management: Blazingstar peach","https://www.intplant.com/index.php/cultivars/peaches/blazingstar"],["Google Patents: US PP10555 'FA 12' peach (sold as Blazingstar)","https://patents.google.com/patent/USPP10555P/en"]],"basis":"sourced","note":"Some retail pages mix up Blazingstar with the white-fleshed Blushingstar; the Kraus page lists yellow flesh. Fruit size and shape were not stated on the pages used. Its plant patent (US PP10555) is titled 'FA 12'.","reviewed_on":"2026-10-17"},{"id":"peach-canadian-harmony","group":"Peach","type":"Peach","kind":"cultivar","name":"Canadian Harmony","aliases":[],"inventory_rows":[84],"purchase_rows":[78],"tagline":"Mid; large, red-blushed; non-browning freestone","summary":"Cold-hardy yellow freestone peach bred at Harrow, Ontario (1968). Large, red-blushed fruit with firm, juicy flesh that browns slowly; good fresh, canned or frozen.","appearance":"Large, round fruit with crimson blush over 80 to 85 percent of the yellow skin when fully ripe. Flesh is yellow, moderately firm and slow to brown, and the stone comes free. Utah State rates the size medium to large.","flavor_use":"Sweet, juicy flavor with a moderately firm texture. Used fresh (including fruit salads), canned, frozen or preserved because cut slices stay bright. Keeps longer on the shelf than most peaches, per Utah State.","uses":["fresh","canning"],"ripening":"Mid","ripening_note":"Mid to late August (Utah State and Stark Bro's).","id_cues":"Large peach with crimson over 80 to 85 percent of yellow skin and slow-browning yellow flesh, ripening mid to late Aug, around Contender's time. Vigorous, upright tree. Non-browning flesh is shared with other modern peaches, so it is a weak cue.","habit":"Large, very vigorous tree with an upright to upright-spreading habit; very productive and late blooming. Stark Bro's and Silver Creek Nursery also describe vigorous, upright growth.","bark":null,"leaf":"Leaf glands are globose (round), according to the cultivar register entry.","hardiness":"Zones 5-8","sources":[["Stark Bro's: Canadian Harmony Peach Tree","https://www.starkbros.com/products/fruit-trees/peach-trees/canadian-harmony-peach"],["Utah State University Extension: Varieties for Utah - Peach","https://intermountainfruit.org/fruit-tables/peach"],["Fruit and Nut Cultivars Database: Canadian Harmony peach","https://www.fruitandnutlist.org/peach/canadian-harmony"],["Silver Creek Nursery: Canadian Harmony Peach Tree (Bareroot)","https://silvercreeknursery.ca/products/canadian-harmony-peach"]],"basis":"sourced","note":"Stark says up to 85 percent blush and large fruit; Utah State says about 80 percent blush and medium to large fruit. Treat both as ranges.","reviewed_on":"2026-10-17"},{"id":"peach-contender","group":"Peach","type":"Peach","kind":"cultivar","name":"Contender","aliases":[],"inventory_rows":[85],"purchase_rows":[79],"tagline":"Mid; red-orange skin; very hardy; non-browning flesh","summary":"Very cold-hardy yellow freestone peach from North Carolina State University (late 1980s). Medium to large, sweet fruit that ripens mid to late August; buds tolerate spring frost.","appearance":"Medium to large, firm fruit with mostly red to red-orange skin over yellow flesh that resists browning; the stone comes free. The tree has pink spring blossoms.","flavor_use":"Sweet, juicy and fragrant, with firm flesh that keeps its color and shape for fresh slices, canning and freezing. Harvest runs mid to late August, about three weeks after Redhaven (Dave Wilson).","uses":["fresh","canning"],"ripening":"Mid","ripening_note":"Mid to late Aug (Utah State, Stark); about 3 weeks after Redhaven (Dave Wilson).","id_cues":"Mostly red-orange skin over yellow flesh that stays bright when cut, ripening about three weeks after Redhaven. Frost-tolerant late buds and a very hardy tree are real traits but hard to see; season is close to Canadian Harmony.","habit":"Vigorous tree, rated more vigorous than Redhaven but with a similar growth habit. Carries many flower buds that are unusually cold hardy and bloom late. Starts bearing in 2-4 years.","bark":null,"leaf":"Leaf glands are kidney-shaped (reniform), according to the cultivar register entry.","hardiness":"Zones 4-8; survives well below zero; late buds resist frost","sources":[["Stark Bro's: Contender Peach Tree","https://www.starkbros.com/products/fruit-trees/peach-trees/contender-peach"],["Utah State University Extension: Varieties for Utah - Peach","https://intermountainfruit.org/fruit-tables/peach"],["Dave Wilson Nursery: Contender Peach (variety finder)","https://www.wheretobuy.davewilson.com/product-information/product/contender-peach"],["Fruit and Nut Cultivars Database: Contender peach","https://www.fruitandnutlist.org/peach/contender"]],"basis":"sourced","note":"Introduction year differs by source (1988 at Stark Bro's, 1989 at Dave Wilson). Dave Wilson lists a Summercrest x Redhaven cross.","reviewed_on":"2026-10-17"},{"id":"peach-elberta","group":"Peach","type":"Peach","kind":"cultivar","name":"Elberta","aliases":[],"inventory_rows":[86],"purchase_rows":[80],"tagline":"Late; large golden-yellow; sweet, firm freestone","summary":"Old Georgia peach (1870) long used as a standard for canning and fresh eating. Large golden fruit with firm, sweet yellow flesh; self-fertile and ripens late.","appearance":"Large, golden-yellow fruit with a red blush. Flesh is firm, sweet and yellow, and the stone comes free. Pink blossoms open in early to mid spring.","flavor_use":"Full, sweet peach flavor with firm, juicy flesh that holds its shape when canned or baked in pies. Used fresh, canned or frozen; a September peach in Utah.","uses":["fresh","canning","cooking"],"ripening":"Late","ripening_note":"Sept in Utah; Dave Wilson: late July in central CA, up to 3-4 weeks later in colder climates.","id_cues":"Large golden-yellow peach with a red blush, ripening late (about September), well after the early red peaches. Early Elberta, a separate variety, ripens sooner and has little or no blush, so an early or unblushed 'Elberta' may be that one.","habit":"Large, vigorous, upright-spreading tree with a dense top; bears early, heavily and for many years. Hedrick (1917) judged wood and flower buds less hardy than ideal and bloom a bit early in New York.","bark":"Thick trunk; stocky smooth branches reddish-brown mixed with pale ash-gray. Twigs olive-green flushed dark red, glossy and hairless, with many conspicuous lenticels. Flower buds large, hairy, plump, blunt to conical.","leaf":"About 6.75 in long by 1.75 in wide, oval to obovate-lanceolate; dull dark olive-green and somewhat wrinkled above, grayish-green below. Fine to coarse teeth, often double, tipped with reddish-brown glands; 1-6 kidney-shaped glands on the stalk.","hardiness":"Zones 5-8","sources":[["Stark Bro's: Elberta Peach Tree","https://www.starkbros.com/products/fruit-trees/peach-trees/elberta-peach"],["Utah State University Extension: Varieties for Utah - Peach","https://intermountainfruit.org/fruit-tables/peach"],["Dave Wilson Nursery: Elberta Peach (variety finder)","https://www.wheretobuy.davewilson.com/product-information/product/elberta-peach"],["Project Gutenberg: Hedrick, The Peaches of New York (1917), Elberta","https://www.gutenberg.org/cache/epub/47263/pg47263.txt"]],"basis":"sourced","note":"Utah State lists Early Elberta as its own midseason variety, so a store-bought tree sold as Elberta could be either one.","reviewed_on":"2026-10-17"},{"id":"peach-frost","group":"Peach","type":"Peach","kind":"cultivar","name":"Frost","aliases":[],"inventory_rows":[87],"purchase_rows":[81],"tagline":"Mid; leaf curl resistant; yellow-green skin, pink bloom","summary":"Chance-seedling peach from a Washington State University station, valued for resisting peach leaf curl. Yellow-fleshed fruit with a slight red blush; self-fertile with a showy pink bloom.","appearance":"Greenish-yellow to yellow skin with only a slight red blush, and yellow flesh. Flowers are rose-pink, full and close to double. Stone is free or partly free, depending on the source. Mature height about 14 ft (Raintree, semi-dwarf).","flavor_use":"Both sources call it tasty, and trees bear heavily. Used fresh, canned and in baking. No keeping time or detailed flavor notes were found.","uses":["fresh","canning","cooking","ornamental"],"ripening":"Mid","ripening_note":"Midseason (Raintree, Dave Wilson); July in central California; no northern date found.","id_cues":"In spring the leaves should stay mostly clean while other peaches nearby get leaf curl. Flowers are rose-pink, full and close to double. Fruit is yellow-green to yellow with only a slight red blush, so it is not one of the red peaches.","habit":"Self-fertile, heavy-bearing tree that overbears unless the fruit is thinned. Nurseries give a mature height of about 10-14 ft. Flowers are rose-pink, fully petaled and nearly double.","bark":null,"leaf":"Highly resistant to peach leaf curl in WSU trials, so spring leaves stay mostly clean; young trees may show some curl but outgrow it.","hardiness":"Zone 5 (Raintree); blooms late per Dave Wilson","sources":[["Dave Wilson Nursery: Frost Peach (variety finder)","https://www.wheretobuy.davewilson.com/product-information/product/frost-peach"],["Raintree Nursery: Frost Peach","https://raintreenursery.com/products/frost-peach-tree-semi-dwarf"],["Regeneration Farm NW: Frost peach tree","https://regenerationfarmnw.com/product/peach-frost/"]],"basis":"sourced","note":"Dave Wilson says freestone, Raintree says semi-freestone. Leaf curl resistance comes from 10-year trials at WSU; none of the pages covers Idaho.","reviewed_on":"2026-10-17"},{"id":"peach-jh-hale","group":"Peach","type":"Peach","kind":"cultivar","name":"J.H. Hale","aliases":["Hale","JH Hale"],"inventory_rows":[88],"purchase_rows":[83],"tagline":"Late; extra large, red-blushed; needs another peach","summary":"Old, very large yellow freestone peach with golden skin mostly covered in red. Not self-fertile: it needs another peach or nectarine blooming at the same time (not Elberta).","appearance":"Very large, round, even-sized fruit with smooth skin that has very little fuzz, golden but heavily covered in red. Flesh is deep yellow, firm, with a fine grain and no strings, and the stone comes free.","flavor_use":"Sweet, firm flesh with good peach flavor. Chiefly a canning peach, also used fresh and frozen. The fruit handles and ships well.","uses":["fresh","canning"],"ripening":"Late","ripening_note":"Same time as Elberta (UC Davis); Utah State lists mid to late season.","id_cues":"Very large, round, red-covered golden peach with very little fuzz, ripening with Elberta in the late group. A lone tree sets little fruit, so a tree that stays barren while nearby peaches crop is a clue. The tree is less vigorous than most peaches.","habit":"Sources differ on vigor: Hedrick (1917) calls it vigorous, upright-spreading and open-topped, while UC Davis FPS says it is less vigorous than most peaches. Productive, but needs another peach or nectarine for pollination.","bark":"Trunk medium thick and smooth; branches smooth, ash-gray overlaid with dark reddish-brown. Twigs medium in thickness, long between buds, olive-green flushed red, smooth and hairless.","leaf":"About 6.75 in long by 1.75 in wide, lanceolate, thin but leathery, folded upward with a recurved tip. Dark green and smooth above (wrinkled along the midrib), olive-green below; single or double teeth; 1-5 dark brown kidney-shaped glands on the stalk.","hardiness":"Zones 5-9 (Utah State); Dave Wilson: excellent frost hardiness","sources":[["UC Davis Foundation Plant Services: J.H. Hale peach","https://fps.ucdavis.edu/treedetails.cfm?v=806"],["Utah State University Extension: Varieties for Utah - Peach","https://intermountainfruit.org/fruit-tables/peach"],["Dave Wilson Nursery: J.H. Hale Peach (variety finder)","https://www.wheretobuy.davewilson.com/product-information/product/jh-hale-peach"],["Project Gutenberg: Hedrick, The Peaches of New York (1917), J. H. Hale","https://www.gutenberg.org/cache/epub/47263/pg47263.txt"]],"basis":"sourced","note":"UC Davis says almost any other peach or nectarine with matching bloom pollinates it, but not Elberta or close relatives. Dave Wilson lists bloom as late. Prone to leaf curl and brown rot. Hale Early and Halehaven are different peaches, so the bare name Hale is ambiguous.","reviewed_on":"2026-10-17"},{"id":"peach-redhaven","group":"Peach","type":"Peach","kind":"cultivar","name":"Redhaven","aliases":[],"inventory_rows":[89],"purchase_rows":[84],"tagline":"Early; red-blushed, little fuzz; sweet yellow flesh","summary":"Michigan-bred early peach, long the yardstick for early ripening. Medium golden fruit with a red blush and sweet, smooth yellow flesh; self-fertile and a heavy bearer.","appearance":"Medium, round fruit with golden-yellow skin and a red blush; the skin has very little fuzz. Flesh is yellow, firm, creamy and smooth. Pink spring blossoms are fragrant.","flavor_use":"Sweet, firm yellow flesh that Utah State calls non-browning. Used fresh, canned and frozen; harvest centers on late July.","uses":["fresh","canning"],"ripening":"Early","ripening_note":"Late July in Utah and per Stark; early July in central California (Dave Wilson).","id_cues":"Medium, red-blushed golden peach with very little fuzz, ripening first (late July in Utah) well before Contender and Canadian Harmony (mid to late Aug). Many yellow red-blushed peaches look alike, so season is the main clue.","habit":"Vigorous, spreading tree that bears early and heavily and almost always needs fruit thinning. Stark Bro's and Utah State both call it vigorous; the cultivar register calls it spreading.","bark":null,"leaf":"Leaf glands are kidney-shaped (reniform). Stark Bro's and Utah State list it as resistant to leaf spot.","hardiness":"Zones 5-8; frost hardy per Dave Wilson","sources":[["Stark Bro's: Redhaven Peach Tree","https://www.starkbros.com/products/fruit-trees/peach-trees/redhaven-peach"],["Utah State University Extension: Varieties for Utah - Peach","https://intermountainfruit.org/fruit-tables/peach"],["Dave Wilson Nursery: Redhaven Peach (variety finder)","https://www.wheretobuy.davewilson.com/product-information/product/redhaven-peach"],["Fruit and Nut Cultivars Database: Redhaven peach","https://www.fruitandnutlist.org/peach/redhaven"]],"basis":"sourced","note":"Stark and Dave Wilson say freestone; Utah State says semi-freestone. Stark gives its origin as South Haven, Michigan (1930), released 1940.","reviewed_on":"2026-10-17"},{"id":"peach-reliance","group":"Peach","type":"Peach","kind":"cultivar","name":"Reliance","aliases":[],"inventory_rows":[90],"purchase_rows":[85,86,87],"tagline":"Early; very hardy, late bloom; soft, sweet, juicy","summary":"Very cold-hardy yellow freestone peach bred in New Hampshire in 1964. Medium golden fruit that is sweet, soft and very juicy, used fresh and for canning; self-fertile.","appearance":"Medium, well-filled fruit with golden skin and a red cheek, yellow flesh and a free stone. Showy flowers open late. The flesh is soft and bruises easily.","flavor_use":"Sweet and very juicy but soft, so it bruises and does not ship well. Used for canning, cooking and fresh eating. Gurney's says newer hardy peaches such as Contender taste better.","uses":["fresh","canning","cooking"],"ripening":"Early","ripening_note":"Mid-late July (Gurney's); mid Aug in SE Wisconsin (Johnson's); 2-3 weeks before Elberta (Dave Wilson).","id_cues":"Medium golden peach with a red blush and soft, easily bruised flesh, on a late-blooming tree that ripens well ahead of Elberta. Fruiting after a hard winter is the best hint, but the fruit looks like many other yellow peaches.","habit":"Productive because its fruit buds are very hardy; blooms late with showy flowers. Mature height is listed around 12-20 ft depending on rootstock, and sources differ on vigor (medium at Gurney's, vigorous at Holdridge Garden).","bark":null,"leaf":"Leaf glands are globose (round), according to the cultivar register entry.","hardiness":"Zones 4-8; very cold and frost hardy, blooms late","sources":[["Gurney's: Reliance Peach Tree","https://www.gurneys.com/products/reliance_peach_tree"],["Johnson's Nursery: Reliance Peach plant profile","https://kb.jniplants.com/reliance-peach-prunus-persica"],["Dave Wilson Nursery: Reliance Peach (variety finder)","https://www.wheretobuy.davewilson.com/product-information/product/reliance-peach"],["Fruit and Nut Cultivars Database: Reliance peach","https://www.fruitandnutlist.org/peach/reliance"],["Holdridge Garden: Reliance Peach Tree","https://www.holdridgegarden.com/product/reliance-peach-tree-prunus-persica-reliance/"]],"basis":"sourced","note":"Ripening date varies a lot by region (July at Gurney's, mid August in Wisconsin), so track your own first harvest. Johnson's credits Dr. Elwyn Meader of New Hampshire.","reviewed_on":"2026-10-17"},{"id":"peach-veteran","group":"Peach","type":"Peach","kind":"cultivar","name":"Veteran","aliases":["Veteran peach","VT"],"inventory_rows":[],"purchase_rows":[88],"tagline":"Mid; yellow-orange, red-splashed; hardy, late bloom","summary":"Hardy yellow freestone peach from Vineland Station, Ontario (1928), a Vaughn x Early Elberta cross. Medium to large, soft, richly flavored fruit on a vigorous, self-fertile tree that blooms late.","appearance":"Medium to large, round-oblate (flattened round) fruit with yellow to yellow-orange skin splashed or blushed red. Flesh is yellow, soft and melting, a little coarse, and the stone comes free when fully ripe.","flavor_use":"Richly flavored, good quality when fully ripe; the flesh peels easily and suits fresh eating, canning, drying and freezing. Self-fertile; needs 900 to 1000 chill hours. Raintree says Pacific Northwest growers spray for peach leaf curl.","uses":["fresh","canning","drying"],"ripening":"Mid","ripening_note":"About 1 week before Elberta (UC Davis), which Maine lists as late Sept; Raintree calls it mid-season.","id_cues":"Maine's table: Reliance mid Aug (small fruit), Contender mid Sept (medium), Elberta late Sept (large). Veteran runs a week ahead of Elberta (UC Davis), likely between Contender and Elberta. Size only rules out small Reliance; look for soft flesh, red-splashed yellow-orange skin, small pale pink late blossoms.","habit":"Vigorous, highly productive, about 14 ft tall (Raintree). Hardy through winter and late to bloom, so it is among the more dependable peaches for cold climates; blossoms are small and not showy (UC Davis).","bark":null,"leaf":"Leaf glands are kidney-shaped (reniform); no other leaf details found.","hardiness":"Zones 5-9 (Raintree, its hardiest peach); UC Davis: winter hardy","sources":[["UC Davis Foundation Plant Services: Veteran peach","https://fps.ucdavis.edu/treedetails.cfm?v=3423"],["Raintree Nursery: Veteran peach","https://raintreenursery.com/products/veteran-peach-semi-dwarf"],["Univ. of Maine Extension (Highmoor Farm): peach varieties table","https://extension.umaine.edu/highmoor/wp-content/uploads/sites/48/2025/07/PeachVarieties.pdf"]],"basis":"sourced","note":"UC Davis says 900 chill hours, Raintree 900-1000. Maine's table does not list Veteran; it is used only for the comparison peaches. Nothing in the listed pages mentions J.H. Hale, so the owner's note about it is not repeated.","reviewed_on":"2026-10-17"},{"id":"apricot-chinese-mormon","group":"Apricot","type":"Apricot","kind":"cultivar","name":"Chinese (Mormon)","aliases":["Mormon","Chinese Mormon"],"inventory_rows":[67],"purchase_rows":[46],"tagline":"Early; late bloom; yellow-orange; sweet edible pit kernel","summary":"Hardy apricot that blooms late and ripens early, suited to cold or high-elevation sites. Medium to large yellow-orange fruit with good flavor; the pit holds an edible sweet kernel.","appearance":"Medium to large fruit with yellow to medium-orange skin and soft yellow to pale orange flesh, usually freestone. The stone can be dried and cracked to reach a sweet kernel that is edible.","flavor_use":"Good flavor and texture; Stark rates the quality very high. Eaten fresh, canned, dried or baked, and trees crop heavily. No keeping time given.","uses":["fresh","canning","drying","cooking","pollinizer"],"ripening":"Early","ripening_note":"Late June to July (Utah State); early July (Stark), among the earliest apricots.","id_cues":"Blooms late yet ripens early (late June to early July). Skin and flesh are yellow to medium orange, and the pit holds a sweet edible kernel. Fruit color alone is shared with many apricots, so bloom and ripening timing matter most.","habit":"Rounded tree that bears early and heavily and blooms late. Nursery sizes disagree: about 15-20 ft tall and wide at one, around 30 ft at another.","bark":null,"leaf":null,"hardiness":"Zones 4-7 (Utah State)","sources":[["Utah State University Extension: Varieties for Utah - Apricot","https://intermountainfruit.org/fruit-tables/apricot"],["Stark Bro's: Chinese Apricot Tree","https://www.starkbros.com/products/fruit-trees/apricot-trees/chinese-mormon-apricot"],["Glover Nursery: Apricot, Chinese (Mormon)","https://glovercatalog.com/product/chinese-mormon-apricot"],["Mill Creek Gardens: Chinese Apricot plant page","https://plants.millcreekgardens.com/12190009/Plant/14183/Chinese_Apricot/"]],"basis":"sourced","note":"Stark's Chinese Apricot page (URL says chinese-mormon) and Utah State's Chinese (Mormon) entry read as the same cultivar, so they are combined here.","reviewed_on":"2026-10-17"},{"id":"apricot-giant-tilton","group":"Apricot","type":"Apricot","kind":"cultivar","name":"Giant Tilton","aliases":["Tilton"],"inventory_rows":[68],"purchase_rows":[47],"tagline":"Mid; large golden-orange; fresh, canning, drying","summary":"Large golden-orange freestone apricot, self-fertile. Stark Bro's lists it next to plain Tilton, an old California apricot long prized for canning and drying.","appearance":"Large, rounded fruit about 2 3/4 inches across with fairly tough, thick skin and yellow-orange freestone flesh. Plain Tilton is described as golden-yellow with a red blush, medium to large.","flavor_use":"Firm golden flesh with a rich, distinctive flavor. Good fresh, in desserts, canned, frozen or dried; Tilton is long considered a top apricot for canning and drying.","uses":["fresh","cooking","canning","drying"],"ripening":"Mid","ripening_note":"July for Tilton (Utah State); mid to late summer (Stark Bro's).","id_cues":"Large, rounded, thick-skinned golden-orange apricot with yellow-orange flesh that frees from the stone, ripening in July. Plain Tilton shows a red blush. Hard to separate from other orange apricots by sight; use the purchase record and ripening date.","habit":"Described as a vigorous, robust, hardy tree with ample yields. Tilton (an alias) is also called a vigorous tree that bears a large crop, very hardy and resistant to late frost (Utah State).","bark":null,"leaf":null,"hardiness":"Zones 5-9 (Utah State, Tilton); resists late frost","sources":[["Stark Bro's: Giant Tilton Apricot Tree","https://www.starkbros.com/products/fruit-trees/apricot-trees/giant-tilton-apricot"],["Stark Bro's: Tilton Apricot Tree","https://www.starkbros.com/products/fruit-trees/apricot-trees/tilton-apricot"],["Utah State University Extension: Varieties for Utah - Apricot","https://intermountainfruit.org/fruit-tables/apricot"]],"basis":"sourced","note":"Stark sells Giant Tilton and Tilton as separate items with similar traits; Giant Tilton may be a large-fruited selection or a renamed Tilton. This profile blends both.","reviewed_on":"2026-10-17"},{"id":"apricot-harcot","group":"Apricot","type":"Apricot","kind":"cultivar","name":"Harcot","aliases":[],"inventory_rows":[69],"purchase_rows":[48],"tagline":"Mid; orange, red blush; late bloom, canker resistant","summary":"Canadian-bred apricot with medium to large orange fruit blushed red, sweet and rich in flavor. Blooms late, resists brown rot and perennial canker, and is self-fertile.","appearance":"Medium to large orange fruit with a red blush and firm, freestone flesh. Leaves are shiny dark green and the spring flowers are white to pale pink.","flavor_use":"Rich, sweet flavor with plenty of juice. Used fresh, canned and baked into desserts. No drying or keeping information was found.","uses":["fresh","cooking","canning"],"ripening":"Mid","ripening_note":"Mid July in Utah; June to July per Stark; early to mid June in central California.","id_cues":"Orange fruit with a red blush that ripens around mid July, on a late-blooming tree with shiny dark green leaves. It resembles many orange apricots, so no single trait is unique; bloom timing helps.","habit":"Large, vigorous tree, upright to spreading, cold hardy and late blooming; flowers are white to pale pink.","bark":null,"leaf":"Stark Bro's describes the leaves as shiny and dark green.","hardiness":"Zones 5-7 (Utah State); Dave Wilson lists 4-9","sources":[["Utah State University Extension: Varieties for Utah - Apricot","https://intermountainfruit.org/fruit-tables/apricot"],["Stark Bro's: Harcot Apricot Tree","https://www.starkbros.com/products/fruit-trees/apricot-trees/harcot-apricot"],["Dave Wilson Nursery: Harcot Apricot (variety finder)","https://www.wheretobuy.davewilson.com/product-information/product/harcot-apricot"],["Fruit and Nut Cultivars Database: Harcot apricot","https://www.fruitandnutlist.org/apricot-and-pubescent-skinned-prunophora-hybrids/harcot"]],"basis":"sourced","note":"Sources disagree on hardiness zones (5-7 versus 4-9) and on timing (June to mid July). Only a Canadian origin is documented.","reviewed_on":"2026-10-17"},{"id":"apricot-moorpark","group":"Apricot","type":"Apricot","kind":"cultivar","name":"Moorpark","aliases":["Moore Park"],"inventory_rows":[70],"purchase_rows":[49],"tagline":"Mid; large orange, red-specked; rich flavor; fresh, dried","summary":"Old apricot named for an English estate, with large, juicy, richly flavored freestone fruit. Self-fertile; used fresh, dried, canned and in pies.","appearance":"Large, oval, freestone fruit with smooth, fuzz-free skin in yellow-orange, with an orange-red cheek blush and scattered brownish-red dots. Flesh is yellow and juicy.","flavor_use":"Rich, fragrant, sweet flavor with a plum-like note and juicy flesh. Used fresh, in preserves and pies, and for drying; canning is also listed.","uses":["fresh","cooking","canning","drying","pollinizer"],"ripening":"Mid","ripening_note":"Mid July in Utah (Utah State); about 2 weeks after Blenheim (UC Davis).","id_cues":"Large oval apricot, yellow-orange with an orange-red blush and brownish-red specks. A medium-sized, very firm fruit may be Patterson instead (Dave Wilson's description of it). Moorpark ripens about 2 weeks after Blenheim.","habit":"Large tree: UC Davis FPS gives about 20 ft tall and 20-25 ft wide. Hedrick (1922) describes very large trees with long, strong shoots that are somewhat cold-tender and can be shy or uneven croppers.","bark":null,"leaf":null,"hardiness":"Zones 5-9 per Utah State; UC Davis lists zone 7","sources":[["UC Davis Foundation Plant Services: Moorpark apricot","https://fps.ucdavis.edu/treedetails.cfm?v=997&hidepics=yes"],["Utah State University Extension: Varieties for Utah - Apricot","https://intermountainfruit.org/fruit-tables/apricot"],["Dave Wilson Nursery: Patterson Apricot (variety finder)","https://www.wheretobuy.davewilson.com/product-information/product/patterson-apricot"],["Internet Archive: Hedrick, Cyclopedia of Hardy Fruits (1922), Moorpark","https://archive.org/stream/cyclopediaofhard00hedr/cyclopediaofhard00hedr_djvu.txt"]],"basis":"sourced","note":"Inventory has 2 trees but only 1 Moorpark was bought; the other may be Patterson. Compare fruit size, firmness and speckling once both fruit.","reviewed_on":"2026-10-17"},{"id":"apricot-patterson","group":"Apricot","type":"Apricot","kind":"cultivar","name":"Patterson","aliases":["Patterson apricot","PN"],"inventory_rows":[],"purchase_rows":[50],"tagline":"Early; firm, red-streaked yellow; self-fertile; canning","summary":"California canning apricot (Le Grand, 1968) with firm, bright orange, freestone fruit and a mild flavor; self-fertile and a heavy bearer. Dave Wilson rates it zones 6-9, so zones 4-5 are a gamble.","appearance":"Fairly round freestone fruit, called large by UC Davis but medium-sized by Dave Wilson. Yellow skin streaked with red; flesh is bright orange and very firm.","flavor_use":"Mild flavor rated fair to good, with little juice. Used for canning, freezing, drying and fresh eating; UC Davis rates its canning qualities very high. Self-fertile, so one tree fruits alone. Needs about 600 chill hours.","uses":["fresh","canning","drying"],"ripening":"Early","ripening_note":"About 1 week after Blenheim and 1 week before Moorpark (UC Davis); June 20-30 in California (Dave Wilson).","id_cues":"Vs Moorpark: Patterson ripens about a week earlier, is firm with little juice, and has yellow skin streaked with red. Moorpark is juicy and rich, with an orange-red blush and brownish-red speckles. UC Davis calls both large, so size is a weak cue.","habit":"Heavy, consistent bearer that holds its fruit even under a big crop; self-fertile. The sources used give no mature size or shape.","bark":null,"leaf":null,"hardiness":"Zones 6-9 (Dave Wilson Nursery)","sources":[["UC Davis Foundation Plant Services: Patterson apricot","https://fps.ucdavis.edu/treedetails.cfm?v=1144"],["UC Davis Foundation Plant Services: Moorpark apricot","https://fps.ucdavis.edu/treedetails.cfm?v=997"],["Dave Wilson Nursery: Patterson apricot","https://www.davewilson.com/nurseries/products/fruit-trees/apricot/patterson/"]],"basis":"sourced","note":"Dave Wilson rates it zones 6-9, not the 4-9 on the purchase sheet; none of the listed pages give frost or winter data for zones 4-5. It ripens before Moorpark, so season length matters less than cold.","reviewed_on":"2026-10-17"},{"id":"plum-italian","group":"Plum","type":"Plum","kind":"cultivar","name":"Italian plum","aliases":["Italian Lovell","Italian Seedling","Italian prune plum"],"inventory_rows":[111],"purchase_rows":[109,110],"tagline":"Mid; dark blue prune plum; sweet, freestone, dries well","summary":"European prune-type plum (Prunus domestica), also called Italian Prune or Fellenberg. Dark blue-purple, sweet freestone fruit used fresh, baked, canned or dried; self-fertile.","appearance":"Small to medium plum, oval to oblong with slightly tapered ends, smooth dark purple skin and a blue-white bloom. Flesh is semi-firm and golden-yellow to green-yellow; the pit separates easily. Utah State lists the fruit as large.","flavor_use":"Sweet with a light lemony tang and dense, low-juice flesh that holds its shape when baked. Eaten fresh, baked in cakes and tarts, canned, made into jam or dried as prunes.","uses":["fresh","cooking","canning","drying"],"ripening":"Mid","ripening_note":"Mid to late August (Utah State); August or September (Stark Bro's).","id_cues":"Oval to oblong dark blue-purple plums with a blue-white bloom and golden-yellow flesh that frees from the pit, ripening mid August to September; flowers are pinkish-white in spring. Shape and season are weak cues, as many dark prune plums look alike.","habit":"Medium to large, rather vigorous, hardy tree, spreading or upright with a low top; usually productive, though it can be fussy about soil and suffers in dry or hot weather. Often kept small, about 10-13 ft.","bark":"Branches ash-gray and smooth with small raised lenticels. Twigs short, greenish-red turning brownish-drab, hairy, with small lenticels. Leaf buds medium, conical and pressed to the twig; leaf scars large.","leaf":"Folded upward, obovate to oval, about 4.5 in long by 2 in wide; dark green and hairy above, silvery-green and heavily hairy below. Edges doubly scalloped with small dark glands; stalk red-tinged and hairy with 1-3 round glands.","hardiness":"Zones 4-9","sources":[["Stark Bro's: Italian Plum Tree","https://www.starkbros.com/products/fruit-trees/plum-trees/italian-plum"],["Utah State University Extension: Varieties for Utah - Plum","https://intermountainfruit.org/fruit-tables/plum"],["Specialty Produce: Italian Prune Plums","https://specialtyproduce.com/produce/Italian_Prune_Plums_7483.php"],["Project Gutenberg: Hedrick, The Plums of New York (1911), Italian Prune","https://www.gutenberg.org/cache/epub/72770/pg72770.txt"]],"basis":"sourced","note":"Italian Plum, Italian Prune and Fellenberg are one variety (Stark). 'Italian Seedling' may be grown from seed and vary in fruit; 'Lovell' is normally a peach rootstock name, so the tag may refer to rootstock.","reviewed_on":"2026-10-17"},{"id":"blackberry","group":"Berry","type":"Blackberry","kind":"species","name":"Blackberry","aliases":["various"],"inventory_rows":[2],"purchase_rows":[],"tagline":"Late; black berries; erect types hardiest","summary":"Bramble fruit on two-year canes: leafy the first year, fruiting the second, then dying. Berries ripen from red to black, taste tart to sweet, and are eaten fresh or made into jam, jelly, juice and baked goods.","appearance":"Each berry is a tight cluster of tiny one-seeded drupelets that colors from red to black, and the core stays inside when picked. Canes may be thorny or thornless; erect canes stand upright, while semi-erect and trailing canes need a trellis.","flavor_use":"Flavor ranges from tart to sweet by type. Eat fresh, or cook into jam, jelly, syrup, pastries or juice. Ripe berries are soft, bruise easily and keep only about 3 to 4 days chilled, so freeze extras spread on a tray first.","uses":["fresh","cooking","jelly","juice"],"ripening":"Late","ripening_note":"Idaho bulletin: recommended cultivars ripen from mid-summer into fall, most from late summer on","id_cues":"Picked fruit keeps its core, while a black raspberry is hollow because its core stays on the plant. Canes fruit in their second year, then die. Upright canes suggest an erect type, sprawling canes a trailing type. Fruit alone does not show cultivar.","habit":"Perennial crown sending up biennial canes: first-year primocanes, then fruiting floricanes that die after cropping. Types are erect (upright, self-supporting, hardiest), semi-erect (some support) or trailing (trellis, least hardy). Cultivars may be thorny or thornless.","bark":"Wild Allegheny blackberry canes are thick, sharply ridged and dull reddish-brown, armed with big hooked prickles, and darken with age. Cultivated blackberries range from thorny to thornless, so prickles depend on the cultivar.","leaf":"Alternate compound leaves. Allegheny blackberry has 3 to 7 toothed leaflets (mostly 5), prickles on the leaf stalk, and leaves green above and noticeably lighter beneath. Primocane leaves tend to carry five leaflets, floricane leaves three.","hardiness":"Recommended erect types -10 to -25F; trailing types hurt at 0 to 5F (Idaho)","sources":[["Univ. of Idaho Extension: Growing Raspberries and Blackberries in the Inland Northwest","https://content-hub.uidaho.edu/api/public/content/96e1d3fad86d41718ac4d93713f1c66a?v=0e8a669f"],["Iowa State Univ. Extension: Growing Blackberries in the Home Garden","https://yardandgarden.extension.iastate.edu/how-to/growing-blackberries-home-garden"],["NC State Extension: Blackberries for the Home Garden","https://content.ces.ncsu.edu/blackberries-for-the-home-garden"],["Virginia Tech Dendrology: Alleghany blackberry (Rubus allegheniensis)","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=139"],["Clemson Cooperative Extension: Blackberry (Home and Garden Information Center)","https://hgic.clemson.edu/factsheet/blackberry/"]],"basis":"sourced","note":"Cultivars and cane types on hand are unrecorded ('various'). The Idaho bulletin calls trailing types risky for the Inland Northwest and Intermountain West; erect types are hardier. Sources differ on whether erect canes need support.","reviewed_on":"2026-10-17"},{"id":"currant","group":"Berry","type":"Currant","kind":"species","name":"Currant","aliases":["Red Berry"],"inventory_rows":[3],"purchase_rows":[],"tagline":"Early; red, white or black; tart, jam and jelly","summary":"Shrub bearing hanging clusters of tart berries in red, white or black. Mostly cooked into jelly, jam, pies and preserves rather than eaten fresh, and the plants are very winter hardy.","appearance":"Upright shrub 3 to 6 feet tall. Red types carry long clusters of large bright red berries, white types are pale with a pink blush, and black types are soft and black. The berries are picked by the cluster.","flavor_use":"Tart, so seldom eaten fresh; 'White Imperial' is a low-acid white. Red and white currants make good jam and jelly, while black 'Consort' is sweet and musky. Pick slightly underripe for jelly (more pectin). Keeps about 2 weeks chilled.","uses":["jelly","cooking","ornamental"],"ripening":"Early","ripening_note":"Late June or July in Pennsylvania; each planting ripens over 2 to 3 weeks","id_cues":"Berries hang in strings and are picked by the cluster. Fruit color separates the kinds: bright red, pale white with a pink blush, or black with a musky taste. Currants and gooseberries are both 3 to 6 foot shrubs, so rely on the fruit or tags.","habit":"Deciduous shrub about 3 to 6 ft tall with several stems from the base; red currant is unarmed. Upright in some varieties, spreading in others. Red types fruit mainly on spurs of 2- and 3-year wood and black types on 1-year wood, so old canes are thinned out.","bark":"Bark of adult red currant is thin and smooth; winter twigs are brown to gray, and buds are covered by several overlapping scales.","leaf":"Simple, alternate, roundish leaves with 3 or 5 lobes and coarse teeth, 2 to 4 in across, heart-shaped to flat at the base; downy beneath, nearly hairless above, and fragrant.","hardiness":"Tolerates -22 to -31F (Penn State)","sources":[["Penn State Extension: Home Fruit Plantings: Gooseberries and Currants","https://extension.psu.edu/home-fruit-plantings-gooseberries-and-currants"],["Iowa State Univ. Extension: Growing Currants and Gooseberries in the Home Garden","https://yardandgarden.extension.iastate.edu/how-to/growing-currants-and-gooseberries-home-garden"],["Penn State Extension: Home Fruit Plantings: Gooseberry and Currant Variety Selection","https://extension.psu.edu/home-fruit-plantings-gooseberry-and-currant-variety-selection"],["Native Plant Trust Go Botany: Ribes rubrum (garden red currant)","https://gobotany.nativeplanttrust.org/species/ribes/rubrum/"],["Trees and Shrubs Online: Ribes rubrum","https://www.treesandshrubsonline.org/articles/ribes/ribes-rubrum/"]],"basis":"sourced","note":"Inventory lists 7 'Red Berry' currants but the purchase sheet shows 5 (1 red, 3 black, 1 white), so colors on hand are unconfirmed. Some areas ban black currants (white pine blister rust).","reviewed_on":"2026-10-17"},{"id":"elderberry","group":"Berry","type":"Elderberry","kind":"species","name":"Elderberry (American)","aliases":["Sambucus canadensis"],"inventory_rows":[4],"purchase_rows":[115],"seed_rows":[29],"tagline":"Late; dark purple clusters; cook before eating","summary":"Large suckering shrub with flat white flower heads in early summer and drooping clusters of dark purple berries in late summer. The berries must be cooked and go into jelly, syrup, juice and wine.","appearance":"Multi-stemmed shrub 5 to 12 feet tall that spreads by suckers into thickets. Leaves are divided into 5 to 10 toothed leaflets, flowers are creamy flat-topped heads, and the berries are rounded, dark purple-black and hang in heavy clusters.","flavor_use":"Tart, earthy flavor. Raw berries, stems, leaves and seeds can cause nausea, vomiting and, in large amounts, serious poisoning, so cook the fruit first for jelly, jam, syrup, juice or wine. Birds take much of the crop, so netting helps.","uses":["cooking","juice","jelly","wildlife"],"ripening":"Late","ripening_note":"August to September (Penn State); named cultivars differ by 1 to 2 weeks (Missouri)","id_cues":"Opposite compound leaves with 5 to 10 sharply toothed leaflets, hollow stems with wart-like pores, flat creamy flower heads in June-July, then drooping dark purple fruit in Aug-Sept. Suckers form thickets and the leaves turn red in fall.","habit":"Deciduous multi-stemmed shrub or small tree, usually 5 to 12 ft tall, with spreading or arching stems and a short trunk. Root suckers build thickets, and fresh shoots come up every year at the base and from the roots.","bark":"Twigs are thick and pale silvery-gray to yellow-gray, with big white pith centers and raised, wart-like pores. Bark is brown and smooth at first, then roughens and develops shallow grooves. Buds are tiny, red-brown and pointed; no terminal bud.","leaf":"Opposite compound leaves 6 to 11 in long with about 5 to 11 pointed, sharply toothed leaflets; the lowest leaflets are often three-lobed. Deep green on top, lighter beneath; foliage turns red in fall.","hardiness":"Zones 4 to 9 (Penn State)","sources":[["Penn State Extension: Rain Garden Plants: Elderberry","https://extension.psu.edu/rain-garden-plants-elderberry"],["Univ. of Missouri Center for Agroforestry: Growing and Marketing Elderberries in Missouri","https://cropsandsoils.extension.wisc.edu/files/2023/07/Growing-and-Marketing-Elderberries-in-Missouri.pdf"],["UMN Extension: Elderberries the safe way","https://extension.umn.edu/about/our-stories/news/cottage-food-connection/elderberries-the-safe-way"],["Virginia Tech Dendrology: American elderberry fact sheet","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=85"]],"basis":"sourced","note":"The 19 in the hedge are not identified by cultivar and may mix unnamed Sambucus canadensis stock with named types (Bob Gordon, Wyldewood, York and others). Seedlings vary in yield and fruit quality.","reviewed_on":"2026-10-17"},{"id":"gooseberry","group":"Berry","type":"Gooseberry","kind":"species","name":"Gooseberry","aliases":[],"inventory_rows":[5],"purchase_rows":[],"tagline":"Early; spiny bush; green to pink tart berries","summary":"Spiny shrub 3 to 6 feet tall with tart berries. Firm green fruit is picked for pie and jam, while berries left to turn pink get sweeter and can be eaten fresh.","appearance":"Shrub 3 to 6 feet tall. Fruit color differs by cultivar: Captivator is big and pink-red on a plant with few thorns, Invicta is large and pale green on a very spiny plant, Pixwell is medium and rosy pink when ripe, Hinnonmaki Red is red.","flavor_use":"Skins are tart and the flesh sweetens as berries color. Captivator and Hinnonmaki Red are the sweeter, aromatic types, Invicta is milder, and Pixwell is fair and picked a little underripe. Used for pie, jam and jelly; keeps about 2 weeks chilled.","uses":["cooking","jelly","fresh"],"ripening":"Early","ripening_note":"Late June or July in Pennsylvania; pick berries as they color","id_cues":"Spiny shrub; thorn load and fruit separate the purchased cultivars: Captivator has few thorns and pink-red fruit, Invicta is very spiny with large pale-green fruit, Pixwell ripens rosy pink, Hinnonmaki Red bears red fruit. Cultivars on hand are not recorded.","habit":"Arching, spreading, rounded deciduous shrub roughly 4 to 6 ft tall and wide. Thorn load depends on the cultivar, from few (Captivator, Poorman) to many (Invicta). Fruit forms at the base of 1-year wood and on spurs of 2- and 3-year wood.","bark":"Stems carry sporadic single spines at the nodes (none to about 2 each) and prickles on some stems. Winter buds are alternate and egg-shaped, and the crescent-shaped leaf scars each show three bundle scars.","leaf":"Alternate, simple leaves, round to egg-shaped, about 2 to 3 in long and wide, with 3 to 5 lobes, toothed edges and a flat-cut base. Soft, glossy and hairy; fall color is green-yellow.","hardiness":"Tolerates -22 to -31F (Penn State)","sources":[["Penn State Extension: Gooseberry and Currant Variety Selection","https://extension.psu.edu/home-fruit-plantings-gooseberry-and-currant-variety-selection"],["Iowa State Univ. Extension: Growing Currants and Gooseberries in the Home Garden","https://yardandgarden.extension.iastate.edu/how-to/growing-currants-and-gooseberries-home-garden"],["Penn State Extension: Home Fruit Plantings: Gooseberries and Currants","https://extension.psu.edu/home-fruit-plantings-gooseberries-and-currants"],["Kwantlen Polytechnic Univ. Plant Database: Ribes uva-crispa (gooseberry)","https://plantdatabase.kpu.ca/Plant/riuv"]],"basis":"sourced","note":"Bought: Captivator, Hinnonmaki Red x2, Invicta, Pixwell. Only 3 are on hand and which ones is unrecorded, so this is a species-level profile.","reviewed_on":"2026-10-17"},{"id":"hardy-kiwi","group":"Berry","type":"Hardy kiwi","kind":"species","name":"Hardy kiwi","aliases":[],"inventory_rows":[6],"purchase_rows":[],"tagline":"Late; grape-size smooth kiwi; needs male and female","summary":"Very hardy twining vine whose grape-sized, smooth-skinned fruit is eaten whole, like a smaller and sweeter kiwi. Plants are mostly male or female, so fruit needs both sexes.","appearance":"Vigorous woody vine with sharply toothed leaves 3 to 5 inches long and greenish-white flowers in June. Fruit is about the size of a large grape, smooth, green and sometimes blushed purple-red in sun. It needs a sturdy trellis.","flavor_use":"Sweet and aromatic, with hints of kiwi, banana, strawberry, mint or pear depending on variety; no peeling needed. Fruit can be picked underripe and finished in storage; refrigerated, it keeps up to about 2 months.","uses":["fresh","ornamental"],"ripening":"Late","ripening_note":"From mid-September in Oregon's Willamette Valley ('Ananasnaya'); Geneva ripens earlier","id_cues":"Twining vine with toothed leaves 3 to 5 inches long. Only female vines fruit, and sex shows at bloom: male flowers have pollen only, female flowers a branched central pistil. Male Arctic kiwi (kolomikta) is grown for pink-variegated leaves.","habit":"Vigorous, twining woody vine that can add about 30 ft in one year and reach 100 ft in the wild, so it needs a sturdy trellis or pergola. Flowers form on new shoots from 1-year canes, and heavy winter pruning is routine.","bark":"Young twigs twine and are hairy, with white to brown pith; buds sit hidden in a thickened zone just over each leaf scar, and the terminal bud is missing. Mature bark is gray and flaky.","leaf":"Alternate, simple, ovate leaves about 3 to 5 in long with sharply toothed edges and rounded to slightly heart-shaped bases; soft and flexible, on red leaf stalks.","hardiness":"Zones 4 or 5 to 9; dormant vines to -30F, new shoots frost-tender","sources":[["Penn State Extension: Hardy Kiwi in the Home Fruit Planting","https://extension.psu.edu/hardy-kiwi-in-the-home-fruit-planting"],["Oregon State Univ. Extension: Growing kiwifruit in your home garden (EM 9322)","https://extension.oregonstate.edu/catalog/em-9322-growing-kiwifruit-your-home-garden"],["NC State Extension: Actinidia arguta (hardy kiwi vine) plant toolbox","https://plants.ces.ncsu.edu/plants/actinidia-arguta/common-name/hardy-kiwi-vine/"],["Kwantlen Polytechnic Univ. Plant Database: Actinidia arguta (hardy kiwi)","https://plantdatabase.kpu.ca/Plant/acag"],["Mass Audubon: Hardy kiwi (Actinidia arguta)","https://www.massaudubon.org/nature-wildlife/invasive-plants-in-massachusetts/hardy-kiwi"]],"basis":"sourced","note":"Species and sex of the 4 on hand are unrecorded (arguta or kolomikta; male or female). Fruit needs a male of the same species near the females, unless a self-fertile type like Issai. Vines may take 5 to 9 years to fruit.","reviewed_on":"2026-10-17"},{"id":"honeyberry","group":"Berry","type":"Honeyberry","kind":"species","name":"Honeyberry","aliases":["Haskap"],"inventory_rows":[7],"purchase_rows":[],"tagline":"Early; blue oblong berries; needs two cultivars","summary":"Very cold-hardy blue honeysuckle shrub bearing oblong blue berries in June, ahead of strawberries. Plants need a second, different cultivar that blooms at the same time to set fruit.","appearance":"Thornless, non-suckering shrub 3 to 6 feet tall; leaf shape and plant form vary by cultivar. Berries are dark blue, irregular, round to oblong, from half an inch to over 2 inches long, with thin skin and tiny seeds.","flavor_use":"Tart to sweet by cultivar, tasting somewhere between blueberry, raspberry and currant. Eaten fresh or made into jam, juice, wine, syrup and baked goods. Birds are the main pest, so net plants before the berries color.","uses":["fresh","cooking","juice"],"ripening":"Early","ripening_note":"Early to mid June in Utah, just ahead of strawberries; Boreal-series types ripen later","id_cues":"Dark blue, elongated or irregular berries in June ahead of strawberries on a thornless, non-suckering bush up to about 6 feet. Cream-yellow flowers open very early and tolerate frost to about 19-20F. Leaf shape varies a lot by cultivar, so tags matter.","habit":"Deciduous, long-lived shrub (up to about 30 years), 3 to 6 ft tall and wide; the form varies by variety, from low mounds to upright bushes. Thornless and non-suckering, needing little pruning.","bark":"Branches are light to pale brown, smooth when new and rougher with age; on older wood the outer bark splits into shreds. Branchlets are stiff and hairless, with hair just on young growth.","leaf":"Opposite, oval to oblong leaves, about 1 to 4 in long, with shape varying a lot by variety; dull grayish-green, some with slightly wavy edges, and sometimes hairy on the underside, mostly along the main veins.","hardiness":"Zones 1 to 8 (Wisconsin); scorch and leaf drop in heat above zone 6 (Utah)","sources":[["Utah State Univ. Extension: Haskap in the Garden","https://extension.usu.edu/yardandgarden/research/haskap-in-the-garden.pdf"],["Univ. of Wisconsin Crops and Soils: Honeyberries crop profile","https://cropsandsoils.extension.wisc.edu/honeyberries/"],["Edible Wild Food: Haskap (Lonicera caerulea) identification","https://www.ediblewildfood.com/haskap.aspx"],["Trees and Shrubs Online: Lonicera caerulea","https://www.treesandshrubsonline.org/articles/lonicera/lonicera-caerulea/"]],"basis":"sourced","note":"12 bought (Blue Diamond, Blue Palm, Indigo Treat, Cinderella, Maxine, Sunrise), 11 on hand; which remain is unrecorded. Individual cultivar traits and bloom overlap were not researched.","reviewed_on":"2026-10-17"},{"id":"josta","group":"Berry","type":"Josta","kind":"species","name":"Josta (jostaberry)","aliases":["Giant","Red","Regular","Jostaberry"],"inventory_rows":[8,9,10],"purchase_rows":[],"tagline":"Mid; thornless; big dark berries, sweet-tart","summary":"Thornless hybrid of black currant and gooseberry with berries bigger than a currant. Fruit darkens from green through red to near-black in July and tastes sweet-tart, good fresh or cooked.","appearance":"Vigorous, upright, thornless shrub 5 to 8 feet tall and wide. Berries are gooseberry-sized, bigger than black currants, and ripen through red to purple-black. 'Red Jostaberry' is a selection that looks a bit redder when mature.","flavor_use":"Sweet-tart, with gooseberry tang and a darker black-currant tone; good fresh and in jam, jelly, pie or juice. Ripe berries keep 1 to 2 weeks chilled and freeze well. Birds strip the crop fast without netting.","uses":["fresh","cooking","jelly","juice"],"ripening":"Mid","ripening_note":"Midsummer, usually July; berries ripen unevenly, so pick in several passes","id_cues":"No thorns (the gooseberry parents are spiny), upright bush, very early frost-tender bloom, and berries bigger than black currant that go green, red, then near-black in July. Nursery notes: Red colors up redder, Giant is said to bear larger clusters; no other differences are documented.","habit":"Vigorous, thornless shrub about 4 to 8 ft tall and wide; most sources call it upright, one nursery calls it sprawling. Leafs out early and drops leaves late. Fruits on wood 1 year old and older, so a mix of 1- to 3-year canes is kept.","bark":null,"leaf":"Large, dark green leaves that open early in spring, hang on late, and turn yellow in fall.","hardiness":"Zones 3 to 8; hardy to -40F (Raintree)","sources":[["Raintree Nursery: Jostaberry growing guide","https://raintreenursery.com/pages/jostaberry-growing-guide"],["Raintree Nursery: Red Jostaberry","https://raintreenursery.com/products/red-jostaberry"],["Raintree Nursery: Giant Jostaberry","https://raintreenursery.com/products/giant-jostaberry"],["Edible Landscaping: Josta Berry Black aka Jostaberry","https://ediblelandscaping.com/products/black-josta"],["Burnt Ridge Nursery: Jostaberry (black currant x gooseberry)","https://www.burntridgenursery.com/JOSTABERRY-Black-Currant-x-Gooseberry/productinfo/NSCUJOS/"]],"basis":"sourced","note":"Inventory lines Giant, Red and Regular may match Raintree's 'Giant' and 'Red' selections plus standard josta; their differences come only from nursery text. 18 on hand vs 7 bought (6 black, 1 red).","reviewed_on":"2026-10-17"},{"id":"mulberry-red","group":"Berry","type":"Mulberry","kind":"species","name":"Red mulberry","aliases":["Red","Morus rubra"],"inventory_rows":[11],"purchase_rows":[116],"seed_rows":[27],"tagline":"Mid; tall tree; sweet purple blackberry-like fruit","summary":"Large native eastern tree with sweet, juicy blackberry-like fruit that darkens to purple in summer. Trees are usually male or female, and birds, mammals and people eat the fruit.","appearance":"Tree 25 to 60 feet tall with a short trunk that branches low and gray-brown bark in scaly ridges. Leaves are 3 to 5 inches long. Fruit is a blackberry-like cluster about 1 to 1.25 inches long, reddish at first and dark purple when ripe.","flavor_use":"Sweet and juicy, eaten fresh or made into jelly, jam and wine. The fruit ships and keeps poorly. Trees are slow to start bearing, from about 4 to 10 years, and since most trees are single-sex, some seedlings may never fruit.","uses":["fresh","jelly","wildlife"],"ripening":"Mid","ripening_note":"Fruit fully developed June to August across its range (USDA Silvics)","id_cues":"Alternate toothed leaves 3 to 5 inches long, from unlobed to deeply lobed; usually rough on top and soft and hairy below, though the top can be nearly smooth, so texture is a weak cue. All parts ooze milky sap. White mulberry is a look-alike.","habit":"Deciduous small tree, about 30 to 60 ft tall depending on the source, with a stubby trunk that forks low and a dense, spreading crown. Grows fast on rich, moist soil; self-seeds freely and can turn weedy.","bark":"Bark is gray-brown and irregular, with long ridges that have a scaly surface; young trees can look orange-tinged, most noticeably when wet. Twigs are thin and zigzag, green at first and aging to red-brown, sometimes hairy.","leaf":"Alternate, thin, broadly egg-shaped to nearly round leaves 3 to 5 in long with toothed margins; lobing is highly variable, from none to deeply cut. Rough above, lighter and downy below.","hardiness":"USDA zones 4 to 9 (NC State)","sources":[["NC State Extension: Morus rubra (red mulberry) plant toolbox","https://plants.ces.ncsu.edu/plants/morus-rubra/"],["Virginia Tech Dendrology: Red mulberry fact sheet","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=58"],["USDA Forest Service: Silvics of North America, Red Mulberry (VT reprint)","https://dendro.cnre.vt.edu/dendrology/USDAFSSilvics/58.pdf"]],"basis":"sourced","note":"These sources treat it as a fruit and wildlife tree and do not mention windbreak use. Its native range is the eastern and central US (west to Kansas and Texas), so performance in Idaho is unconfirmed.","reviewed_on":"2026-10-17"},{"id":"sea-berry","group":"Berry","type":"Sea berry","kind":"species","name":"Sea buckthorn (sea berry)","aliases":["Sea Berry","Seaberry"],"inventory_rows":[12],"purchase_rows":[],"tagline":"Late fall; orange berries hang on; very sour","summary":"Hardy, thorny, suckering shrub with silvery leaves and bright orange berries that cling to the twigs into winter. Male and female plants are needed, and the very sour fruit is used for juice.","appearance":"Shrub or small tree 10 to 15 feet tall with narrow silvery-green leaves and sharp thorns. Small yellow flowers open before the leaves. Pea-sized bright orange berries, about 1/4 to 1/3 inch long, crowd the twigs from September through winter.","flavor_use":"Sharply sour and astringent, with no sweetness in North Dakota trials, but rich in vitamin C; used for juice, jam and cordial. Berries do not release from the twig, so pickers cut whole branches, freeze them, then shake the fruit off.","uses":["juice","wildlife","ornamental","windbreak"],"ripening":"Very late","ripening_note":"Ripe Sept to Oct and hangs on through winter; harvest runs late fall to early spring","id_cues":"Narrow silver-scaled leaves 1 to 3 inches long, sharp thorns (some hidden among leaves), yellow flowers before leaf-out, and bright orange berries packed along the twigs into winter. Suckers freely. Plants are dioecious, so only females bear fruit.","habit":"Deciduous large shrub or small tree, 10 to 15 ft tall and 8 to 10 ft wide, spreading and loosely rounded with an open, irregular crown. Suckers freely from the roots into thickets, and stems are armed with numerous stout thorns. Sometimes short-lived.","bark":"Bark is grayish-brown. Twigs are brittle and bear numerous sharp thorns, some hidden among the leaves; buds are silvery to light brown and about 1/8 to 1/4 in long.","leaf":"Alternate, simple, narrow leaves 1 to 3 in long and only 1/8 to 1/4 in wide, with smooth edges. Silvery-white scales mostly wear off with age; silvery-green through summer, turning gray-green by fall.","hardiness":"To at least -40F; USDA zone 3 (NDSU)","sources":[["NDSU Extension: Tree Handbook, Sea-buckthorn (III-47)","https://www.ag.ndsu.edu/trees/handbook/th-3-47.pdf"],["NDSU Carrington REC: Seaberry, Northern Hardy Fruit Evaluation Project","https://www.ag.ndsu.edu/carringtonrec/archive/northern-hardy-fruit-evaluation-project/fruit-index/seaberry/"],["USDA Forest Service: Woody Plant Seed Manual, Hippophae rhamnoides","https://www.fs.usda.gov/nsl/Wpsm/Hippophae.pdf"]],"basis":"sourced","note":"11 on hand; the male-to-female mix is not recorded. NDSU removed its planting over slow picking, suckering and invasiveness worries, though Canadian researchers called it only locally invasive.","reviewed_on":"2026-10-17"},{"id":"viking-aronia","group":"Berry","type":"Aronia","kind":"species","name":"Viking aronia","aliases":["Viking"],"inventory_rows":[13],"purchase_rows":[],"tagline":"Late; blue-black berries; astringent, self-fertile","summary":"Hardy upright shrub grown for dark berries that are too astringent for most people to eat fresh, so they are frozen and made into juice or jelly. Viking is one of the two main berry-production cultivars.","appearance":"Upright shrub about 4 to 8 feet tall that spreads slowly from the crown and by mild suckers, with white flower clusters in early May and red fall color. Berries are blue-black to dark purple, about the size of a large blueberry, in clusters of 10 to 20.","flavor_use":"Puckery and mouth-drying more than bitter, though Viking is among the relatively sweet cultivars. Freeze first, then make juice, jelly, syrup or wine, or add to quick breads, yogurt and smoothies.","uses":["juice","jelly","cooking","ornamental"],"ripening":"Late","ripening_note":"From late August in Wisconsin; about 2 weeks after berries turn blue-black","id_cues":"Black-fruited aronia: shiny dark green leaves, white flower clusters in early May, blue-black berries in clusters of 10 to 20, bright red fall color. Red-fruited aronia is a different, ornamental type. Viking cannot be told from Nero or seedlings by looks in these sources.","habit":"Deciduous, often multi-stemmed shrub about 4 to 8 ft tall (to 10 ft in wild black chokeberry). Grows outward from the crown with modest suckering, though wild plants sucker readily. Old canes need periodic removal.","bark":"Stems are reddish-brown and smooth with small pores (lenticels), later developing diamond-shaped splits. Twigs are slender, reddish brown and hairless, with long narrow buds about 1/3 to 1/2 in long, like serviceberry.","leaf":"Alternate, simple, elliptical to egg-shaped leaves 1 to 3 in long with fine teeth; glossy, deep green above and hairless beneath, with small dark glands along the top of the midrib. Fall color is bright red to orange-red.","hardiness":"USDA zone 3 (NDSU)","sources":[["NDSU Carrington REC: Aronia, Northern Hardy Fruit Evaluation Project","https://www.ag.ndsu.edu/carringtonrec/archive/northern-hardy-fruit-evaluation-project/fruit-index/aronia/aronia-2013-aronia-mitschurinii"],["Univ. of Wisconsin Crops and Soils: Aronia berries crop profile","https://cropsandsoils.extension.wisc.edu/aronia-berries/"],["Univ. of Maryland Extension: Aronia, an alternative crop","https://extension.umd.edu/programs/agriculture-food-systems/program-areas/fruit-vegetable-production/alternative-crops/aronia"],["Virginia Tech Dendrology: Black chokeberry fact sheet","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=480"]],"basis":"sourced","note":"Sources describe aronia in general; only the Wisconsin page names Viking (a main berry cultivar, with Nero). Matches the 2 Viking on the purchase list.","reviewed_on":"2026-10-17"},{"id":"hazelnut","group":"Nut","type":"Hazelnut","kind":"species","name":"Hazelnut (filbert)","aliases":["Jefferson Filbert","Hybrid Hazelnut","Jefferson Filbert Hazelnut","Theta Filbert Hazelnut","Hybrid Hazelnut (controlled-cross)","Hazlenut"],"inventory_rows":[15],"purchase_rows":[70,71,76,118],"tagline":"Early; shrub row; small hybrid nuts, larger Jefferson","summary":"A row of hazelnut shrubs, probably mostly American x European hybrid seedlings from Forestag, with a Jefferson (Oregon State cultivar) and its partner Theta possibly mixed in. Grown for nuts, shelter and wildlife.","appearance":"Shrubby plants; Jefferson stays near 8 to 12 ft. Jefferson nuts are round, with kernels near 1.7 g (45% of nut weight). Hybrid seedling nuts are smaller, thicker-shelled and differ plant to plant. Long, yellow pollen catkins show by late fall.","flavor_use":"Kernels suit roasting and baking; Jefferson is mainly sold in the shell. Seedling hybrids yield modestly and vary, so they work best as backyard trees, wildlife plantings, windbreak shrubs and pollen sources for named cultivars.","uses":["nuts","windbreak","wildlife","pollinizer"],"ripening":"Early","ripening_note":"Jefferson ripens about September per a nursery listing; seedlings vary","id_cues":"Expect plant-to-plant differences in the seedling hybrids. Small nuts in thick, fleshy husks point to the American side; larger round nuts that drop free of the husk point to Jefferson or another European type. Winter bloom is shared by all hazelnuts, so it does not help.","habit":"Multi-stemmed, suckering shrub, typically 8-15 ft tall (Jefferson about 8-12 ft), though unpruned European hazel can top 25 ft. European types can be trained to a single-trunk tree. Crown suckers need thinning or a thicket forms. Long yellow male catkins form in late fall.","bark":"Bark smooth and gray-brown, starting to peel on older European hazel stems; American hazelnut, a hybrid parent, is also gray-brown and smooth with a netted pattern. Young shoots are flexible and hairy; buds are blunt, oval and downy.","leaf":"Leaves round to oval or heart-shaped, with a short point and double-toothed edges; soft and downy underneath, paler than the top; leaves turn yellow before falling.","hardiness":"Arbor Day hybrids zones 4-8; Jefferson zone 5, flowers hardy to -15F","sources":[["Rutgers NJAES: Choosing Plants for a Hazelnut Orchard in New Jersey","https://njaes.rutgers.edu/e368/"],["One Green World: Jefferson Hazelnut Tree","https://onegreenworld.com/product/jefferson-hazelnut-tree/"],["Arbor Day Foundation: The Hybrid Hazelnut Consortium","https://www.arborday.org/campaigns-projects/hybrid-hazelnut-consortium"],["Woodland Trust: Hazel (Corylus avellana)","https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/british-trees/a-z-of-british-trees/hazel/"],["NC State Extension: Corylus americana (American hazelnut) Plant Toolbox","https://plants.ces.ncsu.edu/plants/corylus-americana/"]],"basis":"sourced","note":"Row is labelled Jefferson, but the buys were 75 Forestag hybrid seedlings plus 1 Jefferson and 1 Theta, so most shrubs are likely hybrids. Jefferson resists filbert blight in Oregon but not in New Jersey.","reviewed_on":"2026-10-17"},{"id":"hican","group":"Nut","type":"Hican","kind":"species","name":"Hican","aliases":[],"inventory_rows":[112],"purchase_rows":[69],"tagline":"Mid; pecan x hickory cross; variable seedlings, slow to bear","summary":"A hybrid of pecan and a hickory species, grown for its nuts on a large, long-term tree. Seedlings are genetically variable, and bearing is often slow, erratic or shy.","appearance":"Nut looks like a medium pecan with a slightly thicker shell, in a husk that splits open at maturity. Mature trees are about 49 to 65 ft tall, growing slowly to moderately, with a large taproot.","flavor_use":"Distinct flavor that leans toward hickory with a pecan note (one nursery says roughly 80/20). Shell is a little thicker than pecan. The wood is also used for smoking meat and woodworking.","uses":["nuts"],"ripening":"Mid","ripening_note":"Fruit recorded about mid Sept to mid Oct at Purdue (Indiana); seedlings may differ","id_cues":"Looks much like a medium pecan tree, so leaves and bark are weak clues. Check the nut: pecan-like but with a slightly thicker shell, in a husk that splits at maturity. Seedlings vary, so expect differences between trees.","habit":"Pecan-hickory hybrid that grows into a large tree, about 50-70 ft tall with a round, spreading crown (another nursery says 49-65 ft); said to look much like a medium pecan. Big taproot makes transplanting hard; dropped nuts and leaves are litter. Seedlings vary and may resemble either parent.","bark":null,"leaf":null,"hardiness":"Nursery says zone 4b and up (-30C); not guaranteed, verify locally","sources":[["Food Forest Nursery: Hican Tree Growing Guide","https://www.foodforestnursery.com/growing-guides/nut-trees/hican-trees/"],["Nutcracker Nursery: Hican, Carya illinoinensis x Carya ovata","https://nutcrackernursery.com/products/hican-carya-illinonensis-x-carya-ovata"],["Purdue Arboretum Explorer: Carya x nussbaumeri (Hican)","https://www.arboretum.purdue.edu/explorer/plants/119/"],["Nolin River Nut Tree Nursery: Hican (archived 2009 page)","https://web.archive.org/web/20090322030710/http://www.nolinnursery.com/Hican.htm"],["Rock Bridge Trees: Hicans","https://rockbridgetrees.com/2019/10/hicans/"]],"basis":"sourced","note":"Seedlings of unknown parentage (the hickory species is not stated), so nut traits and cold-hardiness are unpredictable. Some hicans fill poorly or bear little; compatible pecan or hickory pollen nearby helps.","reviewed_on":"2026-10-17"},{"id":"pecan","group":"Nut","type":"Pecan","kind":"species","name":"Pecan (hardy native)","aliases":["Pecan (Native Hardy)"],"inventory_rows":[113],"purchase_rows":[74],"tagline":"Late; thin-shelled buttery nuts; needs long warm season","summary":"Large shade and nut tree grown here from native hardy seedlings. Thin-shelled, buttery nuts, but it needs a long, warm season to ripen them and a second tree for pollen, so crops may be unreliable on a short-season site.","appearance":"Oblong brown nut with black streaks, about 1 to 2 in long, in a green husk that splits into four parts. Tree can reach 50 to 70 ft tall and 50 to 60 ft wide, with leaves 12 to 20 in long carrying 9 to 17 narrow leaflets.","flavor_use":"Sweet kernel with a rich, buttery taste and a soft, smooth bite, held in a thin to medium-thick shell.","uses":["nuts"],"ripening":"Late","ripening_note":"Oct to Nov per the nursery; needs 180+ frost-free days and summer heat","id_cues":"Big tree with long feather-like leaves of 9 to 17 narrow, toothed leaflets; bark smooth when young, later scaly ridges. Husk is thin, green turning brown, and splits in four. Leaves and bark alone may not separate it from hickories, so check the nut.","habit":"Large broad tree: 50-70 ft tall and 50-60 ft wide for a northern seedling, while another source gives 70-100 ft. Evenly balanced, broadly oval crown with main limbs angled upward and outward; old trees droop low branches. Brittle branches break in wind; deep taproot hinders transplanting.","bark":"Gray-brown to light brown bark, smooth while young, later splitting into scaly ridges. Twigs fairly stout and reddish-brown; the end bud is yellow-brown and 1/4 to 1/2 in long.","leaf":"Compound leaves 12-20 in long with 9-17 narrow, toothed leaflets 4-7 in long, often sickle-curved; end leaflet present. Leaves stay on the tree until late fall.","hardiness":"Zones 5-9 or 5-10 as sources state; warm sites do best","sources":[["Utah State University Extension: Pecan (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/pecan"],["Willis Orchard Company: Pecan (Native Hardy Seedling)","https://www.willisorchards.com/product/pecan-native-hardly-seedling"],["Rock Bridge Trees: Northern Pecan Varieties for the Mid-South","https://rockbridgetrees.com/northern-pecan-trees/"],["NC State Extension: Carya illinoinensis (pecan) Plant Toolbox","https://plants.ces.ncsu.edu/plants/carya-illinoinensis/"]],"basis":"sourced","note":"Seedlings are unnamed, so nut size, ripening and hardiness vary. Sources start at zone 5 and ask for 180+ frost-free days; USU notes one tree fruiting in Logan, Utah, but a zone 4 or short-season site may not ripen nuts.","reviewed_on":"2026-10-17"},{"id":"walnut-english","group":"Nut","type":"Walnut","kind":"species","name":"English walnut","aliases":["English","Persian walnut"],"inventory_rows":[114],"purchase_rows":[],"seed_rows":[23],"tagline":"Mid; thin shell, mild nuts; use hardy Carpathian types","summary":"Common (Persian) walnut: a large, spreading tree with thin-shelled, mild nuts. Utah guidance favors hardy Carpathian-type strains for most sites; other English walnuts suit only warmer places.","appearance":"Nuts ripen inside a smooth green hull that darkens and dries by harvest; the shell itself is thin and wrinkled. Tree reaches 40 to 60 ft tall and as wide, with a rounded crown.","flavor_use":"Mild, sweet kernel from a shell that cracks easily; good fresh or baked. Dry nuts at 95-105 F for a few days; they keep 3 to 6 months at room temperature and about a year below freezing.","uses":["nuts","fresh","cooking"],"ripening":"Mid","ripening_note":"October per a nursery; earliest types need 140-150 days without hard freeze (Utah)","id_cues":"Compound leaves a foot or more long, with 5 to 11 oblong leaflets that give off a citrus scent when crushed. Young bark is smooth and gray; old bark forms diamond-shaped ridges. Seed-grown trees may not be hardy Carpathian types.","habit":"Spreading tree with a rounded to open crown, 40-60 ft tall and about as wide; train to a central or modified leader. Deep taproot makes transplanting hard. Nuts begin at 4-6 years, with good crops after 15-20 years. Intolerant of shade.","bark":"Young bark is smooth and gray; with age it forms diamond-shaped ridges. Stem pith is chambered, and the end bud is 2-3 times larger than the side buds.","leaf":"Leaves 12-18 in long with 5-11 (often 5-9) oblong leaflets about 2-6 in long; the end leaflet is largest and the lowest are smallest. Crushed leaves smell of citrus.","hardiness":"Carpathian types to about -10 to -20 F (zone 5-9); others need warmer sites","sources":[["Utah State University Extension: How to Grow Walnuts in Your Yard","https://extension.usu.edu/yardandgarden/research/walnuts-in-the-home-orchard"],["NC State Extension: Juglans regia (English walnut) Plant Toolbox","https://plants.ces.ncsu.edu/plants/juglans-regia/"],["One Green World: Carpathian English Walnut","https://onegreenworld.com/product/carpathian-english-walnut/"],["Oregon State University: Juglans regia (English walnut) Landscape Plants","https://landscapeplants.oregonstate.edu/plants/juglans-regia"]],"basis":"sourced","note":"Probably seed-grown, so strain and hardiness are unknown; only Carpathian types are advised for cold Intermountain sites. Roots make juglone, which harms blueberries, tomatoes and some other plants.","reviewed_on":"2026-10-17"},{"id":"walnut-heartnut","group":"Nut","type":"Walnut","kind":"species","name":"Heartnut (Japanese walnut)","aliases":["Heartnut Japanese","Heartnut"],"inventory_rows":[115],"purchase_rows":[68],"tagline":"Early; heart-shaped nuts crack easily; huge leaves","summary":"Heartnut is a Japanese walnut form with flattened, heart-shaped nuts that split easily along the seam. The kernel is mild and sweet; the tree is fast, wide-spreading and has very large compound leaves.","appearance":"Nut is flattened and heart-shaped, splitting into two heart-shaped halves; in the best forms the kernel drops out whole. Compound leaves reach 2 to 3 ft long, and stout twigs are roughly broom-handle thick; old trees can stay low and spreading, about 20 to 30 ft tall.","flavor_use":"Mild, sweet kernel; the Rhodes seedling line is described as smooth and creamy with little bitterness. Shell is thin and splits along the seam. A grower reports good keeping at room temperature, with flavor improving in storage.","uses":["nuts","fresh","cooking"],"ripening":"Early","ripening_note":"September per a nursery listing; seedlings may differ","id_cues":"Oversized compound leaves with a tropical look, 2 to 3 ft long, on stout twigs; wide, low crown. Nuts hang in clusters and are flattened hearts, unlike the thick, rough, cylindrical nuts of wild Japanese walnut, which seedlings can revert to.","habit":"Fast, vigorous tree (6-8 ft a year in Iowa) with a strong central leader and broad canopy that is often low and wide-spreading; old trees may be 100 ft across yet only 20-30 ft tall. Quoted sizes differ: 20-30 ft, 35-40 ft, up to 65 ft for wild Japanese walnut.","bark":"Light gray trunk bark (described for Japanese walnut); texture not given. Twigs are notably thick, roughly like a broom handle.","leaf":"Very large compound leaves, 2-3 ft long, with 11-17 serrated leaflets about 3-7 in long; bright yellowish green, downy underneath and on the midrib, giving a tropical look.","hardiness":"Best in zones 5-6, some types to 4; one nursery rates seedlings 4b (-25F)","sources":[["Red Fern Farm: Heartnuts (Tom Wahl)","https://redfernfarm.com/index.php/2017/01/11/heartnuts/"],["Montana Fruit Trees: Rhodes Heartnut Seedling (Bundle of 2)","https://www.montanafruittrees.com/products/rhodes-heartnut-seedling"],["Stark Bro's: Heartnut Tree (Japanese walnut)","https://www.starkbros.com/products/nut-trees/walnut-trees/heartnut"],["Oregon State University: Juglans ailantifolia (Japanese walnut, heartnut)","https://landscapeplants.oregonstate.edu/plants/juglans-ailantifolia"],["Wikipedia: Juglans ailantifolia (Japanese walnut)","https://en.wikipedia.org/wiki/Juglans_ailantifolia"]],"basis":"sourced","note":"Montana Fruit Trees sells heartnut seedlings (Rhodes line) in pairs; if that is what was bought, each tree is genetically unique and some may bear thick-shelled wild-type nuts. Plant two or more for pollination; mature size is uncertain.","reviewed_on":"2026-10-17"},{"id":"hickory-shellbark","group":"Nut","type":"Hickory","kind":"species","name":"Shellbark hickory","aliases":["Shellbark Hickory","Carya laciniosa","HS"],"inventory_rows":[],"purchase_rows":[75],"tagline":"Mid; large nuts, thick husk; slow, deep taproot","summary":"Native hickory of moist river bottoms with sweet nuts bigger than any other hickory has. Slow-growing and deep-taprooted, it wants deep moist soil and takes many years to bear.","appearance":"Fruit is tan to brown, about 1.8 to 2.4 in long, in a husk 1/4 to 1/2 in thick that splits to the base in four parts. The cream-colored nut is 4-angled with a thick shell; about 25 to 35 cleaned nuts weigh a pound.","flavor_use":"Sweet, buttery kernel in a thick shell; many rate it below shagbark. Hickories are mostly self-fertile but crop better with cross-pollination (Willis lists a pollinator as needed), so plant several. Pecan weevil and hickory shuckworm can cut yields.","uses":["nuts","wildlife","timber"],"ripening":"Mid","ripening_note":"September to October per USDA NRCS, some fruit hanging to December; Willis lists September to November","id_cues":"Versus shagbark: usually 7 to 9 leaflets (shagbark 5) with no hair tufts on the leaf-tooth tips, heavier branches, and much bigger nuts. Bark plates are straighter, but both are shaggy, so bark is a weak cue. Hybrids with shagbark and pecan occur.","habit":"Large, slow-growing, long-lived tree, roughly 65 to 100 ft tall, with an open round-to-oblong crown. The seedling puts down a long taproot fast while the shoot grows slowly, so it transplants poorly; it resprouts after cutting. Leafs out late, in late May to June.","bark":"Smooth light gray with shallow ridges when young, later long broad plates that peel up from the trunk for a shaggy look. Twigs are thick, orange-brown and rusty-hairy when young, with a large, elongated terminal bud.","leaf":"Alternate, compound, roughly 1 to 3 ft long, usually with 7 to 9 leaflets 3.5 to 8 in long. Leaflets are coarsely toothed, shiny dark green above, paler and soft-hairy below, with no hair tufts on the teeth.","hardiness":"Zones 5-9 (Willis); -15 F average minimum in northern native range (USDA)","sources":[["USDA NRCS: Plant Guide, Shellbark hickory (Carya laciniosa)","https://plants.usda.gov/DocumentLibrary/plantguide/pdf/pg_cala21.pdf"],["USDA Forest Service: Silvics of North America, Shellbark Hickory","https://dendro.cnre.vt.edu/dendrology/USDAFSSilvics/450.pdf"],["Willis Orchard Company: Shellbark Hickory Tree","https://www.willisorchards.com/product/shellbark-hickory-tree"]],"basis":"sourced","note":"Native to deep moist bottomland with 150-210 frost-free days; only occasionally on dry sandy soil (USDA). A short-season, dry, windy site is likely a poor fit; no page I read rates wind. Bearing: 10-20 yrs (Willis) vs 40-yr minimum (USDA).","reviewed_on":"2026-10-17"},{"id":"douglas-fir","group":"Evergreen","type":"Douglas-fir","kind":"species","name":"Douglas-fir","aliases":["Douglas Fir","Dg. Fir"],"inventory_rows":[19],"purchase_rows":[],"tagline":"Native conifer; 3-pointed cone bracts; flat needles","summary":"Native Idaho evergreen; the Rocky Mountain (interior) form grows slower and is hardier than the coastal form. Tall, straight pyramid for windbreak, wildlife food and timber.","appearance":"Tall, straight-stemmed pyramid, dense when young and more open with age. Wild interior trees reach roughly 100-130 ft; landscape-size trees are listed at 40-70 ft tall and 20-30 ft wide. Evergreen, blue-green all year.","flavor_use":"Mid-size to tall windbreak conifer; seeds feed birds and small mammals, and deer and elk browse the twigs. Wants moist, well-drained loam and full sun and will not take standing water. Seed source affects hardiness, so interior stock is the safer choice.","uses":["windbreak","wildlife","timber"],"ripening":null,"ripening_note":"Evergreen all year; cones mature to brown in late summer.","id_cues":"Hanging cones with a three-pointed bract sticking out past each scale (true firs and spruces lack these). Needles single and flat, without the pegs of spruce or the suction-cup bases of firs; buds long, sharp, red-brown. Thick corky bark develops around age 40.","habit":"Cone-shaped crown of firm, straight branches that sag low on the tree and angle upward near the top; full while young, thinning with age. Open-grown trees keep branches low on the trunk, crowded ones shed them. Slower growing and hardier than the coastal form.","bark":"Smooth gray with resin blisters on young stems; around age 40 it turns thick, corky and red-brown, split into ridges by deep furrows. Twigs are thin and reddish-brown, carrying long, pointed, sharp-tipped buds.","leaf":"Flat needles about 1 in long (0.6-1.4 in), single and spiraled around the twig, blunt-tipped; yellow-green to blue-green above with two white bands beneath. Fragrant when crushed. Evergreen.","hardiness":"Zone 3 for the Rocky Mountain form (NDSU)","sources":[["Virginia Tech Dendrology: Douglas-fir (Pseudotsuga menziesii)","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=105"],["USDA Forest Service FEIS: Rocky Mountain Douglas-fir (var. glauca)","https://www.fs.usda.gov/database/feis/plants/tree/psemeng/all.html"],["NDSU Tree Handbook: Rocky Mountain Douglas-fir (III-153)","https://www.ag.ndsu.edu/trees/handbook/th-3-153.pdf"]],"basis":"sourced","note":"Interior form (var. glauca) assumed; inventory records only Douglas-fir. Sources differ on cone length (about 1.6-2.8 in vs 2-4 in) and needle length.","reviewed_on":"2026-10-17"},{"id":"eastern-red-cedar","group":"Evergreen","type":"Juniper","kind":"species","name":"Eastern red cedar","aliases":["Eastern Red Ceder","Juniperus virginiana"],"inventory_rows":[20],"purchase_rows":[],"seed_rows":[12],"tagline":"Hardy evergreen; shreddy bark; cedar-apple rust host","summary":"A juniper often called a cedar (botanically it is a juniper, not one of the true cedars). Hardy, drought-tolerant evergreen for windbreaks and hedges, with shreddy bark and blue berries. Carries cedar-apple rust.","appearance":"Mid-sized evergreen about 30-45 ft tall and 15-30 ft wide, on a short trunk. Compact pyramid in youth that loosens and sags a little with age. Blue-green in summer, red-brown to purplish in winter; female trees bear dusty blue berries.","flavor_use":"Windbreak and hedge tree; takes drought, alkaline and salty soil, and the berries feed birds. Heartwood resists rot, so it suits fence posts. Host of cedar-apple rust: keep a few hundred yards from apples, crabapples and hawthorns, or choose resistant varieties.","uses":["windbreak","wildlife","timber"],"ripening":null,"ripening_note":"Blue berry-like cones ripen within one season, on female trees.","id_cues":"Tiny scale leaves in overlapping pairs plus prickly, spiny-tipped juvenile leaves, often both on one tree; turns red-brown or purplish in winter. Gray to red-brown bark shreds in long strips. Rocky Mountain juniper is similar but does not turn red-brown in winter (see its entry).","habit":"Grows at a moderate-to-slow pace, lives a long time and is hardy; deep taproot. Male and female cones usually grow on separate trees. Needs full sun; only young trees put up with shade.","bark":"Gray-brown to red-brown, thin and fibrous, shedding in long narrow strips and often leaving gray patches beneath. Twigs are green at first, then brown; buds are tiny and hidden under leaves of the same color.","leaf":"Scale-like and awl-shaped leaves, often both on one tree, with scale leaves in overlapping pairs; juvenile leaves are prickly with spiny tips. Blue-green in summer, red-brown to purplish in winter.","hardiness":"Zones 2-9 (Utah State); zone 2 (NDSU)","sources":[["NDSU Tree Handbook: Eastern Red-cedar (III-173)","https://www.ag.ndsu.edu/trees/handbook/th-3-173.pdf"],["Utah State Univ. Extension TreeBrowser: Redcedar, Eastern","https://extension.usu.edu/treebrowser/catalog/redcedar-eastern"],["Univ. of Minnesota Extension: Cedar-apple rust","https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/yard-and-garden-problems/cedar-apple-rust"]],"basis":"sourced","note":"Workbook lists 40-50 ft; NDSU gives 30-45 ft. If the 7 trees south of the orchard sit a few hundred yards or less from apples, expect rust (UMN says spores can travel over a mile).","reviewed_on":"2026-10-17"},{"id":"juniper","group":"Evergreen","type":"Juniper","kind":"genus","name":"Juniper (variety not recorded)","aliases":["Juniper Variety","Rocky Mountain juniper"],"inventory_rows":[21],"purchase_rows":[],"tagline":"Blue-green juniper; tight scale leaves; 2-year berries","summary":"Likely Rocky Mountain juniper, a hardy, drought-tolerant evergreen for windbreaks. Narrow to pyramidal, keeps its color through winter, with bright blue berries. Can carry cedar-apple rust.","appearance":"Smallish to mid-sized evergreen, usually 20-40 ft tall and 12-20 ft wide, narrow to pyramidal with upward-reaching branches. Foliage runs from deep to pale bluish-green, sometimes plain light green, and keeps its color through winter; female trees carry blue berries.","flavor_use":"Windbreak and screen tree that holds its lower branches; needs little water once settled in, and full sun. Berries and cover help wildlife. Susceptible to cedar-apple rust: keep away from apples, crabapples, juneberries and hawthorns.","uses":["windbreak","wildlife","ornamental"],"ripening":null,"ripening_note":"Berry-like cones take two years to ripen, on female trees.","id_cues":"Leaves hug the twig instead of overlapping in pairs, and stay blue-green in winter; berries are bright blue and need 2 years to ripen. Bark shreds on both junipers, a weak cue. Eastern red cedar browns in winter, ripens berries in 1 year and opens up and droops with age.","habit":"Crown shape varies from pyramid to narrow column, usually with lots of long branches angled upward; seedling trees vary in form and cultivars range from low spreaders to narrow columns. Holds its lower branches. Male and female cones usually grow on separate trees; shade intolerant.","bark":"Brown to gray or reddish-brown and fibrous, peeling in narrow strips; older bark cracks into a web of shallow furrows between flat ridges. Twigs slender and red-brown with age; buds tiny and hard to see among the leaves.","leaf":"Awl-shaped or scale-like leaves, about 0.25-0.33 in long, pressed against the twig rather than in overlapping pairs. Light to dark bluish-green, often with a waxy bloom, with little winter color change.","hardiness":"Zone 3 (NDSU); zones 3-7 (Utah State)","sources":[["NDSU Tree Handbook: Rocky Mountain Juniper (III-157)","https://www.ag.ndsu.edu/trees/handbook/th-3-157.pdf"],["NDSU Tree Handbook: Eastern Red-cedar (III-173)","https://www.ag.ndsu.edu/trees/handbook/th-3-173.pdf"],["Utah State Univ. Extension TreeBrowser: Juniper, Rocky Mountain","https://extension.usu.edu/treebrowser/catalog/juniper-rocky-mountain"]],"basis":"sourced","note":"Inventory says only 'Variety'; the workbook lists Rocky Mountain juniper, so that is described. Cultivars vary widely in shape and color. Workbook says 20-30 ft; NDSU gives 20-40 ft. The Rocky Mountain juniper species profile describes that species in full.","reviewed_on":"2026-10-17"},{"id":"austrian-pine","group":"Evergreen","type":"Pine","kind":"species","name":"Austrian pine","aliases":["Austrian Black Pine","Pinus nigra"],"inventory_rows":[22],"purchase_rows":[],"seed_rows":[22],"tagline":"Dense young pine; 2 stiff needles; silvery buds","summary":"European pine widely planted in the West as a hardy windbreak and screen. Stiff needles in pairs and silvery buds tell it from ponderosa pine.","appearance":"Mid-sized to large pine, about 50 ft tall and 30 ft wide. Densely conical for its first 20 years or so, then it loses lower branches and turns irregular and flat-topped. Yellow-green to blue-green foliage all year.","flavor_use":"Useful in groups, border rows and windbreaks, mainly while young, since the canopy thins with age. Takes poor dry soil, salt spray and city conditions. Prevent drought stress to limit Sphaeropsis (Diplodia) tip blight; nematodes may kill a tree within a year.","uses":["windbreak","ornamental"],"ripening":null,"ripening_note":"","id_cues":"Always 2 stiff, sharp needles per bundle, 3-6 in long. Buds are silvery with stripes; cones 2-3 in with non-pointed (not prickly) scales; bark dark and platy. Ponderosa has 2 and 3 needles per bundle (length overlaps), cinnamon resinous buds, prickly 3-6 in cones and orange-cinnamon plates.","habit":"Dense for roughly the first 20 years, then sheds lower branches and becomes irregular and flat-topped. About the same size and build as native ponderosa pine. Tolerates poor, dry soil; shade intolerant.","bark":"Rough, plated bark that starts dark brown and fades to gray with age. Twigs orange-brown and hairless; buds silvery with stripes, about 1/2 to 3/4 in long.","leaf":"Needles come in pairs, 3-6 in long (about 5 in typical); slim, rigid and sharp-pointed, in shades from yellow-green to blue-green; they persist 3-4 years.","hardiness":"Zones 4-7 (Utah State); zones 3-7 (Virginia Tech)","sources":[["Utah State Univ. Extension TreeBrowser: Pine, Austrian","https://extension.usu.edu/treebrowser/catalog/pine-austrian"],["Utah State Univ. Extension TreeBrowser: Pine, Ponderosa","https://extension.usu.edu/treebrowser/catalog/pine-ponderosa"],["Virginia Tech Extension: Austrian Pine, Pinus nigra","https://www.pubs.ext.vt.edu/3010/3010-1462/3010-1462.html"]],"basis":"sourced","note":"Workbook lists 30-50 ft; Virginia Tech gives about 50 ft. Utah State found it mostly pest-free in Utah but notes Dothistroma and tip blight problems elsewhere.","reviewed_on":"2026-10-17"},{"id":"ponderosa-pine","group":"Evergreen","type":"Pine","kind":"species","name":"Ponderosa pine","aliases":["Ponderosa","Pinus ponderosa"],"inventory_rows":[23],"purchase_rows":[],"seed_rows":[15],"tagline":"Tall native pine; orange plated bark; long needles","summary":"Tall native pine; the interior (Rocky Mountain) form has shorter needles and smaller cones than the coastal form. Older trees have orange plated bark; used for windbreak and timber.","appearance":"Large pine that can reach 60-125 ft tall and 25-30 ft wide. Narrow pyramid when young; old trees have an irregular, open crown and a trunk bare of branches for over half its height. Long-lived, up to about 600 years. Green year-round.","flavor_use":"Tall windbreak and timber pine; tolerates drought and alkaline or salty soil; seeds are squirrel food and birds nest in it. Needs full sun and well-drained ground. Porcupines gnaw bark and small trees; needle cast diseases and bark beetles are known problems.","uses":["windbreak","timber","wildlife"],"ripening":null,"ripening_note":"","id_cues":"Orange-cinnamon bark plates split by deep furrows, with a vanilla or turpentine smell. Long needles in 2s and 3s, stout orange-brown twigs, resin-coated cinnamon buds, and 3-6 in cones with a prickle on each scale. Austrian pine is a look-alike with sharper needles.","habit":"Slow growing and long-lived; its deep taproot makes it wind-firm. Sheds lower branches as it ages. Does poorly in shade, standing water or poorly drained soil.","bark":"Young trunks are blackish brown; mature trunks wear broad flat slabs in orange-brown to rusty red, with deep grooves between them (the puzzle-piece look). Thick bark resists fire. Crushed bark and twigs smell resinous; inner bark smells of vanilla.","leaf":"Long, stiff needles, 2 or 3 per bundle, roughly 3-10 in long, dark to yellowish green, with sharp tips and a slight twist; each needle lasts 3-6 years. The interior form has shorter needles, often 2 per bundle.","hardiness":"Zones 3-7 (Utah State); zone 3 (NDSU)","sources":[["Utah State Univ. Extension TreeBrowser: Pine, Ponderosa","https://extension.usu.edu/treebrowser/catalog/pine-ponderosa"],["NC State Extension Plant Toolbox: Pinus ponderosa","https://plants.ces.ncsu.edu/plants/pinus-ponderosa/"],["NDSU Tree Handbook: Ponderosa Pine (III-169)","https://www.ag.ndsu.edu/trees/handbook/th-3-169.pdf"]],"basis":"sourced","note":"Interior form (var. scopulorum) assumed; inventory gives species only. Sources differ on needles per bundle (2 vs 2-3, mostly 3) and length. Workbook says 60-100 ft; NC State says 60-125 ft.","reviewed_on":"2026-10-17"},{"id":"white-pine","group":"Evergreen","type":"Pine","kind":"species","name":"White pine (western white pine)","aliases":["Western White Pine","Wht. Pine","WWP","Pinus monticola"],"inventory_rows":[24],"purchase_rows":[],"seed_rows":[19],"tagline":"Idaho state tree; 5 soft needles; long hanging cones","summary":"Idaho's state tree, a tall timber pine of the northern Rockies with soft needles in bundles of five. Rarely planted in yards and prone to blister rust.","appearance":"Tall, fairly narrow pine with slender drooping branches and a long clean trunk; crown can be symmetrical or one-sided. About 60-100 ft in cultivation and up to around 175 ft in northern Idaho forests, growing fast on deep, moist soil.","flavor_use":"Timber pine, rarely planted in yards. Prefers moist, rich, deep soil but can manage dry sandy sites. Five-needle pines get white pine blister rust; currants and gooseberries are the alternate hosts, so keep them apart. Rust-resistant seedlings exist.","uses":["timber","ornamental"],"ripening":null,"ripening_note":"","id_cues":"Five soft, bluish-green needles per bundle and very long (4-15 in), slender hanging cones with unarmed scales. Mature bark breaks into small dark blocks. Five needles are shared with other white pines; eastern white pine has shorter cones and needles that last fewer years.","habit":"Grows fast on deep, porous, moist soil. Crown is usually slim but may spread wide, and can be symmetrical or lopsided, with drooping slender branches; forest trees often have a bare trunk for the lower two-thirds. Moderately shade tolerant; prefers sun.","bark":"Thin, smooth and pale gray to gray-green when young; later dark gray to nearly black, thick and divided into small rectangular plates by furrows and cross-cracks. Twigs begin rusty and hairy, later reddish-brown to purplish-brown and smooth.","leaf":"Five needles per bundle, each about 2-5 in long, thin, straight, supple and soft; bluish-green with faint white lines and finely saw-toothed edges. The bundle sheath drops off, and needles last 3-4 years.","hardiness":"Zones 5-8 (Utah State, which queries 3-4)","sources":[["Utah State Univ. Extension TreeBrowser: Pine, Western White","https://extension.usu.edu/treebrowser/catalog/pine-western-white"],["Idaho Forest Products Commission: Western White Pine","https://www.idahoforests.org/content-item/western-white-pine/"],["Washington State Univ. HortSense: White pine blister rust","https://hortsense.cahnrs.wsu.edu/fact-sheet/pine-white-pine-blister-rust/"]],"basis":"sourced","note":"Both trees died (owner report; cause not recorded). Inventory says only 'White'; the workbook names western white pine, so that is described. Needle length: 2-4.5 in (Utah State) vs 3-5 in (Idaho).","reviewed_on":"2026-10-17"},{"id":"blue-spruce","group":"Evergreen","type":"Spruce","kind":"species","name":"Blue spruce","aliases":["Colorado blue spruce","Picea pungens","Blue"],"inventory_rows":[25],"purchase_rows":[],"seed_rows":[26],"tagline":"Dense pyramid; sharp square needles; hanging cones","summary":"Dense, pyramidal Rocky Mountain spruce with sharp four-sided needles. Foliage is silvery blue or plain green; used as a windbreak, screen or specimen.","appearance":"Broad, dense pyramid with stiff branches held level and reaching the ground; about 30-65 ft tall and 15-25 ft wide, eventually quite large. Foliage runs from dull green through blue-green to silvery blue; in the wild it is about as often green as blue.","flavor_use":"Windbreak, screen or specimen evergreen. More drought tolerant than other spruces, yet may struggle in extreme heat and hot dry winds and may blow over; chronic under-watering invites spruce ips beetle. Watch for Cytospora canker, needle cast and gall adelgid galls. Full sun, no flooding.","uses":["windbreak","ornamental","wildlife"],"ripening":null,"ripening_note":"","id_cues":"Single, sharp, four-sided needles on small woody pegs, so twigs feel rough; cones hang down and are papery. Pines bundle their needles; true firs such as white fir have flat needles and upright cones. Bark is gray and scaly. Blue color is unreliable; many are green.","habit":"Slow growing and shallow-rooted, with branches to the ground if left alone. Trees can be toppled by wind. Needs full sun; no shade, no flooding.","bark":"Pale to dark gray or ash-brown, thin and scaly on young trees, with broad heavy ridges forming on older trunks. Buds yellowish-brown, blunt and not sticky.","leaf":"Stiff, sharply pointed, four-sided needles about 0.75 to 1.25 in long, attached one at a time on pegs and standing out all around the twig; dull green to blue-green to silvery blue; fragrant when crushed.","hardiness":"Zone 2 (NDSU); zones 2-7 (Utah State)","sources":[["Utah State Univ. Extension TreeBrowser: Spruce, Blue or Colorado Blue","https://extension.usu.edu/treebrowser/catalog/spruce-blue-colorado"],["NDSU Tree Handbook: Colorado (Blue) Spruce (III-177)","https://www.ag.ndsu.edu/trees/handbook/th-3-177.pdf"],["NDSU Tree Handbook: White or Concolor Fir (true fir contrast)","https://www.ag.ndsu.edu/trees/handbook/th-3-155.pdf"]],"basis":"sourced","note":"Workbook says zones 1-7 and 50-75 ft; extension sources say zone 2 and about 30-65 ft. Inventory 'Blue' may be a green-needled seedling; color varies.","reviewed_on":"2026-10-17"},{"id":"hinoki-cypress","group":"Evergreen","type":"Cypress","kind":"species","name":"Hinoki cypress","aliases":["Hinoki Cypress","Chamaecyparis obtusa"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[4],"tagline":"Large cypress; flat scale-leaf fans; red shreddy bark","summary":"Hinoki cypress (Chamaecyparis obtusa) is a Japanese evergreen with flat, fan-like sprays of scale leaves. Grown from seed it becomes a full-size tree, so here it is an ornamental needing shelter.","appearance":"Cone-shaped, broad or narrow, with horizontal spreading branches whose tips droop. About 50-75 ft tall and 10-25 ft wide in gardens; up to 120 ft in native forest. Dark green, with no fall color, and it can turn brown in winter.","flavor_use":"Ornamental specimen; seedlings grow into the full-size tree, not the dwarf garden forms. Wants wind shelter and moist, well-drained soil, and does poorly in alkaline soil. Transplants badly. Juniper blight, bagworms and root rot are listed problems.","uses":["ornamental"],"ripening":null,"ripening_note":"","id_cues":"Flat, fan-shaped sprays of scale leaves, with white X or Y marks underneath and blunt tips; two scale sizes. Shreddy reddish bark. Small round orange-brown cones, about 1/3 to 1/2 in wide, with 8-10 scales.","habit":"Medium growth rate. Cone-shaped crown with branchlets held in flat horizontal layers and drooping branch tips. Resents transplanting, so plant small and leave it. Suckering is not described.","bark":"Red-brown, fibrous bark that splits and peels away in thin strips. Sources do not describe young-trunk bark, twig color or buds.","leaf":"Tiny scale leaves pressed flat to the twig in two sizes (larger pair boat-shaped, smaller pair triangular), dark green above with white X or Y marks below, tips blunt. Seedlings start with awl-shaped leaves.","hardiness":"Zone 5 (UConn); zone 6 (Gymnosperm Database)","sources":[["NC State Extension: Chamaecyparis obtusa (Hinoki cypress), Plant Toolbox","https://plants.ces.ncsu.edu/plants/chamaecyparis-obtusa/"],["UConn Plant Database: Chamaecyparis obtusa, Hinoki Falsecypress","https://plantdatabase.uconn.edu/detail.php?pid=106"],["Gymnosperm Database: Chamaecyparis obtusa","https://www.conifers.org/cu/Chamaecyparis_obtusa.php"]],"basis":"sourced","note":"Sheet says zones 4 to 8, but sources give zone 5 or 6, so zone 4 is marginal. NC State says it needs wind protection; UConn says it browns in winter and does poorly in alkaline soil.","reviewed_on":"2026-10-17"},{"id":"cedar-of-lebanon","group":"Evergreen","type":"Cedar","kind":"species","name":"Cedar of Lebanon","aliases":["Cedrus libani"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[6],"tagline":"Slow big cedar; needle tufts, barrel cones; zone 5+","summary":"Cedar of Lebanon (Cedrus libani) is a slow-growing evergreen native from Turkey to Lebanon and Cyprus. It forms a large, flat-topped specimen tree, but cold hardiness is the limit at this site.","appearance":"Pyramidal when young; with age the crown thickens and flattens on top, branches spread level and the lowest ones touch the ground. Typically 40-60 ft tall and 30-50 ft wide; 120 ft has been recorded. Foliage stays green to blue-green all year.","flavor_use":"Specimen, screen or shade tree for a large open lot. Needs full sun and good drainage; tolerates dry soil and a range of soil pH, but not shade or air pollution. Slow and hard to transplant. Highly flammable, so keep it away from buildings.","uses":["ornamental","shade"],"ripening":null,"ripening_note":"Cones mature in fall, about every other year; seeds drop from ripening until spring","id_cues":"Stiff needles in tufts of about 30-40 (single on new growth), three- to four-sided in section, dark green with silver-blue stripes. Barrel-shaped woody cones stand upright on branches. Other true cedars share the needle pattern; Taurus-type sizes reportedly sit between Lebanon and Atlas cedar, so size is a weak cue.","habit":"Slow, especially for the first 20 years. Left alone it can form several leaders, so train one if wanted. The Taurus (stenocoma) form is more columnar, with slightly nodding branch tips. Suckering is not described.","bark":"Dark gray, fissured and fragrant on older trunks. Sources do not describe young bark, twig color or buds.","leaf":"Short, stiff, prickly needles about 3/4 to 1.5 in long, dark green to blue-green with silver-blue stripes and fragrant, in tufts (single on new shoots). Evergreen.","hardiness":"5a-7b (NC State); stenocoma strain zone 5; older stock zone 7 south (Purdue)","sources":[["NC State Extension: Cedrus libani (Cedar of Lebanon), Plant Toolbox","https://plants.ces.ncsu.edu/plants/cedrus-libani/"],["Oregon State Univ. Landscape Plants: Cedrus libani 'Stenocoma'","https://landscapeplants.oregonstate.edu/plants/cedrus-libani-stenocoma"],["Purdue Arboretum: Cedrus libani ssp. stenocoma 'Purdue Hardy'","https://www.arboretum.purdue.edu/explorer/plants/128/"]],"basis":"sourced","note":"Sheet says 5b to 9. Sources: zones 5a-7b; hardier Taurus (stenocoma) strains are documented to zone 5 only, never zone 4. Purdue: most saplings from one Middle East seed collection died in zone 5a winters, so seed source matters.","reviewed_on":"2026-10-17"},{"id":"juniper-rocky-mountain","group":"Evergreen","type":"Juniper","kind":"species","name":"Rocky Mountain juniper","aliases":["Rocky Mountain Juniper","Juniperus scopulorum"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[13],"tagline":"Slow native juniper; scale leaves, blue berries; apple-rust host","summary":"Rocky Mountain juniper (Juniperus scopulorum) is a slow-growing native evergreen with tiny scale leaves and waxy blue berry-like cones. It suits dry sites and windbreaks but hosts cedar-apple rust.","appearance":"Usually one trunk, sometimes forked low, under a conical to irregular crown; up to about 45 ft in the wild. Foliage runs light to dark green and often looks silvery-blue from a waxy coat.","flavor_use":"Windbreak, wildlife cover and bird food on dry sites; prefers somewhat alkaline soil. Hosts cedar-apple rust, which spots apple leaves and fruit: keep it away from the orchard and cut out galls in early spring. Winter wind can burn the foliage.","uses":["windbreak","wildlife","ornamental"],"ripening":null,"ripening_note":"Berry-like cones need two seasons; ripe by Nov-Dec of the second year, then stay on until spring","id_cues":"Tiny scale leaves lie close to the twig; waxy blue cones (1/4 to 1/3 in) ripen in the second year. Eastern redcedar is very similar and hybridizes: its fruit ripens the first autumn and its bark peels as thin narrow scales, while this one splits into flat ridges with shreddy scales.","habit":"Slow: wild trees average about 1 ft at 8 years, 13-14 ft at 40 and 18 ft at 80. Sexes are mostly on separate trees, so only females bear berries. It does not resprout after top-kill. Dense branches suit windbreaks.","bark":"Brown and thin, peeling in narrow strips. Small branchlets are smooth; larger ones shed bark in plates. Trunk bark splits into narrow flat ridges that break into shreddy scales. Buds are not described.","leaf":"Scale leaves 1-3 mm long in opposite pairs, tight to the twig or slightly spreading; light to dark green, from plain green to silvery-blue between trees. Young plants have longer whip leaves, 3-6 mm.","hardiness":"Zone 3 (Gymnosperm Database); tolerates about -35 F (FEIS)","sources":[["USDA Forest Service: Fire Effects Information System, Juniperus scopulorum","https://www.fs.usda.gov/database/feis/plants/tree/junsco/all.html"],["Gymnosperm Database: Juniperus scopulorum (Rocky Mountain juniper)","https://www.conifers.org/cu/Juniperus_scopulorum.php"],["Montana State Univ. Extension: Cedar-apple rust","https://www.montana.edu/extension/Full_HTML_Pubs/a-guide-to-pests-problems-and-identification-of-ornamental-shrubs-and-trees-in-montana/diseases/cedar-apple-rust.html"]],"basis":"sourced","note":"Wild trees grow slower than the sheet's 12 in/yr: FEIS gives about 13-14 ft at age 40. The inventory line 'Juniper (variety)' is not confirmed to be this species.","reviewed_on":"2026-10-17"},{"id":"fir-grand","group":"Evergreen","type":"Fir","kind":"species","name":"Grand fir","aliases":["Grand Fir","Abies grandis"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[16],"tagline":"Fast tall fir; flat notched needles, orange scent","summary":"Grand fir (Abies grandis) is a very tall, fast-growing fir native to northern and central Idaho. Its flat needles give off an orange scent when crushed. It likes moister ground than a dry site offers.","appearance":"Conical, with slightly drooping branches and a long, narrow crown of dense foliage that can turn rounded or flat-topped with age. Often 130-165 ft inland and 140-200 ft on the coast, with a trunk 3-4 ft thick.","flavor_use":"Grown for Christmas trees and as an ornamental; a timber tree in the wild. Does best on moist, deep soils and is only moderately drought tolerant, so a dry site likely needs watering. Prone to heart and root rot fungi, budworm, tussock moth and bark beetles.","uses":["ornamental","timber"],"ripening":null,"ripening_note":"Cones fall apart on the tree as the seeds ripen","id_cues":"Flat needles in two ranks, of alternating lengths, tips notched, orange-scented when crushed. Upright cones break apart on the tree. Young bark is gray-green with resin blisters; buds are large and pitchy. Look-alikes include subalpine, Pacific silver and noble firs.","habit":"Fast for a fir: seedlings have added up to 3 ft a year, and 140 ft in about 50 years is reported on coastal sites. Crown width varies from narrow to wide. Deep taproot plus wide-spreading roots; grows from seed only, with no sprouting.","bark":"Young bark gray-green with resin blisters. Older bark is 2-3 in thick, mottled brown-gray and grooved into flat ridges; the layer beneath is purple-red. Twigs are stiff and olive to red-brown; buds are big, rounded and coated in pitch, usually in groups of 3 or more at the tip.","leaf":"Needles are flat, 3/4 to 2 in long, set in two flat rows with long and short ones alternating; glossy dark yellow-green on top with two white bands underneath; tips notched or blunt. Crushed needles smell of citrus.","hardiness":"Zone 4 (Oregon State)","sources":[["Oregon State Univ. Landscape Plants: Abies grandis (Grand Fir)","https://landscapeplants.oregonstate.edu/plants/abies-grandis"],["Virginia Tech Dendrology: grand fir (Abies grandis)","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=183"],["USDA Forest Service: Fire Effects Information System, Abies grandis","https://www.fs.usda.gov/database/feis/plants/tree/abigra/all.html"]],"basis":"sourced","note":"Sheet says zone 6; Oregon State says zone 4. FEIS: inland it is most common where rainfall is 25+ in a year and does best on moist valley bottoms, so a dry site likely needs irrigation. No page I read covers wind.","reviewed_on":"2026-10-17"},{"id":"fir-fraser","group":"Evergreen","type":"Fir","kind":"species","name":"Fraser fir","aliases":["Fraser Fir","Abies fraseri"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[17],"tagline":"Christmas-tree fir; cool, moist, acid soil; heat-shy","summary":"Fraser fir (Abies fraseri) is a narrow-crowned fir from high southern Appalachian peaks, grown as a Christmas tree. It wants cool, wet mountain conditions, so a dry inland site is a poor match.","appearance":"Narrow cone to spire-shaped crown with branches at right angles to the trunk. About 30-55 ft tall in garden references and 50-60 ft in the wild; an 87 ft tree is on record. Evergreen.","flavor_use":"Christmas tree and ornamental. Sources call for cool, damp but well-drained acidic loam; heat is a problem, the roots are very shallow and windthrow is a known risk. Balsam woolly adelgid seriously threatens wild stands; root rots occur. Hot, dry, windy ground is a poor fit.","uses":["ornamental"],"ripening":null,"ripening_note":"Good cone crops come about every other year, starting near age 15","id_cues":"Flat, flexible needles with a notched or rounded tip, shiny dark green above. Dark purple cones whose long bracts curl down over the scales; balsam fir, the look-alike, has short bracts that stay tucked under the scales. Smooth gray bark with resin blisters.","habit":"Very shallow rooted and prone to windthrow. Shade tolerant, but does best with full sun: about 8 ft after 11 years in the open, only 2-3 ft in 20 years under dense shade. Seeds are wind-dispersed; layering from low branches is minor.","bark":"Thin gray bark, smooth when young apart from resin blisters; old trunks grow small reddish scales that later turn gray. Twigs pale yellow-brown with reddish fuzz; buds small, conical, light brown and resinous.","leaf":"Flat, flexible needles about 1/2 to 1 in long, in two ranks on lower branches and spiraled elsewhere. Tip slightly notched or rounded; shiny dark green above, stomatal rows beneath; strong turpentine-like scent.","hardiness":"Zone 4 (Gymnosperm Database)","sources":[["NC State Extension: Abies fraseri (Fraser fir), Plant Toolbox","https://plants.ces.ncsu.edu/plants/abies-fraseri/"],["USDA Forest Service: Fire Effects Information System, Abies fraseri","https://www.fs.usda.gov/database/feis/plants/tree/abifra/all.html"],["Gymnosperm Database: Abies fraseri","https://www.conifers.org/pi/Abies_fraseri.php"]],"basis":"sourced","note":"Sheet says zones 4 to 7; Gymnosperm Database agrees (zone 4). Wild stands get about 33-100 in of rain a year in cool, foggy, acid-soil mountains and NC State says heat is not tolerated, so a hot, dry site is a poor fit.","reviewed_on":"2026-10-17"},{"id":"ash","group":"Shade tree","type":"Ash","kind":"species","name":"Green ash (ash)","aliases":["Ash","Green Ash","Fraxinus pennsylvanica"],"inventory_rows":[116],"purchase_rows":[],"seed_rows":[7],"tagline":"Tough shade tree; paired compound leaves; diamond bark","summary":"Large shade and windbreak tree from eastern and central North America, with paired compound leaves and diamond-patterned bark. Tough on dry, high-pH ground, but emerald ash borer makes new plantings a gamble.","appearance":"Mature size is 50 to 70 ft high with a 35 to 50 ft spread. Pyramidal when young, becoming a rounded, irregular crown with age. Leaflets are bright green and go yellow in autumn.","flavor_use":"Shade and windbreak tree that tolerates drought, wind and soils with a high pH; seeds feed wildlife. Watch for emerald ash borer, lilac borer on stressed trees, brittle limbs in wind or ice, and messy seed drop from female trees.","uses":["shade","windbreak","wildlife"],"ripening":null,"ripening_note":"Flowers open as leaves expand in spring; seed clusters hang on female trees into winter","id_cues":"Paired (opposite) leaves with 7 to 9 toothed leaflets, plus gray bark whose crossing ridges outline diamonds. Diamonds are clearest on older trees. Hairiness of leaves and twigs varies between trees, so hairiness alone is a weak cue.","habit":"Pyramidal when young, rounder and irregular with age. Transplants easily and adapts to many soils. Male and female flowers grow on separate trees, so only females make winged seeds. Sun-loving but accepts some shade.","bark":"Gray, with an orangey cast on some young trees. Older bark has crossing ridges that outline diamonds. Twigs are fairly stout and gray to brown; the end bud is rust-brown, cone-shaped and fuzzy.","leaf":"Paired and once-compound, about 10 to 12 in long, with 7 to 9 short-stalked, finely toothed leaflets 4 to 6 in long. Bright green, going yellow in autumn.","hardiness":"Zones 3-9 (Utah State Extension)","sources":[["NC State Extension Plant Toolbox: Fraxinus pennsylvanica","https://plants.ces.ncsu.edu/plants/fraxinus-pennsylvanica/"],["Utah State University Extension: Green Ash (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/ash-green"],["University of Idaho Extension: Emerald Ash Borer bulletin 1077","https://www.uidaho.edu/extension/publications/bul-1077"]],"basis":"sourced","note":"UI Extension says Idaho had no reported emerald ash borer sightings (page undated; confirm current status). NC State: the borer can kill ash in 3-5 years, and it advises against adding new green ash.","reviewed_on":"2026-10-17"},{"id":"aspen","group":"Shade tree","type":"Aspen","kind":"species","name":"Quaking aspen (trembling aspen)","aliases":["Trembling","Quaking Aspen","Populus tremuloides","QA"],"inventory_rows":[117],"purchase_rows":[],"seed_rows":[18],"tagline":"White bark; quaking leaves; suckers; short-lived stems","summary":"Native mountain tree with pale bark and round leaves that tremble in light wind. It spreads by root suckers into groves and suits cool, moist, sunny sites.","appearance":"About 50 ft tall with a spread near 30 ft; pyramidal when young, narrowing to a rounded crown. Whitish trunk, yellow-green summer leaves and yellow-to-orange autumn color.","flavor_use":"Grown for white bark and fall color; fast for 10 to 20 years, then slower. Suckers can become a nuisance, and heat or drought stress invites leaf spots, cankers and borers, so it suits cool, moist sites. Very shade intolerant.","uses":["shade","ornamental"],"ripening":null,"ripening_note":"Fall leaves range from yellow to orange","id_cues":"Smooth cream to greenish-white bark, round leaves on long flattened stalks that flutter, and many stems rising in a clump from one root system. Old trunks turn furrowed, so check the leaves on big trees.","habit":"Stems in a grove are usually genetically identical, joined by one root system and spreading by suckers after disturbance. Single stems live about 50 years, though the root system can last far longer. Strongly pyramidal when young.","bark":"Smooth and cream to greenish-white, turning furrowed on old trunks. Twigs are slender, red-brown and hairless; terminal buds are pointed, 1/4 to 1/2 in long, sometimes sticky with resin, with overlapping red-brown scales.","leaf":"Alternate, nearly round to broad-oval, 1.5 to 3 in across, finely toothed with a short point. The long leaf stalk is flattened sideways, so the blade flutters. Yellow-green in summer, yellow to orange in autumn.","hardiness":"Zones 3-7 (Utah State Extension)","sources":[["Utah State University Extension: Quaking Aspen (Forestry tree ID)","https://extension.usu.edu/forestry/tree-identification/poplar-aspen/quaking-aspen"],["NC State Extension Plant Toolbox: Populus tremuloides","https://plants.ces.ncsu.edu/plants/populus-tremuloides/"]],"basis":"sourced","note":"Utah State says aspen struggles in hot, dry lower valleys and should rarely be planted there. Clumps are all one sex (NC State). Owner's sheet says zones 1-7; Utah State says 3-7.","reviewed_on":"2026-10-17"},{"id":"sugar-maple","group":"Shade tree","type":"Maple","kind":"species","name":"Sugar maple","aliases":["Sugar","Sgr Mpl","Acer saccharum"],"inventory_rows":[118],"purchase_rows":[],"tagline":"Big maple; 5 rounded lobes; syrup; dislikes high pH","summary":"Large eastern shade tree with five-lobed, mostly smooth-edged leaves and bright fall color, tapped for maple syrup. Utah State steers it away from scorching, dry spots and strongly alkaline soil.","appearance":"Medium-sized to tall, reaching about 100 ft, with a very dense, oval crown. Bright yellow-green summer leaves turn bright red, orange or yellow in fall. Paired, horseshoe-shaped winged seeds hang in clusters and ripen in fall.","flavor_use":"Shade and ornamental tree, noted for syrup: most maple sap needs about 43 gal boiled down per gal of syrup. Utah State says to keep it off scorching, dry spots and strongly alkaline soil.","uses":["shade","syrup","ornamental"],"ripening":null,"ripening_note":"Sap flows when nights fall to the 20s F and days reach the 40s F; tap only trees 12 in or more across","id_cues":"Paired leaves with 5 rounded lobes and smooth to wavy edges; sharp brown buds on brown, shiny twigs; gray bark furrowed into long irregular plates on older trees. Red maple has round red buds and red twigs; black and Norway maples also resemble it.","habit":"Shade tolerant, with a very dense, oval crown. Small yellow-green flowers dangle in clusters as the leaves emerge, or a little earlier, in early spring. Trees under 12 in across are too small to tap.","bark":"Gray to brown. Older trunks split into long, thick, uneven plates or ridges that may curl outward and can look scaly. Twigs are slender, brown to red-brown and shiny; buds are brown and sharp-pointed.","leaf":"Paired and simple, roughly 3 to 6 in across, palmately 5-lobed with rounded lobe tips and edges smooth or sometimes wavy-toothed. Yellow-green on top, lighter underneath; leaf stalk usually shorter than the blade. Fall color bright red, orange or yellow.","hardiness":"Zones 4-8 (Utah State TreeBrowser)","sources":[["Utah State University Extension: Sugar Maple (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/maple-sugar"],["Virginia Tech Dendrology: Sugar Maple (Acer saccharum)","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=2"],["University of New Hampshire Extension: Maple Sugaring Tips for Beginners","https://extension.unh.edu/resource/maple-sugaring-tips-beginners-and-backyard-maple-sugar-producers"]],"basis":"sourced","note":"Sources differ on bark color (gray vs brown). Utah State says it can work in Utah if scorching, dry spots and strongly alkaline soil are avoided; check soil pH before planting more.","reviewed_on":"2026-10-17"},{"id":"maple","group":"Shade tree","type":"Maple","kind":"genus","name":"Maple (species not recorded)","aliases":["Maple"],"inventory_rows":[119],"purchase_rows":[],"tagline":"Unknown maple; count leaf lobes, check bark and size","summary":"Genus-level profile for one planted maple of unrecorded species. Lobe count, bark and size separate the likely candidates from the owner's lists: sugar, Japanese and trident maple.","appearance":"Size is a quick clue: Japanese maple stays a small tree, trident is small to medium, and sugar maple grows large. Fall color: sugar bright red, orange or yellow; Japanese yellow to red or purple; trident very late.","flavor_use":"Mostly ornamental or shade trees; sugar maple sap makes syrup. Japanese maple dislikes cold and intense heat and wants shade in the afternoon plus shelter from wind. Keep sugar maple off scorching, dry spots and strongly alkaline soil.","uses":["ornamental","shade","syrup"],"ripening":null,"ripening_note":"Fall color: sugar bright red to yellow, Japanese varies by cultivar, trident turns very late","id_cues":"These maples all have paired (opposite) leaves. Trident: 3 forward-pointing lobes. Japanese: deeply 5-9 lobed, fine double teeth. Sugar: 5 rounded lobes, smooth edges. Norway: 5 pointed lobes, milky sap in a snapped leaf stalk. Red: usually 3 toothed lobes, red twigs. Size and bark help too.","habit":"Japanese maple is a small tree that wants shade in the afternoon and shelter from wind. Trident is a small to medium tree, fairly drought resistant but shade intolerant. Sugar maple is a large, shade-tolerant tree with a well-formed canopy.","bark":"Sugar: gray, deeply furrowed into long uneven plates on older trees. Trident: scaly in gray, orange and brown once the tree is a few years old. Japanese: green to purplish-red when young, grayish later. Norway: smooth gray-brown, furrowed with age. Red: smooth light gray, then long scaly plates.","leaf":"Sugar: 3 to 5 in across, 5 lobes with rounded tips, edges smooth or wavy. Trident: 1.5 to 3 in wide, 3 shiny forward-pointing lobes with a few tiny teeth. Japanese: 2 to 5 in long, 5 to 9 deep lobes, doubly toothed, green to purplish-red by cultivar.","hardiness":"Sugar maple zones 4-8; Japanese 5-8; trident 5-9 (Utah State TreeBrowser)","sources":[["Utah State University Extension: Sugar Maple (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/maple-sugar"],["Utah State University Extension: Japanese Maple (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/maple-japanese"],["Utah State University Extension: Trident Maple (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/maple-trident"],["Utah State University Extension: Norway Maple (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/maple-norway"],["Utah State University Extension: Red Maple (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/maple-red"]],"basis":"sourced","note":"Species not recorded. Japanese and trident maple are rated zone 5 and warmer, sugar maple zone 4 and warmer. Norway maple's milky leaf-stalk sap can fade late in summer. Species profiles for sugar, Japanese, and trident maple describe each in full.","reviewed_on":"2026-10-17"},{"id":"oak","group":"Shade tree","type":"Oak","kind":"genus","name":"Oak (various)","aliases":["Oak various","Quercus","Northern red oak","White oak"],"inventory_rows":[120],"purchase_rows":[],"tagline":"Pointed lobes = red oak; rounded = white or bur oak","summary":"Genus-level profile for 8 oaks of mixed or unrecorded type. Leaf lobe shape and acorn timing separate red-type oaks from white-type oaks; bur oak copes with dry, windy, high-pH ground better than red oak.","appearance":"Large, broad-crowned shade trees. Northern red oak reaches 50 to 75 ft tall and as wide; white and bur oak also get fairly large with wide canopies. Fall color: red oak reddish-brown, white oak brown to dark red, bur oak yellow to brown.","flavor_use":"Shade and wildlife trees; acorns feed deer, squirrels and birds, though the drop is a nuisance for some. Wood is used for lumber and furniture. Bur oak copes with high soil pH, dry spells, heat, cold and wind; red oak yellows (chlorosis) in soil that is not acidic enough and can get oak wilt.","uses":["shade","wildlife","timber"],"ripening":null,"ripening_note":"Acorns mature in one season on white and bur oak but take two seasons on northern red oak","id_cues":"Check lobes first: pointed, bristle-tipped lobes mean red oak type; rounded lobes mean white type (white oak, bur oak). Acorns mature in 2 seasons on red oak, 1 on white and bur; bur oak cups are fringed and cover half or more of the nut. Bark is a weaker clue: bur oak is furrowed like red oak.","habit":"Large trees with broad crowns; white and bur oak are long-lived with a medium growth rate, northern red oak moderate to fast. Bur oak grows on dry uplands and is drought tolerant; red oak prefers acidic, well-drained soil.","bark":"Red oak: smooth when young, later broad flat-topped ridges separated by shallow furrows. White oak: light ash-gray, chunky vertical blocks on young trees, scaly plates on old ones. Bur oak: thick, gray-brown bark with deep furrows and ridges; twigs often have corky ridges.","leaf":"All alternate and simple. Red oak: 8 to 12 in long, with 7 to 11 pointed, bristle-tipped lobes; green above, grayish-white below. White oak: 5 to 9 in, with 7 to 9 smoothly rounded lobes. Bur oak: 6 to 10 in, with 5 to 9 smoothly rounded lobes, dark green above and paler, finely hairy below.","hardiness":"Bur oak zones 2-8; white oak zones 3-9 (Utah State TreeBrowser)","sources":[["NC State Extension Plant Toolbox: Quercus rubra (northern red oak)","https://plants.ces.ncsu.edu/plants/quercus-rubra/"],["Utah State University Extension: Bur Oak (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/oak-bur"],["Utah State University Extension: White Oak (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/oak-white"]],"basis":"sourced","note":"Owner's sheet lists northern red oak at zones 3-8; the listed pages give no zone for it. Utah State rates bur oak a good fit for most of Utah (high pH, drought, cold, wind); no Idaho-specific page was checked. Species profiles for northern red oak and white oak describe each in full.","reviewed_on":"2026-10-17"},{"id":"dawn-redwood","group":"Shade tree","type":"Deciduous conifer","kind":"species","name":"Dawn redwood","aliases":["Dawn Redwood","Metasequoia glyptostroboides"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[5],"tagline":"Deciduous conifer; red fluted bark; wants moist soil","summary":"Fast, cone-shaped deciduous conifer from China with feathery needles that turn bronze and drop in fall. A big specimen or shade tree for moist ground; a poor match for dry, alkaline soil.","appearance":"Conical, uniform crown about 70 to 100 ft tall and 25 ft wide, and old trees can pass 100 ft. Foliage is light green in spring, darker in summer, then russet to pinkish bronze in fall; the tree is leafless in winter.","flavor_use":"Specimen or lawn shade tree for big spaces; transplants easily. UConn warns it struggles in dry soil or soil with a high pH, and spider mites show up when it is dry, so it needs steady moisture. Early fall frosts hurt late growth, so avoid frost pockets. Japanese beetles feed on the leaves.","uses":["shade","ornamental"],"ripening":null,"ripening_note":"Foliage turns russet to bronze and drops, twiglets and all, in fall; cones mature late fall","id_cues":"Flat needles in opposite pairs on feathery twiglets that drop whole in fall; buds are opposite on the persistent twigs; trunk is buttressed and fluted with shredded red-brown bark. Baldcypress looks similar, but UConn says the opposite buds tell them apart.","habit":"Very fast, with a straight single trunk and a narrow cone-shaped crown; branches spread out horizontally. Wants full sun and moist, well-drained soil on the acid side. It grows late into fall, so early frosts can injure new growth.","bark":"Reddish brown and stringy, shedding in long rope-like strips and forming an irregular fluted pattern; the trunk base flares into buttresses and looks braided. Persistent twigs are thin and pale reddish brown with small paired buds.","leaf":"Flat, linear needles about 1/2 to 1 in long, opposite and in two ranks along branchlets that look like small feathery compound leaves. Light to bright green; branchlets and needles fall together in autumn.","hardiness":"Zone 4 (UConn Plant Database)","sources":[["University of Connecticut: Plant Database - Metasequoia glyptostroboides (Dawn Redwood)","https://plantdatabase.uconn.edu/detail.php?pid=289"],["Virginia Tech Dendrology: dawn redwood (Metasequoia glyptostroboides)","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=98"],["The Morton Arboretum: Dawn redwood","https://mortonarb.org/plant-and-protect/trees-and-plants/dawn-redwood/"]],"basis":"sourced","note":"Sheet says zones 4b to 8; UConn gives zone 4 only. UConn and Morton both favor moist, slightly acid soil, and UConn warns it struggles on dry or alkaline ground, which describes this site.","reviewed_on":"2026-10-17"},{"id":"larch-western","group":"Shade tree","type":"Larch (deciduous conifer)","kind":"species","name":"Western larch","aliases":["Western Larch","Larix occidentalis"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[14],"tagline":"Deciduous conifer; needle tufts; gold fall; plated bark","summary":"Native Inland Northwest conifer that turns gold and drops its soft needles in fall, with very thick bark on old trunks. It comes from cool, moist mountain sites, so a dry, alkaline site is a stretch.","appearance":"Typically 100 to 180 ft tall, some over 200 ft, on a very straight trunk often bare of branches for much of its length, topped by a short, airy, pyramid-shaped crown. Golden in fall, then bare. Spread is not given in the sources (sheet: 25 to 30 ft).","flavor_use":"Large tree for deep soil in full sun; Oregon State says it soon outgrows a typical garden. Roots anchor well against wind, but branches are brittle. Low rainfall limits its native range at the low end, so on a dry site plan to irrigate (inference). No salt tolerance.","uses":["shade","ornamental"],"ripening":null,"ripening_note":"Needles open yellow-green in spring, turn gold by autumn, then drop","id_cues":"A conifer that drops its needles: soft needles in tufts of 15 to 30 on short spur shoots, golden in fall; thick, plated, reddish bark with age; cone bracts stick out past the scales. Virginia Tech lists tamarack, subalpine larch and Dunkeld larch as look-alikes, so tufts alone are a weak cue.","habit":"Fast-growing and long-lived, and very shade-intolerant, so it needs open sun. Roots are deep and spreading. In a stand the lower third to half of the trunk is bare; open-grown trees keep branches low. Limbs are thick yet brittle.","bark":"Young trees have thin, scaly, gray-brown bark; old trunks develop very thick bark with deep furrows and big flaky plates, coloring from yellowish to red-brown. Twigs are yellow-brown and crowded with short spur shoots; buds are tiny, rounded and smooth.","leaf":"Soft, slender needles about 1 to 2 in long, flat to triangular in cross-section, borne alone on the current year's growth but bundled 15 to 30 together on the short spur shoots of older wood. Light yellow-green in spring, glossy pale green in summer, gold by autumn.","hardiness":"Zone 4 (Oregon State Landscape Plants)","sources":[["Virginia Tech Dendrology: western larch (Larix occidentalis)","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=214"],["Oregon State University Landscape Plants: Larix occidentalis","https://landscapeplants.oregonstate.edu/plants/larix-occidentalis"],["USDA Forest Service: Fire Effects Information System, Larix occidentalis","https://www.fs.usda.gov/database/feis/plants/tree/larocc/all.html"]],"basis":"sourced","note":"Sheet says medium growth (12 in/yr); FEIS and Oregon State call it fast. FEIS: low rainfall limits its range and soil pH 6 to 7 suits it, so dry alkaline ground is uncertain (inference).","reviewed_on":"2026-10-17"},{"id":"planetree-monumental","group":"Shade tree","type":"Planetree","kind":"species","name":"Monumental planetree (London planetree)","aliases":["Monumental Planetree","Platanus x acerifolia","MP"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[25],"tagline":"Pyramidal planetree; peeling bark; maple-like leaves","summary":"Monumental looks like a trade name for the London planetree 'Morton Naper': a broad pyramidal shade tree with peeling cream-white bark and big maple-like leaves. Listed hardy to zone 4; takes high pH and some drought.","appearance":"Listed at about 50 to 70 ft tall and 33 to 49 ft wide (NVK gives metres), with a strong central leader and dense, broad pyramidal crown. The plain species reaches 70 to 100 ft and is more open and wide-spreading. Leaves are green in summer and turn yellow in fall.","flavor_use":"Shade or specimen tree for a large yard; NVK names the peeling bark as its main feature. Morton says the species tolerates drought and high pH but needs watering in its first years, and young trees can frost-crack. Messy: drops leaves, twigs and seed balls. Canker stain and anthracnose can occur.","uses":["shade","ornamental"],"ripening":null,"ripening_note":"Flowers open in early spring as the leaves emerge; leaves turn yellow in fall; seed balls break up over winter","id_cues":"Alternate, maple-like leaves with 3 to 5 lobes; bark flakes off in patches to show cream, green and gray; round seed balls hang in pairs or threes, while American sycamore holds them singly. Leaf shape alone is a weak cue, since it mimics a maple's.","habit":"Strong central leader with a dense, broad pyramidal crown; listed as fast growing. The plain species develops a looser, uneven crown that spreads wide with age. Male and female flowers are separate balls on the same tree.","bark":"Gray-brown to tan outer bark flakes off in scales, leaving blotches of cream, white, gray and green beneath; the upper trunk looks nearly white, and NVK lists white winter bark.","leaf":"Simple, alternate and leathery, with 3 to 5 maple-like lobes and a width of 6 to 7 in; edges are nearly smooth. Bright green above, paler below. NVK calls the leaves coarse and deeply lobed. They turn yellow to yellow-brown in fall.","hardiness":"Zone 4 for this selection (NVK); species 5-8 (Illinois Extension)","sources":[["NVK Nurseries: Platanus x acerifolia 'Monumental' (Morton Naper)","https://www.nvknurseries.com/plant/Platanus-x%20acerifolia-Monumental-Morton-Naper"],["The Morton Arboretum: London planetree (Platanus x acerifolia)","https://mortonarb.org/plant-and-protect/trees-and-plants/london-planetree/"],["University of Illinois Extension: Selecting Trees - London Planetree","https://web.extension.illinois.edu/treeselector/detail_plant.cfm?PlantID=247"]],"basis":"sourced","note":"NVK lists Monumental with 'Morton Naper' in brackets, matching the sheet note, so it looks like a trade name for that selection. Morton's page names 'Morton Circle' and 'Morton Euclid' but not Naper, so the breeder is unconfirmed.","reviewed_on":"2026-10-17"},{"id":"kentucky-coffeetree","group":"Shade tree","type":"Coffeetree","kind":"species","name":"Kentucky coffeetree","aliases":["Kentucky Coffee Tree","Gymnocladus dioicus"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[21],"tagline":"Late-leafing shade tree; very large compound leaves; toxic","summary":"Large native shade tree with very large twice-compound leaves, stout twigs and flat pods on female trees. Tolerates drought and high pH, but the foliage, seeds and pulp are toxic to people, pets and livestock.","appearance":"Reaches roughly 60 to 80 ft in height and 40 to 55 ft across; the crown is oval and open, sometimes irregular. Leaves come out late in spring, pinkish bronze at first, then blue-green, and turn yellow in fall. The bare winter tree looks coarse, and female trees keep dark pods into winter.","flavor_use":"Shade tree for large lawns and parks that tolerates drought, pollution and occasional flooding. NC State rates the leaves, seeds and pulp as toxic to livestock, people and pets, so keep animals and children away from pods and fallen leaves. Male trees are seedless, which avoids pod litter.","uses":["shade","ornamental"],"ripening":null,"ripening_note":"Leaf-out comes in late spring and leaf drop by early fall; pods are showing by fall and stay on female trees through winter","id_cues":"Very large twice-compound leaves up to 3 ft long, appearing late; very stout zigzag twigs with no terminal bud and sunken side buds; deeply furrowed bark with scaly ridges; flat leathery pods on female trees. Compound leaves alone are not unique, so use twigs and pods too.","habit":"Male and female flowers grow on separate trees, and only females make pods. Fast when young, then moderate to slow. Needs full sun (shade intolerant); tolerates many soils but prefers deep, moist ones.","bark":"Dull gray-brown, split by deep furrows into scaly ridges; older trunks show curved scales, young branches are smoother and brown to gray. Twigs are very thick, brown and zigzag, with a broad salmon-pink pith and sunken buds.","leaf":"Alternate and twice-compound, to about 3 ft by 2 ft, with 5-9 leaflet pairs; each oval leaflet is untoothed, blue-green and about 1.5 in long. Emerges pinkish bronze in late spring and turns a mild yellow in fall.","hardiness":"Zones 3-8 (Utah State TreeBrowser)","sources":[["NC State Extension Plant Toolbox: Gymnocladus dioicus","https://plants.ces.ncsu.edu/plants/gymnocladus-dioicus/"],["Utah State University Extension: Kentucky Coffeetree (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/coffeetree-kentucky"],["The Morton Arboretum: Kentucky coffeetree","https://mortonarb.org/plant-and-protect/trees-and-plants/kentucky-coffeetree/"]],"basis":"sourced","note":"NC State flags leaves, seeds and pulp as toxic to livestock, people and pets; Morton names leaves and seeds. Roasted-seed coffee is mentioned, but treat every part as unsafe to eat. Sheet growth is 12-24 in/yr; NC State: fast when young.","reviewed_on":"2026-10-17"},{"id":"beech-american","group":"Shade tree","type":"Beech","kind":"species","name":"American beech","aliases":["American Beech","Fagus grandifolia"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[8],"tagline":"Smooth gray bark; slim sharp buds; holds winter leaves","summary":"Large eastern shade tree with smooth gray bark, sharply toothed leaves that cling in winter, and edible nuts. It wants moist, acid, well-drained soil, so dry alkaline ground is a stretch.","appearance":"Large, low-branched tree, often 50 to 80 ft tall and 40 to 80 ft wide, with a dense, rounded to oval crown of wide-spreading limbs. Summer foliage is dark green and fall color is golden bronze.","flavor_use":"Shade or woodland tree; wildlife eat the nuts, and people can eat small amounts (NC State: large servings may upset the stomach). Wants moist, acid, well-drained soil; Utah State rates drought and alkaline tolerance only medium. Beech bark disease (scale plus fungus) has killed millions of beeches in New England.","uses":["shade","nuts","wildlife"],"ripening":null,"ripening_note":"Flowers open with the leaves in spring; nuts ripen in fall; leaves turn golden bronze and many hang on into winter.","id_cues":"Smooth gray trunk, slim sharp brown buds 3/4 to 1 in long, sharply toothed leaves with 11 to 15 pairs of straight parallel veins, and dead leaves clinging all winter. Nuts sit in prickly husks. European beech has smaller leaves with fewer veins.","habit":"Slow to moderately slow growth, faster when young. Dense, low-branched, shade-tolerant crown. Sends up root suckers from its surface roots, so a whole grove can grow from one tree. Can be hard to transplant; fails in wet or compacted soil.","bark":"Thin, smooth, silvery to pale blue-gray bark that darkens and may mottle with age but stays smooth. Twigs are slender, shiny and slightly zigzag; buds are brown, narrow, sharp-pointed and 3/4 to 1 in long.","leaf":"Simple, alternate, egg-shaped to elongated, 2 to 5 in long, coarsely and sharply toothed with a tapering tip. Dark green and shiny above, paler below, turning golden bronze in fall; some dead leaves hang on over winter.","hardiness":"Zones 3-9 (Utah State and NC State)","sources":[["Utah State University Extension: American Beech (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/beech-american"],["NC State Extension Plant Toolbox: Fagus grandifolia","https://plants.ces.ncsu.edu/plants/fagus-grandifolia/"],["UMass Extension: Beech Bark Disease (landscape fact sheet)","https://www.umass.edu/agriculture-food-environment/landscape/fact-sheets/beech-bark-disease"]],"basis":"sourced","note":"Sheet says zones 4-9 and 12-24 in per year; sources say zones 3-9 and slow to moderately slow growth. The beech bark disease source covers New England; Idaho status was not checked.","reviewed_on":"2026-10-17"},{"id":"yellow-poplar","group":"Shade tree","type":"Tulip tree","kind":"species","name":"Yellow poplar (tulip tree)","aliases":["Yellow Poplar","Tulip poplar","Tuliptree","Liriodendron tulipifera","YP"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[9],"tagline":"Very tall fast tree; 4-lobed leaves; needs steady moisture","summary":"Very tall native tree of the magnolia family despite the poplar name, with four-lobed leaves, tulip-like flowers and cone-like seed heads. Needs room and deep, moist soil.","appearance":"Very large, straight-trunked tree listed at 80 to 120 ft tall and 30 to 60 ft wide (NC State), or about 90 by 50 ft (Virginia Extension), with a pyramidal to oval crown. Leaves turn golden yellow in fall.","flavor_use":"Shade or specimen tree for large open sites; flowers attract hummingbirds and butterflies. Sensitive to heat and drought, shallow-rooted, and weak-wooded in wind or ice, so a poor fit for dry, windy ground unless it gets steady water. Aphids, scale and Verticillium wilt can occur.","uses":["shade","ornamental","wildlife"],"ripening":null,"ripening_note":"Flowers open in late spring; seed clusters turn brown by October and last through winter; leaves turn golden yellow in fall.","id_cues":"Four-lobed leaves with a flat-cut tip, like a tulip outline; duck-bill-shaped buds; twigs that smell spicy when broken; bark with pale furrows in a diamond pattern; upright, cone-like seed heads that last into winter.","habit":"Fast once established, with a straight trunk that may stay limb-free to 80 ft up. Shallow roots, weak wood, and hard to transplant (move small balled plants in spring). Can be coppiced; rabbits chew young buds and bark.","bark":"Smooth, light gray-green on young trees; older bark is gray-brown with flat-topped ridges and pale furrows in a diamond pattern. Twigs are green to reddish-brown with ring-like stipule scars; buds are flattened, duck-bill shaped, up to 1/2 in.","leaf":"Alternate, simple, 3 to 8 in across, with four main lobes, smooth edges and a broad, flat-cut tip; leaf stalk 2 to 4 in. Glossy green above, paler below, golden yellow in fall; may yellow and drop early in drought.","hardiness":"Zones 4-9 (NC State); Virginia Extension says 5-9","sources":[["NC State Extension Plant Toolbox: Liriodendron tulipifera","https://plants.ces.ncsu.edu/plants/liriodendron-tulipifera/"],["Morton Arboretum: Tuliptree (Liriodendron tulipifera)","https://mortonarb.org/plant-and-protect/trees-and-plants/tuliptree/"],["Virginia Cooperative Extension: Tuliptree (Liriodendron tulipifera)","https://www.pubs.ext.vt.edu/2901/2901-1074/2901-1074.html"]],"basis":"sourced","note":"Sheet says zones 4-9 and a 30-50 year life; the pages I opened give no lifespan. Sources differ on alkaline soil: Morton says it tolerates some, Virginia Extension lists soil pH 3.7 to 6.8.","reviewed_on":"2026-10-17"},{"id":"elm-american","group":"Shade tree","type":"Elm","kind":"species","name":"American elm","aliases":["American Elm","Ulmus americana"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[10],"tagline":"Vase-shaped shade tree; lopsided leaves; Dutch elm risk","summary":"Large, fast-growing native shade tree with a vase shape, doubly toothed leaves and ridged bark. Copes with dry, windy, alkaline ground, but Dutch elm disease makes ordinary seedlings a gamble.","appearance":"Large vase- or urn-shaped tree, 60 to 80 ft tall and 30 to 60 ft wide, with arching limbs. In the open the trunk often forks low; in a dense stand the crown is narrow on a long clear trunk. Fall color is soft yellow.","flavor_use":"Dense-shade tree for large sites, with food and nesting value for wildlife; Utah State rates drought and alkaline tolerance high, and Morton says it copes with heat and wind. Dutch elm disease is fatal with no cure; elm yellows and Verticillium wilt also occur.","uses":["shade","wildlife"],"ripening":null,"ripening_note":"Small flowers open before the leaves in late winter to early spring; winged seeds ripen in spring; leaves turn yellow in fall.","id_cues":"Doubly toothed leaves with a lopsided base on zigzag twigs with no end bud; vase-shaped crown; dark gray bark with flat braided ridges, and broken bark shows light and dark layers. Hybrid elms can look alike, so no single cue is certain.","habit":"Rapid growth into a vase shape, but short-lived in practice because of disease (Utah State rates longevity low). Fibrous roots transplant easily. Roots of nearby elms can graft together and pass Dutch elm disease between trees.","bark":"Ash-gray to dark gray, mixed with black on old trees, with flat braided ridges and diamond-shaped furrows; very old bark can turn rough and patternless. Twigs are slender, smooth, brown and zigzag; buds are oval, chestnut-brown, about 1/4 in.","leaf":"Alternate, simple, oval to elliptic, 4 to 6 in long and 1 to 3 in wide, with doubly toothed edges, a pointed tip and an uneven base. Dark green and slightly rough above, paler and sometimes hairy below; soft yellow in fall.","hardiness":"Zones 2-9 (Utah State); NC State lists 3-9","sources":[["Utah State University Extension: American or White Elm (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/elm-american-white"],["NC State Extension Plant Toolbox: Ulmus americana","https://plants.ces.ncsu.edu/plants/ulmus-americana/"],["Morton Arboretum: American elm (Ulmus americana)","https://mortonarb.org/plant-and-protect/trees-and-plants/american-elm/"]],"basis":"sourced","note":"Sheet says zones 4-9; sources say 2-9 or 3-9. Plain seedlings are not named cultivars, so assume Dutch elm risk. Morton rates Valley Forge and New Harmony strongly resistant, Princeton good; Utah State doubts long-term proof.","reviewed_on":"2026-10-17"},{"id":"hackberry-common","group":"Shade tree","type":"Hackberry","kind":"species","name":"Common hackberry","aliases":["Common Hackberry","Celtis occidentalis"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[11],"tagline":"Tough shade tree; warty corky bark; 3-vein uneven leaves","summary":"Tough, long-lived shade tree with warty, corky bark and leaves with an uneven base. Utah State rates it high for drought and alkaline soil and notes it is often used in windbreaks.","appearance":"Medium to large tree, usually 40 to 60 ft tall and wide (NC State says up to 130 ft in ideal conditions), with a straight trunk, arching branches and a broad, spreading crown. Fall color is a plain yellow.","flavor_use":"Shade, street and windbreak tree for dry, windy, high-pH ground; birds eat the dark fruit and people can eat the thin, sweet flesh. Witches' broom and leaf nipple galls look untidy but do little harm. NC State lists it as immune to Dutch elm disease.","uses":["shade","windbreak","wildlife","fresh"],"ripening":null,"ripening_note":"Fruit ripens in September to October and may hang on into winter; fall color is a plain yellow.","id_cues":"Gray bark with corky warts and ridges; leaves with three distinct veins from an uneven base and coarse teeth from mid-leaf to the tip; zigzag twigs with no end bud; round purple fruit; nipple galls. Look-alikes are sugarberry and elms.","habit":"Medium-fast to rapid growth, long-lived. Straight central trunk, arching branches, wide crown. Transplants easily and takes many soils and wind, but not maritime exposure. Wood is heavy but soft and weak, and decays quickly when wet.","bark":"Smooth gray-brown when young, soon forming corky warts that grow into rough corky ridges; smooth limbs can resemble beech. Twigs slender, zigzag, green to reddish-brown with pale dots (lenticels); side buds small and pressed to the twig.","leaf":"Alternate, simple, egg- to lance-shaped, 2 to 5 in long, with a long pointed tip, coarse teeth from mid-leaf to tip, an uneven base and three main veins from the base. Green, sometimes rough above; plain yellow in fall; may carry nipple galls.","hardiness":"Zones 2-9 (Utah State); NC State lists 3-9","sources":[["Utah State University Extension: Common Hackberry (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/hackberry-common"],["NC State Extension Plant Toolbox: Celtis occidentalis","https://plants.ces.ncsu.edu/plants/celtis-occidentalis/"],["Virginia Tech Dendrology: Hackberry (Celtis occidentalis) fact sheet","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=26"]],"basis":"sourced","note":"Sheet says zones 3-9; Utah State says 2-9, NC State 3-9. Growth is medium-fast (Utah State) to rapid (NC State). NC State mentions Asian woolly hackberry aphid and frequent mix-ups with sugarberry.","reviewed_on":"2026-10-17"},{"id":"maple-japanese","group":"Shade tree","type":"Maple","kind":"species","name":"Japanese maple","aliases":["Acer Japanese Maple","Acer palmatum"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[2],"tagline":"Small maple; 5-9 cut lobes; zone 5+, needs shelter","summary":"Small Asian maple with deeply lobed opposite leaves, grown for its form and fall color. Rated zone 5 and warmer, so on this site it wants wind shelter and afternoon shade.","appearance":"Usually 15 to 25 ft tall and often multi-stemmed, with a compact, rounded, layered crown of spreading branches. Leaves are green to red or purple in summer depending on the cultivar, then turn yellow, orange, bronze, purple or scarlet in fall.","flavor_use":"Ornamental or specimen tree, also used for bonsai. Wants afternoon shade, shelter from drying wind and even moisture; young leaves are frost-tender, and too much sun, wind or dry weather can scorch them. Seeds itself freely and is rated invasive in Virginia and D.C.; only mildly deer resistant.","uses":["ornamental"],"ripening":null,"ripening_note":"Fall color runs yellow to red; winged seeds are ripe by early fall","id_cues":"Opposite leaves cut into 5 to 9 pointed, toothed lobes; thin hairless twigs, green to red and often with a pale bloom; tiny buds tucked under the leaf-stalk base, often paired at the tip; winged seeds curve inward. Leaf color varies by cultivar, so color is a weak cue.","habit":"Small multi-stemmed tree or large shrub, slow to moderate growth, form very variable. Named forms are mostly grafted and plain seedlings differ from them, so seed-grown trees vary and do not reliably match a cultivar.","bark":"Young bark is green to reddish-purple, turning gray with age. Twigs are thin, hairless and green to bright red, often with a pale bloom. Buds are small, green or red, and hidden beneath the leaf-stalk base.","leaf":"Opposite, simple, 2 to 5 in long, cut into 5 to 9 pointed lobes (usually 5 to 7) with double-toothed edges and some hairs in the vein angles beneath. Green in the typical form, red or purple in some cultivars; fall color yellow, orange, scarlet or bronze.","hardiness":"Zones 5-8 (Utah State); Oregon State says hardy to zone 5","sources":[["Utah State University Extension: Japanese Maple (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/maple-japanese"],["NC State Extension Plant Toolbox: Acer palmatum","https://plants.ces.ncsu.edu/plants/acer-palmatum/"],["Oregon State University Landscape Plants: Acer palmatum","https://landscapeplants.oregonstate.edu/plants/acer-palmatum"]],"basis":"sourced","note":"Rated zone 5 and up by USU and OSU, so zone 4 is outside the range. NC State says not drought tolerant; OSU, quoting Sunset, says plain seedlings take more sun, wind and drought than named forms. No page covers alkaline soil.","reviewed_on":"2026-10-17"},{"id":"maple-trident","group":"Shade tree","type":"Maple","kind":"species","name":"Trident maple","aliases":["Trident Maple","Acer buergerianum"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[3],"tagline":"Small maple; 3 forward lobes; flaking orange bark","summary":"Small East Asian maple with three-lobed leaves and flaking gray, orange and brown bark, much used for bonsai. Reported hardy to zone 5 and drought resistant, but sources favor acid soil.","appearance":"Roughly 20 to 35 ft tall and somewhat narrower, with an oval to rounded crown; often multi-stemmed and low-branched unless pruned to one trunk. Fall color varies from yellow to red and orange and arrives late in the season.","flavor_use":"Small street, shade or bonsai tree. Tolerates drought, wind and salt but wants full sun and well-drained acid soil; no page states how it handles alkaline soil. Watch for verticillium wilt and limb breakage under snow or ice.","uses":["shade","ornamental"],"ripening":null,"ripening_note":"Fall color comes very late; winged seeds mature in fall","id_cues":"Opposite leaves with three forward-pointing triangular lobes and 3 main veins, glossy above; gray, orange and brown flaking bark on older stems; rich brown, pyramid-shaped, 4-angled buds; winged seeds with parallel wings. Flaking takes some years, so young trees lack it.","habit":"Grows at a slow to medium pace into a rounded tree that is often multi-stemmed and low-branched; it can be trained to a single trunk. Transplants easily. Shade intolerant, so it needs full sun.","bark":"Within several years it turns gray, orange and brown and flakes into scales, showing orange-brown inner bark. Twigs are thin; new growth is gray-brown and hairy, turning darker and smooth in the second year. Buds are deep brown, four-angled and pyramid-shaped.","leaf":"Opposite, simple, 3-lobed with forward-pointing lobes and 3 main veins; about 1.5 to 3.5 in wide, edges entire or slightly toothed. Glossy dark green above. Fall tones run from yellow through orange to red, mostly red and orange.","hardiness":"Zones 5-9 (Utah State); Oregon State says hardy to zone 5","sources":[["Utah State University Extension: Trident Maple (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/maple-trident"],["NC State Extension Plant Toolbox: Acer buergerianum","https://plants.ces.ncsu.edu/plants/acer-buergerianum/"],["Oregon State University Landscape Plants: Acer buergerianum","https://landscapeplants.oregonstate.edu/plants/acer-buergerianum"]],"basis":"sourced","note":"USU rates zones 5-9 and OSU hardy to zone 5, so zone 4 is a risk. NC State and OSU both call for well-drained, acid soil. Drought and wind tolerance are reported, but none of the pages covers an alkaline, windy inland site.","reviewed_on":"2026-10-17"},{"id":"oak-northern-red","group":"Shade tree","type":"Oak","kind":"species","name":"Northern red oak","aliases":["Northern Red Oak","Quercus rubra","RO"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[20],"tagline":"Large oak; bristle-tipped lobes; acorns take 2 years","summary":"Large eastern shade oak with pointed, bristle-tipped leaves and red fall color. Moderate to fast growing and rated to zone 4, but iron chlorosis is a risk in high-pH soil.","appearance":"Typically 50 to 75 ft tall and about as wide, though it can reach 90 ft in height, with a rounded, broad crown that branches low in the open. Leaves are green above, paler below, and turn reddish-brown to deep red in fall.","flavor_use":"Shade and specimen tree; acorns feed birds, deer and squirrels, and the wood is used for flooring and furniture. Prefers well-drained, fertile, acidic soil and has higher water needs than bur oak. Oak wilt is a risk and gypsy moth is its worst insect pest. Acorn drop is a nuisance.","uses":["shade","wildlife","timber"],"ripening":null,"ripening_note":"Acorns take two seasons to ripen; leaves turn reddish-brown to deep red in fall","id_cues":"Leaves have 7 to 11 pointed, bristle-tipped lobes cut a third to half way to the midvein; acorns sit in a flat, shallow, beret-like cap and take two seasons; older bark has wide, flat-topped ridges with pale streaks. Black, scarlet and Shumard oaks look similar, so check acorns and bark too.","habit":"Moderate to fast growing for an oak, with a rounded crown carrying low branches in the open. Transplants easily. First acorns come at about 20 to 25 years and heavy crops at 40 to 50. Shade tolerance is intermediate.","bark":"Young trunks are smooth; older ones develop broad, flat-topped ridges with shallow grooves between, brown to almost black, with light gray lengthwise lines giving a ski-track look. Twigs are stout and red-brown; buds are clustered, pointed, red-brown and about 1/4 in long.","leaf":"Alternate, simple, large (5 to 8 in long per USU and VT; NC State says 8 to 12), with 7 to 11 pointed, bristle-tipped lobes. Dull to dark green above, paler or grayish beneath with small hair tufts where veins meet. Fall color reddish-brown to deep red.","hardiness":"Zones 4-8 (Utah State Extension)","sources":[["Utah State University Extension: Northern Red Oak (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/oak-northern-red"],["NC State Extension Plant Toolbox: Quercus rubra","https://plants.ces.ncsu.edu/plants/quercus-rubra/"],["Virginia Tech Dendrology: Northern red oak (Quercus rubra)","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=38"]],"basis":"sourced","note":"Sheet says zones 3-8 and fast growth; USU says zones 4-8 and medium growth. USU and NC State both flag chlorosis in high-pH soil. USU puts its water needs above bur oak's; NC State calls it drought tolerant once established.","reviewed_on":"2026-10-17"},{"id":"oak-white","group":"Shade tree","type":"Oak","kind":"species","name":"White oak","aliases":["White oak","Quercus alba","WO"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[24],"tagline":"Slow big oak; rounded lobes; light scaly bark","summary":"Large, long-lived eastern oak with rounded, bristle-free lobes and pale scaly bark, planted for shade and wildlife. Rated zones 3-9 and handles some drought, but grows slowly.","appearance":"Can reach 135 ft with an 80 ft spread but usually stops at 80 to 100 ft. Pyramidal when young, becoming a broad, rounded crown with age. Leaves are green in summer, then turn brown to dark red in fall.","flavor_use":"Long-lived shade and wildlife tree; wood goes to lumber, furniture, floors and barrels. Acorns are edible to people only once the tannins are washed out, and NC State lists the tree as toxic to horses. Avoid wet or compacted ground and sites near paving; it is hard to transplant.","uses":["shade","wildlife","timber","nuts"],"ripening":null,"ripening_note":"Acorns ripen within one season, in fall; autumn leaves are brown to dark red","id_cues":"Leaves have 7 to 9 rounded, finger-like lobes with no bristles; bark is light ash-gray, chunky blocks on younger trees and scaly plates on old; acorn cap is warty and covers about a quarter of the nut; twigs lack corky ridges. Bur oak leaves can look similar, but its acorn cap is fringed and covers half or more.","habit":"Slow growing per NC State (USU says medium) and long-lived; pyramidal when young, broad and rounded with age. Its taproot goes deep, so it is hard to move; it dislikes soil compaction and can suffer wind damage.","bark":"Light ash-gray. Young and middle-aged trees have chunky, upright blocks; old trees have scaly plates fixed along one edge. Twigs are purple-gray to reddish-green and lack corky ridges; buds are small, round to oval, red-brown and clustered at the tip.","leaf":"Alternate, simple, 5 to 9 in long and 2 to 4 in wide, with 7 to 9 rounded, finger-like lobes and no bristles. Bright green above, paler and waxy beneath. Autumn color brown to dark red.","hardiness":"Zones 3-9 (Utah State Extension)","sources":[["Utah State University Extension: White Oak (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/oak-white"],["NC State Extension Plant Toolbox: Quercus alba","https://plants.ces.ncsu.edu/plants/quercus-alba/"],["Utah State University Extension: Bur Oak (TreeBrowser)","https://extension.usu.edu/treebrowser/catalog/oak-bur"]],"basis":"sourced","note":"USU: zones 3-9, medium growth, tolerates moderately high pH. NC State: slow growth, usually 80-100 ft (sheet: 50-80), chlorosis if pH too high. USU rates bur oak hardier (zone 2) and suited to high pH, drought, wind.","reviewed_on":"2026-10-17"},{"id":"comfrey","group":"Perennial","type":"Comfrey","kind":"genus","name":"Comfrey (variety not recorded)","aliases":["Comfrey","Symphytum","Bocking 14"],"inventory_rows":[16],"purchase_rows":[],"tagline":"Coarse hairy leaves; deep roots; mulch and bees; do not eat","summary":"Vigorous perennial with large, coarse, hairy leaves and drooping bell flowers, grown here for mulch and bee forage. It contains liver-toxic alkaloids, so do not eat it.","appearance":"Clump of upright leafy stems that pass 3 ft before flowering. Bocking types then collapse into a thick mat and regrow from the base. Drooping bell flowers open from early summer into fall: usually cream on common comfrey, blue to red-purple on Russian or Bocking types.","flavor_use":"Do not eat or brew it: comfrey carries pyrrolizidine alkaloids that can injure the liver, and oral products are banned or restricted in most countries. In the garden the leaf mat smothers weeds and adds organic matter, and the long bloom draws pollinators. Roots resprout, so removal is hard.","uses":["mulch","wildlife"],"ripening":null,"ripening_note":"Leaves grow from late May to hard frost in the upper Midwest; flowering starts late May or June and runs to fall","id_cues":"Large, coarsely hairy, lance-shaped leaves, long-stalked at the base and stalkless or running down the stem higher up; drooping bell flowers in one-sided clusters. Flower color is a weak cue: common comfrey is usually cream, Bocking blue to red-purple. Self-sown seedlings suggest common comfrey.","habit":"Herbaceous perennial from a deep, thick root system. Shoots start early in spring, keep adding stems all season and regrow fast after cutting. Bocking types stay in a clump and spread only from disturbed roots; common comfrey also spreads by seed.","bark":"Erect, leafy, fast-growing stems over 3 ft tall. Leaves on the flowering stems sit directly on the stem or run down it, and the stems end in one-sided clusters of drooping flowers.","leaf":"Basal leaves large, lance-shaped, long-stalked and coarsely hairy; stem leaves get smaller toward the top and are nearly stalkless or run down the stem.","hardiness":"Crowns and roots very winter hardy in northern Midwest; no zone given","sources":[["UW-Madison and UMN Extension: Comfrey (Alternative Field Crops Manual)","https://corn.agronomy.wisc.edu/Crops/Comfrey.aspx"],["UMN Extension: Bocking comfrey orchard understory cover","https://blog-fruit-vegetable-ipm.extension.umn.edu/2026/07/site-specific-strategies-bocking-14.html"],["NIH LiverTox (NCBI Bookshelf): Comfrey","https://www.ncbi.nlm.nih.gov/sites/books/NBK548370/"]],"basis":"sourced","note":"Variety not recorded: could be common comfrey or sterile Bocking 14. Sources disagree on seed set of common comfrey (UMN: heavy; Wisconsin bulletin: rare). The Wisconsin page dates from 1992.","reviewed_on":"2026-10-17"},{"id":"mint","group":"Perennial","type":"Mint","kind":"genus","name":"Mint (various)","aliases":["Mint various","Mentha"],"inventory_rows":[17],"purchase_rows":[],"tagline":"Square stems, paired scented leaves; spreads fast by runners","summary":"Spreading perennial herb with square stems and strongly scented, toothed leaves in opposite pairs. Spearmint and peppermint are the usual garden types, used for tea and flavoring, and mints spread aggressively by runners.","appearance":"Upright, leafy stems about 1 to 3 ft tall that knit into a spreading patch. Small pink, white or purple flowers form dense spikes in summer. Spearmint looks lighter green overall and peppermint darker green.","flavor_use":"Spearmint smells sweet and flavors tea, cold drinks and mint sauce; peppermint has a warmer, spicier scent and also goes in tea and flavoring. Plant in a 12 to 16 inch pot, or a bottomless pot sunk in the ground, and trim runners before they root.","uses":["herb","fresh","drying","cooking"],"ripening":null,"ripening_note":"Pick leaves any time while growing; cut stems for drying just as the first flowers appear","id_cues":"Square stems, opposite pairs of toothed leaves and a minty smell when crushed. Spearmint: nearly hairless, nearly stalkless leaves and a sweet scent. Peppermint: dark leaves on short stalks, reddish stems, spicier scent. Hybrids and other mints vary a lot, so treat these as rough guides.","habit":"Perennial that spreads by runners (stolons) and underground rhizomes, rooting at the nodes, and forms dense patches that can crowd out a bed. Prefers moist soil in sun to part shade; peppermint adapts to most conditions.","bark":"Square (4-angled) stems, upright to ascending, light green or tinged red, smooth or nearly so. They root at the nodes where they touch the soil.","leaf":"Opposite, simple, toothed leaves up to about 3.5 inches long. Spearmint: lighter green, pointed, slightly crinkled, nearly hairless and nearly stalkless. Peppermint: darker green, sharply toothed, on short leaf stalks. Crushed leaves smell strongly minty.","hardiness":"","sources":[["Univ. of Maryland Extension: Growing Mint in a Home Garden","https://extension.umd.edu/resource/growing-mint-home-garden"],["FloraFinder: Spearmint (Mentha spicata)","https://florafinder.org/Species/Mentha_spicata.php"],["Missouriplants.com: Peppermint (Mentha piperita)","https://www.missouriplants.com/Mentha_piperita_page.html"]],"basis":"sourced","note":"Inventory says 'various', so the 18 plants may include other mints or hybrids; the sources cover only spearmint and peppermint. Mints cross readily, so look and scent can blur.","reviewed_on":"2026-10-17"},{"id":"rhubarb","group":"Perennial","type":"Rhubarb","kind":"species","name":"Rhubarb","aliases":["Rheum rhabarbarum","Rhubarb"],"inventory_rows":[18],"purchase_rows":[],"tagline":"Spring stalk crop; big leaves; leaf blades poisonous","summary":"Long-lived perennial vegetable grown for its thick, sour leaf stalks, pulled in spring and cooked into pies, sauces and jams. The plant is large and the leaf blades are poisonous.","appearance":"Clump roughly 3 ft tall and 3 to 3.5 ft wide with big leaves on thick stalks that run from green to red by variety. Tall white-flowered seed stalks may form. A planting can last 10 to 15 years or more.","flavor_use":"Very sour raw, so cook the stalks with sugar into pies, sauces, jams and breads, or freeze or can them. Cut off and discard the leaf blades: they are toxic (oxalic acid) and can cause serious illness. Do not feed them to livestock.","uses":["cooking","canning","jelly"],"ripening":null,"ripening_note":"Stalks ready in spring at 10 to 15 in.; pick 6 to 10 weeks, to end of June (MN) or early July (OR); none in first 2 years","id_cues":"Big leaves on long, thick leaf stalks, green to red with the skin usually reddish, rising from a woody crown in early spring. Tall white-flowered seed stalks may form. Ornamental rhubarb (Rheum palmatum) has red foliage and inedible stalks, so confirm what you have before eating.","habit":"Clumping perennial from a thick woody crown with fibrous roots. Leaf stalks rise from crown buds each spring and the plant goes dormant in late summer and fall. Divide every 5 to 10 years, keep the soil well drained and moist, and cut off seed stalks as they appear.","bark":"The edible part is the leaf stalk (petiole), not a stem: thick, 10 to 15 inches long when ready, skin green to red and flesh pale to green. A separate tall seed stalk with white flowers can rise from the crown.","leaf":"Very large leaf blades on the long stalks, emerging from the crown in spring. The blades hold high levels of oxalic acid and are toxic to people and animals, so never eat them.","hardiness":"Hardy in USDA zone 4, worth trying in zone 3 (UMN)","sources":[["Utah State Univ. Extension: How to Grow Rhubarb in Your Garden","https://extension.usu.edu/yardandgarden/research/rhubarb-in-the-garden"],["UMN Extension: Growing rhubarb in home gardens","https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/growing-rhubarb"],["Oregon State Univ. Extension: Grow your own rhubarb (EC 797)","https://extension.oregonstate.edu/catalog/ec-797-grow-your-own-rhubarb"]],"basis":"sourced","note":"Variety not recorded; the workbook lists it on the Berry sheet though it is a vegetable. Sources differ on stalk oxalic acid (USU: almost none; UMN: high) and on when to start picking (year 2 or 3).","reviewed_on":"2026-10-17"},{"id":"raspberry","group":"Berry","type":"Raspberry","kind":"genus","name":"Raspberry (identity unconfirmed)","aliases":["Rasberry?","Rubus idaeus"],"inventory_rows":[14],"purchase_rows":[],"tagline":"Hollow fruit slips off core; 2-year prickly canes; suckers","summary":"Cane fruit whose berries slip off the core and come away hollow. Canes live two years, fruiting in the second, and red types spread by root suckers. This one bush is not confirmed as a raspberry.","appearance":"Perennial roots send up arching canes about 3 to 6 ft tall that tangle into thickets. Berries are clusters of tiny seeded drupelets, usually red but also yellow, black or purple. Summer-bearing types fruit on 2nd-year canes; fall-bearing types also fruit on first-year cane tips.","flavor_use":"Eaten fresh, or cooked, juiced and made into jam and pastries. Ripe berries soften and bruise quickly. Avoid windy spots or add a windbreak. Do not plant where tomatoes, peppers, potatoes, eggplant or strawberries grew in the past 5 years (Verticillium wilt).","uses":["fresh","cooking","juice","jelly"],"ripening":null,"ripening_note":"Summer-bearing types fruit early to mid summer; fall-bearing types also fruit late summer to early fall (Idaho bulletin)","id_cues":"Fruit test: a ripe raspberry pulls off its white core (plug) and is hollow; a blackberry keeps the core inside. Red raspberry leaves have 3 to 7 toothed leaflets, nearly white below, on arching reddish-green, bristly canes. Wild blackcaps have purple canes. Other Rubus overlap, so trust the fruit.","habit":"Perennial crown and roots with biennial canes: first-year primocanes bear leaves only (except fall-bearing types), second-year floricanes fruit and then die. Red types spread by root suckers into thickets; black and most purple types spread less.","bark":"Canes are round and arching, reddish green and bristly to slightly prickly, with brown, scaly bark on the oldest canes. Red raspberry canes do not root at the tips, and wild blackcap raspberry canes are purple.","leaf":"Leaves alternate, divided into 3 to 7 saw-toothed leaflets (5 to 8 in. overall), green above with nearly white undersides; leaf stalks carry very fine prickles or glandular hairs.","hardiness":"Red types: many hardy to -20F, a few to -25 to -30F (Idaho)","sources":[["Univ. of Idaho Extension: Growing Raspberries and Blackberries in the Inland Northwest","https://content-hub.uidaho.edu/api/public/content/96e1d3fad86d41718ac4d93713f1c66a?v=0e8a669f"],["Oregon State Univ. Extension: Growing Raspberries in Your Home Garden (EC 1306)","https://extension.oregonstate.edu/catalog/pub/ec1306"],["Virginia Tech Dendrology: Raspberry (Rubus idaeus)","https://dendro.cnre.vt.edu/dendrology/syllabus/factsheet.cfm?ID=424"]],"basis":"sourced","note":"Entered as 'Rasberry?' and not confirmed. Check the fruit (hollow cap or core inside), cane color and leaflets when it fruits; it could be a blackberry, hybrid berry, black raspberry or wild Rubus.","reviewed_on":"2026-10-17"},{"id":"serviceberry-eastern","group":"Berry","type":"Serviceberry","kind":"species","name":"Eastern serviceberry (Amelanchier canadensis)","aliases":["Amelanchier canadensis","Shadbush","Juneberry"],"inventory_rows":[],"purchase_rows":[117],"tagline":"Early; multi-stem shrub; sweet purple-black berries","summary":"Eastern native multi-stem shrub or small tree with showy white spring bloom and sweet, blueberry-like purple-black berries. It suckers, likes moist sites, and is often confused with other serviceberries.","appearance":"Berry-like pomes under 1 in across that turn from green to red to deep purple-black. Showy white flowers open before the leaves. The plant is a multi-stem shrub or small tree.","flavor_use":"Sweet and blueberry-like, eaten fresh or in jams, jellies and pies; birds often get there first. In full sun it wants moister soil, and NC State says the genus does not tolerate wind and yellows in alkaline soil, so a dry windy site is a stretch.","uses":["fresh","cooking","jelly","ornamental","wildlife"],"ripening":"Early","ripening_note":"May to June in North Carolina (NC State); expect later at a cold, high site","id_cues":"Multi-stem, suckering clump or thicket that blooms a bit later than downy serviceberry (A. arborea), the usual nursery mix-up. One main trunk points to arborea; 2-3 trunks and bronzed purple new leaves point to laevis. Leaves oblong, finely toothed, 1-3 in long; compare with the Saskatoon entry.","habit":"Large multi-stem shrub or small tree that suckers into clumps and thickets; 15 to 25 ft tall and 15 to 20 ft wide per NC State, 5 to 15 ft per JC Raulston. Wild plants grow in bogs, swamps and wet lowlands. Medium growth rate.","bark":"Smooth when young, developing long rough ridges and furrows with age. Twigs are hairy at first, reddish-brown in winter, with long, pointed reddish-purple buds.","leaf":"Alternate, oblong, finely toothed, 1 to 3 in long and under 1 in wide, rounded at base and tip with a small sharp point. Hairy when young, turning orange-red in fall.","hardiness":"Zones 3a to 8a (NC State Plant Toolbox)","sources":[["NC State Extension: Amelanchier canadensis (Plant Toolbox)","https://plants.ces.ncsu.edu/plants/amelanchier-canadensis/"],["JC Raulston Arboretum: Amelanchier (serviceberry) plant profile","https://jcra.ncsu.edu/horticulture/plant-profiles/details.php?ID=35"],["NC State Extension: Amelanchier (serviceberry) genus","https://plants.ces.ncsu.edu/plants/amelanchier/"]],"basis":"sourced","note":"Much nursery stock sold as canadensis is really A. arborea (JC Raulston), and hybrids blur the names, so the 25 plants may be mixed. Sources give different heights (5-15 vs 15-25 ft).","reviewed_on":"2026-10-17"},{"id":"serviceberry-western","group":"Berry","type":"Serviceberry","kind":"species","name":"Western serviceberry (Saskatoon)","aliases":["Western Serviceberry","Amelanchier alnifolia","Saskatoon","WS"],"inventory_rows":[],"purchase_rows":[],"seed_rows":[30],"tagline":"Mid; sweet purple-black berries; suckering thickets","summary":"Saskatoon, the native western serviceberry: a suckering shrub or small tree with early white bloom and sweet purple-black berries in July and August, eaten fresh or cooked.","appearance":"Berry-like pomes 6 to 11 mm long, purple-black with a faint blue-gray waxy bloom, sweet and fleshy with 4 to 10 small seeds, in terminal clusters. Shrub or small tree 3 to 26 ft tall, rounded when grown alone.","flavor_use":"Sweet berries eaten fresh or dried, or cooked into pies, jam, jelly, syrup and wine. Self-fruitful, and irrigation raises yield (USU). Wild stands may give a good crop only every 3 to 5 years (drought, spring frost, juniper rust).","uses":["fresh","cooking","jelly","drying","windbreak","wildlife"],"ripening":"Mid","ripening_note":"July to August across its range (NRCS); July 10 to Aug 19 in Montana east of the Divide (USFS)","id_cues":"Rounded to oval leaves with coarse teeth, short upright clusters of white flowers, purple-black berries with a blue-gray bloom, and rhizome sprouting into thickets. Native from the Pacific coast to the Rockies and northern plains. Compare leaf shape with the A. canadensis entry.","habit":"Often forms thickets, mats or clumps by sprouting from the root crown and rhizomes; a lone plant is rounded. Cultivars sucker from minimal (Honeywood) to many (Northline). Seedlings may need up to 5 years to bear. Relatively short-lived: sampled Montana plants averaged about 18 years old.","bark":"Thin, light brown tinged with red, smooth or shallowly fissured.","leaf":"Simple, alternate, deciduous, ovate to nearly round, coarsely toothed to below the middle (sometimes nearly entire), with 8 to 13 pairs of parallel side veins.","hardiness":"Cold hardy to zone 3 (Utah State Extension)","sources":[["USDA NRCS: Plant Guide, Saskatoon (Amelanchier alnifolia)","https://plants.usda.gov/DocumentLibrary/plantguide/pdf/pg_amal2.pdf"],["USDA Forest Service FEIS: Amelanchier alnifolia","https://www.fs.usda.gov/database/feis/plants/shrub/amealn/all.html"],["Utah State Univ. Extension: How to Grow Serviceberries in Your Garden","https://extension.usu.edu/yardandgarden/research/serviceberry-in-the-garden"]],"basis":"sourced","note":"Drought: USU says established plants survive on little water, but USFS says it does not tolerate prolonged drought (absent below 14 in/yr in Montana). NRCS warns that cultivars sold as alnifolia may be hybrids.","reviewed_on":"2026-10-17"},{"id":"rootstock-m111","group":"Apple","type":"Apple rootstock","kind":"rootstock","name":"M-111 rootstock (ungrafted)","aliases":["M 111 Rootstock","M.111","MM.111","Malling-Merton 111"],"inventory_rows":[56],"purchase_rows":[],"tagline":"Large-tree rootstock; well anchored; tolerates dry soil","summary":"M-111 (MM.111) is a Malling-Merton apple rootstock for large, well-anchored trees. These plants are ungrafted, so a named apple must be grafted on before the tree carries that cultivar's fruit.","appearance":"A grafted tree on M-111 gets large: about 75% of full size per NMSU, and listed as standard size in the Intermountain table. Vigorous cultivars tend to grow upright. The sources give no mature height or spread.","flavor_use":"Used as the root system under a grafted apple. It tolerates drought, suits a wide range of moist soils and resists woolly apple aphid. Fire blight and root rot resistance are only moderate, replant disease can hurt it, and it bears at a medium age and yield.","uses":["rootstock"],"ripening":null,"ripening_note":"","id_cues":"An ungrafted whip is all rootstock, and no source gives bark or leaf traits that separate M-111 from other apple rootstocks, so trust the tag (AL-Rstk M111). On a grafted tree, rootstock shoots usually have leaves unlike the cultivar's in size, shape, color, hairiness and stalks.","habit":"Trees grow upright if the cultivar is vigorous. Suckering is moderate in the Intermountain table, so shoots from the roots or low on the trunk are rootstock growth and usually differ from the grafted cultivar.","bark":null,"leaf":"No source describes M-111 leaves specifically. Rootstock leaves in general differ from the cultivar's in size, shape, color, tooth edges, hairiness, stalk thickness and length, and stipules at the stalk base, and may be flat or cupped.","hardiness":"Semi-hardy (Intermountain table); moderately winter hardy (NMSU)","sources":[["USU Intermountain Fruit Guide: Apple Rootstock table","https://intermountainfruit.org/fruit-tables/rootstock-apple"],["New Mexico State Univ.: Rootstocks for Size Control in Apple Trees (H-307)","https://pubs.nmsu.edu/_h/H307/index.html"],["eXtension Apples (Penn State): What do apple rootstock leaves look like?","https://apples.extension.org/what-do-apple-rootstock-leaves-look-like/"]],"basis":"sourced","note":"Ungrafted stock, not a cultivar: uses lists what a grafted apple would be for. NMSU gives about 75% of full size, while the Intermountain table classes it as standard. No source describes bark.","reviewed_on":"2026-10-17"},{"id":"rootstock-emla7","group":"Apple","type":"Apple rootstock","kind":"rootstock","name":"EMLA 7 rootstock (ungrafted)","aliases":["EMLA7 Apple Rootstock","M.7 EMLA","M.7"],"inventory_rows":[38],"purchase_rows":[],"tagline":"Semi-dwarf rootstock; heavy suckering; avoid heavy clay","summary":"EMLA 7 is the virus-free clone of East Malling's M.7, a semi-dwarf apple rootstock about 60% of standard size. These plants are ungrafted and need a named apple grafted on.","appearance":"A grafted tree on M.7 EMLA stays semi-dwarf, about 60% of a full-size tree (NMSU figure for M.7A). It stands without support, though some cultivars lean, and it bears early and heavily. The sources give no mature height.","flavor_use":"Used as the root system under a grafted apple. It does well on most soils except heavy clay and is moderately winter hardy. Suckering is heavy, and it is susceptible to collar rot; like other EM stocks it is not woolly apple aphid resistant.","uses":["rootstock"],"ripening":null,"ripening_note":"","id_cues":"An ungrafted whip is all rootstock, and no source gives bark or leaf traits that separate EMLA 7 from other rootstocks, so trust the tag (AL-Rtsk-EMLA7). Many shoots from the base of a grafted tree suggest a sucker-prone stock like this, and their leaves usually differ from the cultivar's.","habit":"Semi-dwarf and free-standing, though some cultivars lean. Suckering is rated high in the Intermountain table and NMSU calls it a known sucker producer; sucker shoots are rootstock growth that usually differ from the grafted cultivar.","bark":null,"leaf":"No source describes EMLA 7 leaves specifically. Rootstock leaves in general differ from the cultivar's in size, shape, color, tooth edges, hairiness, stalk thickness and length, and stipules at the stalk base, and may be flat or cupped.","hardiness":"Semi-hardy (Intermountain table); moderate winter hardiness (NMSU)","sources":[["USU Intermountain Fruit Guide: Apple Rootstock table","https://intermountainfruit.org/fruit-tables/rootstock-apple"],["New Mexico State Univ.: Rootstocks for Size Control in Apple Trees (H-307)","https://pubs.nmsu.edu/_h/H307/index.html"],["eXtension Apples (Penn State): What do apple rootstock leaves look like?","https://apples.extension.org/what-do-apple-rootstock-leaves-look-like/"]],"basis":"sourced","note":"Ungrafted stock: uses lists what a grafted apple would be for. The tables list M.7A/M.7a (an improved M.7), not EMLA 7 by name. NMSU says susceptible to collar rot; the Intermountain table rates root rot moderately resistant.","reviewed_on":"2026-10-17"}]};
(function (root) {
  'use strict';
  const profiles = root.CULTIVAR_LIBRARY.records;
  const byId = new Map(profiles.map(profile => [profile.id, profile]));
  const byInventoryRow = new Map();
  const byPurchaseRow = new Map();
  const bySeedRow = new Map();
  profiles.forEach(profile => {
    profile.inventory_rows.forEach(row => byInventoryRow.set(row, profile));
    profile.purchase_rows.forEach(row => byPurchaseRow.set(row, profile));
    (profile.seed_rows || []).forEach(row => bySeedRow.set(row, profile));
  });
  const GROUPS = ['Apple', 'Pear', 'Cherry', 'Peach', 'Apricot', 'Plum', 'Berry', 'Nut', 'Evergreen', 'Shade tree', 'Perennial'];
  const RIPENING_BANDS = ['Early', 'Mid', 'Late', 'Very late'];
  const GUIDE_PAGE = 'cultivar_guide.html';
  const groupNotes = new Map((root.CULTIVAR_LIBRARY.group_notes || []).map(note => [note.group, note]));
  // Shrubs, canes, and herbs have no trunk bark, so the field is labelled by what the plant has.
  const BARK_LABELS = { Berry: 'Stems and bark', Perennial: 'Stems' };

  function forInventoryRow(row) { return byInventoryRow.get(row) || null; }
  function forPurchaseRow(row) { return byPurchaseRow.get(row) || null; }
  function forSeedRow(row) { return bySeedRow.get(row) || null; }
  function profileById(id) { return byId.get(id) || null; }
  function groupNote(group) { return groupNotes.get(group) || null; }
  function guideHref(profile) { return `${GUIDE_PAGE}#${profile.id}`; }
  function barkLabel(group) { return BARK_LABELS[group] || 'Bark and twigs'; }
  // Habit, bark, and leaf notes that a source describes for this plant; null fields are skipped.
  function traits(profile) {
    return [['Habit', profile.habit], [barkLabel(profile.group), profile.bark], ['Leaves', profile.leaf]].filter(([, text]) => text);
  }
  function ripeningText(profile) {
    if (!profile.ripening) return profile.ripening_note || '';
    return profile.ripening_note ? `${profile.ripening} (${profile.ripening_note})` : profile.ripening;
  }
  // Native tooltips do not appear on touch screens, so pages also link each tree to its guide entry.
  function tooltip(profile) {
    return [`${profile.name}: ${profile.tagline}`, ripeningText(profile) ? `Ripens: ${ripeningText(profile)}` : ''].filter(Boolean).join('\n');
  }
  root.CultivarLibrary = { GROUPS, RIPENING_BANDS, GUIDE_PAGE, profiles, byId:profileById, forInventoryRow, forPurchaseRow, forSeedRow, groupNote, guideHref, barkLabel, traits, ripeningText, tooltip };
})(typeof window !== 'undefined' ? window : globalThis);
